INSERT INTO `lost_submarines` (`date_lost`, `date_lost_sort`, `fatalities`, `fatalities_num`, `id`, `boat_number`, `name`, `designation`, `class_info`, `last_captain`, `location`, `cause`, `loss_narrative`, `prior_history`, `display_order`, `photo_boat`, `created_at`, `updated_at`, `photo_captain`, `image1`, `image1_subtitle`, `image2`, `image2_subtitle`, `image3`, `image3_subtitle`, `image4`, `image4_subtitle`, `image5`, `image5_subtitle`, `image6`, `image6_subtitle`, `image7`, `image7_subtitle`, `image8`, `image8_subtitle`, `image9`, `image9_subtitle`, `image10`, `image10_subtitle`, `construction`) VALUES
('25 March 1915', '1915-03-25', '21', 21, 1, 'SS-23', 'F-4', 'USS F-4 (SS-23)', 'The F-4 was an F class submarine completed in May of 1913 by the Moran Company of Seattle, WA.  It had originally been named the Skate.  However, the name had been changed to F-4  in November of 1911, prior to launching.', 'LTJG Alfred L. Ede', 'Off Honolulu, Territory of Hawaii (TH)', 'Foundered', 'The boat foundered during local operations.  The cause is not clear.  The salvage team estimated that sea water was leaking through a lead seal and into the battery compartment.  Another possible cause was an unreliable reducer closing a Kingston valve.  A third possibility would be problems in the ballast tank air lines.\r\n\r\nOne sailor was left ashore as a watchman.  His duties were to receive any important news while the boat was at sea, and relay it to the captain on his return.  This was often done before radios were installed on boats.  His status regarding the sinking is often misstated as a survivor.\r\n\r\nIn August of 1915, F-4 was raised and towed using specially constructed pontoons.  She was then put into dry dock for examination.  In early September, she had to be removed from dry dock to accommodate three other F class boats that had been rammed by the USS Supply.  F-4 was still hanging from the pontoons.  She was then disconnected and left in the mud near Pearl Harbor.  In 1940, due to an expansion of the base, the F-4 was moved and buried near the submarine piers.', 'After commissioning and sea trials, F-4 operated with the First Submarine Group on the U. S. West Coast.  She participated in the development operations for the group.  In August of 1914, she was transferred, along with other F class boats, to the Territory of Hawaii (TH).  The boats were towed to Hawaii by armored cruisers.  It was during training operations there that the F-4 was lost.\r\n\r\nF-4 was the first commissioned U. S. submarine to be lost at sea.', 1, 'images/extracted/F-4_SS-23_boat.jpg', NULL, NULL, 'images/extracted/F-4_SS-23_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The F-4 was an F class submarine completed in May of 1913 by the Moran Company of Seattle, WA.  It had originally been named the Skate.  However, the name had been changed to F-4  in November of 1911, prior to launching.'),
('15 January 1916', '1916-01-15', 'Fatalities: 4.\r\nSeven other men were injured.', 4, 2, 'SS-25', 'E-2', 'USS E-2 (SS-25)', 'E-2 was an E class submarine completed in February of 1912 by Fore River Shipbuilding Company in Quincy, MA.  It had originally been named the Sturgeon. It had been changed to E-2 in November of 1911.', 'LT Charles M. Cooke Jr', 'New York Navy Yard', 'Explosion', 'E-2 entered dry dock in the New York Navy Yard in June of 1915.  On 15 January 1916, she suffered a violent explosion.  She had been conducting testing for a new nickel battery for The Edison Storage Battery Company when accumulated hydrogen exploded.  The hope had been to eliminate the danger of chlorine gas that would be generated when sea water came in contact with lead-acid batteries.  There were 32 men aboard at the time including the crew and contractors.\r\n\r\nIn March of 1916, E-2 was placed out of commission for use as a laboratory.  She was used for continued testing of the Edison Storage Battery.\r\n\r\nOn 25 March 1918, E-2 was recommissioned and served in training and experimental work.  She then conducted six anti-submarine patrols along the East Coast.  She received a commendation for two of her patrols which were unusually long for a boat of her size.\r\n\r\nShe sailed from New London to Norfolk where she was placed in ordinary in 1921 and decommissioned in 1922.\r\n\r\nLT Cooke was assigned as captain of the USS S-5 (SS-110).  That boat was lost in 1920.  See below.', 'After commissioning in 1912, E-2 served along the Atlantic coast and in the Gulf of Mexico.  She participated in training exercises until she sailed to the New York Navy Yard for overhaul in 1916.', 2, 'images/extracted/E-2_SS-25_boat.jpg', NULL, NULL, 'images/extracted/E-2_SS-25_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E-2 was an E class submarine completed in February of 1912 by Fore River Shipbuilding Company in Quincy, MA.  It had originally been named the Sturgeon. It had been changed to E-2 in November of 1911.'),
('24 July 1917', '1917-07-24', '7', 7, 3, 'SS-8', 'A-7', 'USS A-7 (SS-8)', 'A-7 was an A class submarine completed in October of 1903 by the Crescent Shipyard in Elizabeth, NJ.  It had originally been named the Shark but the name was changed in 1911.', 'LTJG Arnold Marcus', 'Manilla Bay', 'Explosion', 'A-7 was lost due to a gasoline explosion while on patrol in Manila Bay.  Shortly after her engine was overhauled, there was an incident when gasoline fumes ignited and exploded.  After battling the blaze, the captain ordered everyone topside and into the boats alongside.  LTJG Marcus and most of the crew succumbed to their injuries the next day.  The last remaining crewman died on 1 August.\r\n\r\nA-7 remained out of service after the explosion and was placed in ordinary on 1 April 1918.  She was decommissioned on 12 December 1918.  She was used as a target in 1921.', 'A-7’s first assignments were at the Naval Torpedo Station in Newport, RI.  In 1907, she was assigned to the First Submarine Flotilla at the U. S. Naval Academy.  Assignments included torpedo testing and research in the field of submarine warfare.\r\n\r\nIn 1908, she was taken to the New York Naval Yard where she, along with USS A-6 (SS-7) (Porpoise), were decommissioned and placed aboard the collier Caesar for the trip to Cavite in the Philippines.  They were recommissioned at Cavite on 14 August 1908.  There A-7 conducted training and underwent maintenance and repairs. During WW1, while still operating out of Cavite, A-7 carried out patrols of the entrance to Manila Bay.', 3, 'images/extracted/A-7_SS-8_boat.jpg', NULL, NULL, 'images/extracted/A-7_SS-8_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A-7 was an A class submarine completed in October of 1903 by the Crescent Shipyard in Elizabeth, NJ.  It had originally been named the Shark but the name was changed in 1911.'),
('17 December 1917', '1917-12-17', 'Fatalities: 19.\r\nThree men were rescued.', 19, 4, 'SS-20', 'F-1', 'USS F-1 (SS-20)', 'F-1 was an F class submarine completed in June of 1912 by Union Iron Works in San Francisco, CA.  It had originally been named the Carp but was renamed prior to commissioning.', 'LT Alfred E. Montgomery', 'Off Pt. Loma, San Diego', 'Collision', 'While engaged in exercises off Point Loma, USS F-1 and USS F-3 (SS-22) collided.  F-3 rammed F-1’s port side which was torn open forward of the engine room.  F-1 sank in seconds.  Only three men were rescued by the submarines operating with the F-1.  The other 19 were lost.\r\n\r\nThe cause was determined to be poor visibility due to fog and the difficulties maneuvering in close proximity to other submarines.  No individual was held to blame.\r\n\r\nLT Montgomery went on to a distinguished career in the Navy.  He continued to serve in various capacities in submarines, including command of the USS R-20 (SS-97) and PCO of USS S-32 (SS-137).  In 1922 he went to flight training and was designated a Naval aviator.  He served in various aviation assignments and commands until retiring as a vice admiral in 1951.', 'After commissioning and sea trials, F-1 was assigned to the First Submarine Group, Pacific Torpedo Flotilla.  She briefly held the record for the deepest dive, to 283 feet.  In late 1912, F-1 slipped her mooring at Port Watsonville and grounded on a nearby beach.  Two men died in the incident.\r\n\r\nFrom July of 1914 to November 1915, she was based in Honolulu for developmental operations.  F-1 was placed in ordinary from March of 1916 until June of 1917.  When she was recommissioned, F-1 was part of the Patrol Force, Pacific, based in San Pedro, CA until she was lost.', 4, 'images/extracted/F-1_SS-20_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'F-1 was an F class submarine completed in June of 1912 by Union Iron Works in San Francisco, CA.  It had originally been named the Carp but was renamed prior to commissioning.'),
('12 March 1920', '1920-03-12', 'Fatalities: 4.\r\nFour died trying to swim to shore, 22 were rescued.', 4, 5, 'SS-28', 'H-1', 'USS H-1 (SS-28)', 'H-1 was the lead boat of the H class submarines and was completed in December of 1913 by Union Iron Works of San Francisco, CA.  It had originally been named the Seawolf until the 1911 renaming.', 'LCDR James Webb', 'Magdalena Bay, Mexico', 'Grounding', 'On 6 January 1920, H-1 began her journey back to San Pedro from New London, CT.  She transited the Panama Canal on 20 February.  On 12 March, she ran aground on a shoal off Magdalena Bay, Baja California.  Four men, including the captain, died trying to reach shore.  The diesel freighter Mazatlán tried, without success, to pull the boat off the rocks.  The Mazatlán then carried the 22 survivors to San Pedro arriving on 18 March.  The repair ship USS Vestal pulled H-1 off the rocks on 24 March, but the submarine sank in less than an hour.\r\n\r\nFurther salvage attempts were abandoned.  H-1 was sold for scrap in June of 1920, but was never recovered.  The wreck was located and identified in 2019.', 'H-1 was first assigned to Torpedo Flotilla 2, Pacific Fleet.  Based in San Pedro, CA, she travelled the West Coast from Southern California to lower British Columbia. She frequently sailed with sister ships USS H-2 (SS-29) and USS H-3 (SS-30).  In October of 1917, she sailed to New London, CT.  There she patrolled Long Island Sound for the rest of WW1.  She often patrolled with officer students from the Submarine School.', 5, 'images/extracted/H-1_SS-28_boat.jpg', NULL, NULL, 'images/extracted/H-1_SS-28_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'H-1 was the lead boat of the H class submarines and was completed in December of 1913 by Union Iron Works of San Francisco, CA.  It had originally been named the Seawolf until the 1911 renaming.'),
('1 September 1920', '1920-09-01', '0', 0, 6, 'SS-110', 'S-5', 'USS S-5 (SS-110)', 'The S-5 was an S-4 class submarine completed in March of 1920 by the Portsmouth Naval Shipyard in Kittery, Maine.', 'LCDR Charles M. Cooke Jr', 'Delaware Capes', 'Foundered', 'S-5 was undergoing full power sea trials in the Atlantic Ocean off the Delaware Capes.  She had begun a test dive when water began to flood the submarine.  In those days, the main induction valve was not closed until the engines were shut down.  However, the chief of the watch was distracted and was late in shutting the valve.  When he realized what had happened, he quickly jerked the valve lever which jammed the valve open.\r\n\r\nWater had entered multiple compartments.  However, the valves in most compartments had been shut.  That still left the torpedo room valve open and the space flooded.  The bilges had settled on the bottom making it impossible to pump out the other spaces.  The boat was on the bottom in 180 feet of water with little hope of rescue.\r\n\r\nHowever, the crew reasoned that, if they could move water forward and blow ballast aft, they might be able to get the stern far enough out of the water to be seen.  However, there was a danger of chlorine gas if they moved sea water into the battery compartment.  The crew hoped to move water into the battery compartment and then quickly close the watertight door before too much chlorine gas reached the rest of the boat.  The basic plan worked, sending approximately 17 feet of the stern out of the water.\r\n\r\nThe crew then struggled, over the next 36 hours, to cut a hole of about three inches in diameter in the hull.  They were then able to get the attention of the passing steamship SS Alanthus. With help from the Alanthus and the SS General G. W. Goethais they were able to cut a larger hole, about two feet in diameter, in the hull.  The entire crew was able to escape the next day.  Later attempts to refloat and tow S-5 to shallow waters failed.\r\n\r\nLCDR Cooke would continue to serve in various assignments until he retired in 1948 as a vice admiral.', NULL, 6, 'images/extracted/S-5_SS-110_boat.jpg', NULL, NULL, 'images/extracted/E-2_SS-25_captain.jpg', 'images/extracted/S-5_SS-110_extra1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The S-5 was an S-4 class submarine completed in March of 1920 by the Portsmouth Naval Shipyard in Kittery, Maine.'),
('28 October 1923', '1923-10-28', 'Fatalities: 3\r\n16 escaped, which included Breault and Brown.', 3, 7, 'SS-66', 'O-5', 'USS O-5 (SS-66)', 'O-5 was an O class submarine completed in June of 1918 by Fore River Shipbuilding Company in Quincy, MA.', 'LT Harrison Avery', 'Off Bahia Limon, Panama', 'Collision', 'On 28 October 1923, O-5 was preparing to enter the Canal when she was rammed by the United Fruit Company steamer Abangarez.  The O-5 had a ten-foot hole opened on her starboard side.  She sank quickly in 42 feet of water.  14 men escaped from the submarine initially and three died.  Two others were trapped forward in the torpedo room.\r\n\r\nSalvage efforts began immediately.  A day later, after a couple failed attempts, a tug, local engineers and divers were able to lift the bow far enough to get it out of the water.  The two trapped sailors were then able to escape through the torpedo room hatch.\r\n\r\nOne of the trapped men, Torpedoman Second Class Henry Breault could have escaped when the boat first went down.  However, he chose to assist a shipmate,  Lawrence Brown, and remained inside the sunken submarine.  For his \"heroism and devotion to duty\" on this occasion, Breault was awarded the Medal of Honor.  He was the first submariner to receive the Medal of Honor and the only enlisted man to receive the award for heroism while serving as a submariner. Seven submarine commanders received the award during World War II.\r\n\r\nThe O-5 was initially held responsible for the collision.  That would be reversed by a Court of Naval Inquiry.  However, in 1932, a federal judge ruled that the O-5 was, in fact, responsible.', 'O-5 was one of a class of 16 boats designed for coastal defense in WW1.  During the final months of that war, O-5 patrolled off the East Coast, from Cape Cod MA to Key West, FL.  On 6 October 1918, she was in the Brooklyn Navy Yard when LTJG William J. Sharkey noticed that the batteries were giving off toxic gasses.  He notified the captain, LCDR George Trevor, and they both went to investigate.  The batteries then exploded.  LTJG Sharkey was killed outright and LCDR Trevor was fatally injured.  LTJG Sharkey was awarded the Navy Cross.\r\n\r\nAfter repairs, O-5 departed on 3 November 1918 for European waters as part of a 20-submarine contingent.  However, before the boats reached the Azores, the war had ended.  The O-5 was then assigned to duties at the Submarine School at New London.  In 1923, O-5 was assigned to Coco Solo in the Panama Canal Zone for a brief tour.', 7, 'images/extracted/O-5_SS-66_boat.jpg', NULL, NULL, 'images/extracted/O-5_SS-66_captain.jpg', 'images/extracted/O-5_SS-66_extra1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'O-5 was an O class submarine completed in June of 1918 by Fore River Shipbuilding Company in Quincy, MA.'),
('25 September 1925', '1925-09-25', 'Fatalities: 33.\r\nThree other men survived.', 33, 8, 'SS-162', 'S-51', 'USS S-51 (SS-162)', 'S-51 was an S-48 class submarine completed in June of 1922 by the Lake Torpedo Boat Company in Bridgeport CT.', 'LT Rodney Dobson', 'Near Block Island', 'Collision', 'S-51 was sailing near Block Island, on the surface with running lights on.  The merchant steamship SS City of Rome spotted the single masthead light of S-51 but couldn’t determine the direction of the boat.  S-51 spotted the masthead light and green running light of the City of Rome.  S-51 held her course as she was required to do by the rules of that time.  She had the right of way and was to remain on a predictable course.\r\n\r\nCity of Rome altered course and could then see the red running light of S-51.  At that point, City of Rome realized that the ships were on collision courses.  The steamship turned and backed her engines, but it was too late.  It was 22 minutes after City of Rome first spotted S-51’s masthead light when the steamship rammed the submarine.  Only three of the submarine crew escaped before the boat sank.\r\n\r\nThe courts found both vessels to be at fault.  The City of Rome was faulted for not slowing when in doubt about the other vessel’s course and for not signaling her change in course.  S-51 was faulted for not having proper running lights.\r\n\r\nThe Navy claimed that it was not reasonable for submarines to follow the rules of the road because of their inherent limitations.  The judge disagreed and suggested that if that were true, perhaps submarine operations needed to be conducted in areas without other shipping.\r\n\r\nNOTE: One challenge for submarines in peacetime is that they are low to the water and difficult to see.  Even if the running lights can be seen, the configuration of the lights appears to be that of a much smaller vessel, such as a fishing boat.  Running lights are rarely used during wartime.', 'S-51 was initially based at New London, CT as part of Submarine Division 4 (SUBDIV4).  She participated in routine peacetime training.  In January of 1924, she sailed to the Panama Canal Zone to participate in winter fleet maneuvers.  After visiting various islands in the Caribbean, S-51 returned to New York City on 30 April 1924.  She then resumed her normal training cycles.', 8, 'images/extracted/S-51_SS-162_boat.jpg', NULL, NULL, 'images/extracted/S-51_SS-162_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'S-51 was an S-48 class submarine completed in June of 1922 by the Lake Torpedo Boat Company in Bridgeport CT.'),
('17 December 1927', '1927-12-17', '40', 40, 9, 'SS-109', 'S-4', 'USS S-4 (SS-109)', 'S-4 was the first of the S-4 class submarines, completed in November of 1919 by the Portsmouth Naval Shipyard in Kittery Maine.', 'LCDR R. K. Jones', 'Off Provincetown, MA', 'Collision', 'S-4 was surfacing after a submerged run over a measured mile when she was accidentally rammed by the Coast Guard vessel Paulding while on rum patrol.  Paulding stopped and put over small boats.  They reported only a small amount of oil and bubbles, which lent some hope for possible rescue.\r\n\r\nThere were six men alive in the forward torpedo room.  They were communicating with the rescue team by tapping on the hull.  However, bad weather prevented their rescue before the oxygen in the boat ran out.  As a result, all 40 members of the crew were lost.\r\n\r\nS-4 was raised in March of 1928.  It would then be used as a test vessel for rescue operations.  She would be decommissioned in 1933 and scuttled in 1936.', 'After acceptance, S-4 sailed to Havana, Cuba for operations in the Gulf of Mexico.  She was then transferred to operations off the coast of New England.  In November of 1920, she sailed to meet her assigned unit, Submarine Division 12, to embark on what was to be the longest voyage by submarines of the time.  They sailed from New England, via the Panama Canal and Pearl Harbor, to Cavite in the Philippines.  The boats arrived at Cavite on 1 December 1921.\r\n\r\nS-4 operated out of Cavite until 1924.  From there, the division was assigned to the U. S. West Coast, arriving at Mare Island, CA on 30 December 1924.  For the next few years, S-4 operated primarily from San Francisco, San Pedro and San Diego.  In early 1927, she sailed to the Canal Zone where she operated for a couple months before sailing on to New London, CT.  For the remainder of that year, she operated off the New England coast.', 9, 'images/extracted/S-4_SS-109_boat.jpg', NULL, NULL, 'images/extracted/S-4_SS-109_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'S-4 was the first of the S-4 class submarines, completed in November of 1919 by the Portsmouth Naval Shipyard in Kittery Maine.'),
('23 May 1939', '1939-05-23', 'Fatalities: 26.\r\nThis total included two civilian technicians.  33 men were rescued.', 26, 10, 'SS-192', 'Squalus', 'USS Squalus (SS-192)', 'Squalus was a Sargo class submarine completed in March of 1939 by the Portsmouth Naval Shipyard in Kittery, Maine.', 'LT Oliver Naquin', 'Off Kittery, Maine', 'Foundered', 'Squalus was still in post-construction trials and was conducting a high-speed dive.  The dive appeared to be going normally.  The “Christmas tree” was all green, indicating that the critical openings and valves were shut.  An overpressure in the boat held.  Suddenly, Captain Naquin felt an increased pressure and he soon received the report of flooding in the engine rooms.\r\n\r\nThe captain ordered all watertight doors closed.  Five men were able to scramble from the after battery compartment into the control room before that watertight door was secured.  17 others tried in vain to seal themselves in the after torpedo room.  Nine others drowned in the engine rooms and after battery.  The survivors were able to confirm that all four spaces aft of the control room had been flooded.\r\n\r\nThe next danger appeared in the form of the forward battery.  It was draining rapidly and was in danger of exploding.  One of the electricians crawled into the battery space, in the dark, and pulled the disconnect links.  He saved the submarine but likely at the cost of permanent damage to his vision.  The submarine was now cold, dark and on the bottom in 240 feet of water.\r\n\r\nThe captain divided the survivors into two groups.  One was in the warmer control room and the other in the forward torpedo room.  Momsen lungs were issued in case the crew would have to make free ascents to the surface.  However, the captain was confident that someone would be searching for them.\r\n\r\nWhen the officials in Portsmouth realized the Squalus was overdue, they quickly sent USS Sculpin (SS-191) to search for her sister.  Sculpin had been built before Squalus and had just finished trials.  Sculpin headed for the last reported location of the Squalus.  Unfortunately, the coordinates had been transcribed incorrectly.  However, Squalus had been sending up red signal flares and Sculpin saw the smoke.  Sculpin was able to locate the buoy Squalus had released.  The two boats had just begun to communicate by phone when the cable snapped.  However, Sculpin had located Squalus and knew that some men inside were alive.\r\n\r\nThe submarine rescue vessel USS Falcon (ASR-2) had been dispatched from New London, CT with a McCann rescue bell on board.  Also aboard were the inventers, LCDR Swede Momsen and CDR Allan McCann, since the bell had only been used in training.  The Falcon arrived at the site at 04:30 the next morning and was moored over the Squalus by 08:00.  A diver in a hard hat suit reached the Squalus within the next hour and attached a downhaul cable to the forward torpedo room escape hatch.\r\n\r\nIt then took four trips with the diving bell to bring up the 33 survivors.  On the last trip up, the downhaul cable frayed and jammed the winch.  They lightened the rescue bell by adding air to it and pulled the cable up by hand.  The 33 men who survived the sinking were now safe, 40 hours after the boat had sunk.\r\n\r\nIt took almost four months to salvage the Squalus.  The boat was towed back to port on 13 September 1939.  Then she was overhauled at Portsmouth, renamed the USS Sailfish (SS-192) and recommissioned.  The Sailfish would complete 12 war patrols before becoming a training boat in New London at the end of January, 1945.  She was credited with seven enemy vessels sunk for 45,000 tons.\r\n\r\nOne of the ships in that total was the IJN carrier Chuyo.  Unfortunately, at the time Chuyo was sunk, she was carrying 22 of the survivors from the Sculpin sinking and only one of them survived.\r\n\r\nSailfish’s conning tower is a memorial at the Portsmouth Naval Shipyard.\r\n\r\nAlthough many of the surviving crew would return to submarines, LT Naquin would not.  After the sinking of the Squalus, he was assigned to the battleship USS California (BB-44) where he survived the attack on Pearl Harbor.  He was then assigned to the heavy cruiser USS New Orleans (CA-32) where he earned a Bronze Star in the Battle of Tassafaronga for guiding the badly damaged ship to safety at Tulagi harbor and saving it.  He retired from the Navy as a rear admiral in 1955.', NULL, 10, 'images/extracted/Squalus_SS-192_boat.jpg', NULL, NULL, 'images/extracted/Squalus_SS-192_captain.jpg', 'images/extracted/Squalus_SS-192_extra1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Squalus was a Sargo class submarine completed in March of 1939 by the Portsmouth Naval Shipyard in Kittery, Maine.'),
('20 June 1941', '1941-06-20', '33', 33, 11, 'SS-70', 'O-9', 'USS O-9 (SS-70)', 'O-9 was an O class submarine completed in July of 1918 by the Fore River Shipbuilding Company of Quincy., MA.', 'LT Howard Abbott', 'Off the Isle of Shoals', 'Foundered', 'On the morning of 19 June 1941, O-9 along with USS O-6 (SS-67) and USS O-10 (SS-71) left New London for test depth diving.  The next day, test dives were completed first by O-6 and then by O-10.  O-9 began her dive at 08:37.  When O-9 had not returned to the surface by 10:32, the search began immediately.  Other submarines and the rescue vessel USS Falcon (ASR-2) joined the search.  That evening, debris with markings from O-9 was recovered in water that was 440 feet deep.\r\n\r\nDivers went down on 21 and 22 June, setting endurance and depth records.  However, it was to no avail; there could not have been any survivors.  Rescue operations were cancelled on 22 June since O-9 had a test depth of just 200 feet and was on the bottom well past crush depth.  Memorial services were conducted that day.', 'During the final months of WW1, O-9 completed coastal patrols in the Atlantic, searching for U-boats.  She departed Newport, RI for Britain on 2 November 1918.  However, the war ended before O-9 arrived.  After WW1 she trained submarine crews at the Submarine School in New London.  In 1924, she was assigned to Coco Solo in the Panama Canal Zone.  While there, she was reclassified as a second line submarine.\r\n\r\nO-9 returned to New London in January of 1930 and reverted to a first line boat.  She was decommissioned in June of 1931 but remained on the Naval Vessel Register.  On 14 April 1941, she was one of ten O-boats recommissioned to serve as training boats.  However, O-9 required extensive work and continued to suffer mechanical problems, which may have contributed to her foundering.\r\n\r\nSection 2, Submarines Lost During WW2', 11, 'images/extracted/O-9_SS-70_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'O-9 was an O class submarine completed in July of 1918 by the Fore River Shipbuilding Company of Quincy., MA.'),
('10 December 1941', '1941-12-10', 'Fatalities: 5.\r\nA total of five men were lost, one from Seadragon and four from Sealion.', 5, 12, 'SS-195', 'Sealion', 'USS Sealion (SS-195)', 'Sealion was a Sargo class submarine completed in November of 1939 by the Electric Boat Company in Groton, CT.', 'LCDR Richard G. Voge', 'Cavite Naval Base in the Philippine Islands', 'Bombed in the harbor', 'The first submarine casualty of World War 2 was an officer on the USS Seadragon (SS-194) which was next to Sealion and also in overhaul.  He was killed when the first bomb hit the Sealion and sent a fragment through the conning tower of the Seadragon, striking him.  Four members of the Sealion’s crew were lost when a second bomb penetrated the hull and exploded in the after engine room.\r\n\r\nThe Sealion was damaged beyond the capability of the local shipyard to repair within the combat zone.  Classified materials were destroyed.  On 25 December, three depth charges were detonated inside the hull.  The Sealion was then left in place.  It was found nearby, and in nearly the same condition, at the end of the war.\r\n\r\nSeadragon was towed out into Manila Bay.   After temporary repairs, she was able to get underway and, with an escort, make it to Surabaya.  She would later make history when her pharmacist mate successfully performed the first appendectomy on an American submarine.\r\n\r\nLCDR Voge, captain of the Sealion, would later serve as captain of the recommissioned USS Sailfish (SS-192).  After completing five war patrols on that boat, he served with distinction on the staff of the Commander of the Submarine Force, U. S. Pacific Fleet, Admiral Charles Lockwood.  Voge retired as a rear admiral.\r\n\r\nLT Reich, the executive officer (XO) of the boat would later assume command of the new Sealion, also known as Sealion II (SS-315), in 1944.  Four of the torpedoes used by Sealion II to sink the IJN carrier Kongo carried the names of the four sailors lost in the bombing at Cavite: Foster, O’Connell, Paul and Ogilvie.  The new Sealion II joined the USS Pampanito (SS-383)  in the rescue of the British and Australian soldiers in September of 1944.', 'In the spring of 1940, Sealion sailed with other submarines for the Philippine Islands where she joined the U. S. Asiatic Fleet.  She operated between Luzon and the Sulu Archipelago.  She then prepared for a routine overhaul which began on 8 December 1941.  Two days later, she was damaged beyond repair by bombs.\r\n\r\nThis USS Sealion (SS-195) made no war patrols and, therefore, would not have sunk any enemy shipping.', 12, 'images/extracted/Sealion_SS-195_boat.jpg', NULL, NULL, 'images/extracted/Sealion_SS-195_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Sealion was a Sargo class submarine completed in November of 1939 by the Electric Boat Company in Groton, CT.'),
('20 January 1942', '1942-01-20', '0', 0, 13, 'SS-141', 'S-36', 'USS S-36 (SS-141)', 'S-36 was an S-18 class submarine completed in April of 1923 by Bethlehem Shipbuilding in San Francisco.', 'LT John R. McKnight', 'Taka Bakang Reef in Makassar Strait west of Southern Celebes', 'Grounding', 'S-36 began her second patrol on 30 December, 1941 from Mariveles.  She claimed the sinking of a 5,000-ton transport in a daring raid in Calapan Harbor early in this patrol.  She was still experiencing many equipment failures.  On 15 January, S-36 was attacked by an enemy destroyer which resulted in more problems.  On 17 January, she was directed to proceed to Surabaya, Java.  En route, she ran aground on the reef on 20 January.  This was likely due, at least in part, to the inadequate charts we had of the Western Pacific at that time.\r\n\r\nThe forward battery compartment flooded and it was feared that the compartment contained chlorine gas.  However, upon further investigation, the captain thought the boat still could be salvaged.\r\n\r\nMultiple attempts to free the boat were unsuccessful.  When a Dutch ship arrived to assist, and the situation had gotten progressively worse, the captain decided it was time to abandon ship and destroy it.  The boat was actually scuttled the next day, 21 January.  All of the crew were taken safely to Surabaya.', 'Following initial sea trials, S-36 briefly operated on the U. S. West Coast.  In September of 1925, she departed for the Cavite Nay Yard on Luzon in the Philippines.  She remained there for the next 16 years as part of the U. S. Asiatic Fleet, conducting exercises and deployments to China and the Dutch East Indies.  On 2 December 1941, her planned overhaul was cancelled.\r\n\r\nHer first war patrol began on 8 December 1941 and was in the area between Cape Bolinao and San Fernando.  Many problems developed including air leaks, steering failures and communications issues.  On 16 December, after none of her previous messages had gotten through, S-36 was ordered to Mariveles at the entrance to Manila Bay.  There she was able to make repairs and replenish stores before beginning her next patrol.\r\n\r\nS-36 was lost on her second war patrol.  She was not credited with any sinkings.', 13, 'images/extracted/S-36_SS-141_boat.jpg', NULL, NULL, 'images/extracted/S-36_SS-141_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'S-36 was an S-18 class submarine completed in April of 1923 by Bethlehem Shipbuilding in San Francisco.'),
('24 January 1942', '1942-01-24', 'Fatalities: 46.\r\nThe commanding officer, executive officer and one enlisted man survived.  Three other men were in the base hospital at the time and were spared.', 46, 14, 'SS-131', 'S-26', 'USS S-26 (SS-131)', 'S-26 was an S-1 class submarine completed in October of 1923 by Bethlehem Shipbuilding in Quincy, MA.', 'LCDR Earl Hawk', 'Gulf of Panama', 'Collision', 'S-26 left Balboa (Panama City) in the Canal Zone on her second war patrol accompanied by the submarines USS S-21 (SS-126), USS S-29 (SS-134) and USS S-44 (SS-155).  They were escorted by the patrol craft PC-460.  Running lights were not being used in wartime conditions.  At 22:10, the PC-460 signaled by lamp that she was leaving the group.  Apparently, only S-21 received the message.  The escort then turned to leave the formation.  It appears that, for some reason, the PC turned more than 180 degrees and went past the course which would have been parallel and reciprocal.  Therefore, the patrol craft was now crossing through the formation of submarines she was escorting.\r\n\r\nAt 22:23, PC-460 collided with S-26 in the darkness.  The patrol craft hit the S-26 on the starboard side of the torpedo room.  The boat sank within seconds.  The three survivors were on the bridge at the time.  Salvage operations began immediately, but when divers reached the boat there were no signs of life.  Because of the depth of the water, neither rescue or salvage of the S-26 was possible.\r\n\r\nCaptain Hawk went on to a successful command in the USS Pompon (SS-267).  The executive officer, LT Robert E. M. Ward went on to successful commands in the USS Sailfish (SS-192) and then the USS Sea Leopard (SS-483).', 'S-26 operated from New London from 1923 to 1925, visiting the U. S. Virgin Islands and Hawaii.  From 1925 to 1930, she operated out of West Coast ports and at times served in the Panama Canal area.  In December of 1930, S-26 was transferred to Hawaii.  She served at Pearl Harbor until October of 1938 when she returned to New London.\r\n\r\nS-26 was in reserve with a partial crew from April of 1939 to July of 1940.  She resumed full duty at that point, with duties out of New London and hydrogen tests at Washington D. C.\r\n\r\nAfter the attack on Pearl Harbor on 7 December 1941, she departed New London and arrived at Coco Solo, Panama on 19 December.  She then conducted her first war patrol in the Pacific, but encountered no enemy forces.\r\n\r\nS-26 was lost on her second war patrol.  She was not credited with any sinkings.', 14, 'images/extracted/S-26_SS-131_boat.jpg', NULL, NULL, 'images/extracted/S-26_SS-131_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'S-26 was an S-1 class submarine completed in October of 1923 by Bethlehem Shipbuilding in Quincy, MA.'),
('Likely 11 February 1942', '1942-02-11', '58', 58, 15, 'SS-174', 'Shark', 'USS Shark (SS-174)', 'Shark was a Porpoise class submarine completed in January of 1936 by the Electric Boat Company in Groton, CT.', 'LCDR Lewis Shane Jr', 'Likely the northern Celebes', 'Uncertain.  Likely ASW forces', 'On her third patrol, Shark was assigned to the Ambon Island area to guard against an expected invasion.  She reported making an unsuccessful attack on a destroyer which, in turn, depth charged Shark.  On 7 February, Shark reported an unsuccessful attack on a cargo ship that was riding high in the water and likely empty.  This last report resulted in a caution from Surabaya against sending too many messages containing little useful information but perhaps giving away her location.  No further messages were ever received from Shark.\r\n\r\nOn 8 February, Shark was ordered to Makassar Strait via the north coast of Celebes.  Japanese records report three attacks on American submarines in the area over the next few weeks.  An attack on 11 February is deemed the most likely cause of the loss of Shark, but this is not certain.  In the report of that attack, the Japanese stated that they heard voices in the water.  However, they made no attempt to pick up any survivors.', 'After commissioning, Shark spent a year and a half in training exercises.  In December of 1938, she was transferred to Pearl Harbor.  In December of 1940, she was transferred to Manila as part of the U. S. Asiatic Fleet.  She departed Manila on 9 December 1941 and was at sea at the outbreak of hostilities.  Her first patrol was in Tayabas Bay.  She was there for about ten days until recalled to transfer Admiral Thomas Hart, Commander-in-Chief of the U. S. Asiatic Fleet, from Manila to Surabaya, Java.  Shark received credit for her second war patrol for this mission.  Shortly after completing the mission, Shark reported seeing a torpedo from an enemy submarine miss her.\r\n\r\nShark was lost on her third war patrol.  She was not credited with any sinkings.', 15, 'images/extracted/Shark_SS-174_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Shark was a Porpoise class submarine completed in January of 1936 by the Electric Boat Company in Groton, CT.'),
('3 March 1942', '1942-03-03', 'Fatalities: 6.\r\nThe crew of 59 survived the scuttling but five or six crewmen died in captivity.', 6, 16, 'SS-176', 'Perch', 'USS Perch (SS-176)', 'Perch was a Porpoise class submarine completed in November of 1936 by the Electric Boat Company in Groton, CT.', 'LCDR David A. Hurt', 'Makassar Strait', 'Scuttled', 'On her second patrol, on 25 February 1942, Perch made a night surface attack on a small convoy.  However, the enemy’s fire was accurate and Perch herself was damaged.  On 1 March, Perch was spotted by a pair of Japanese destroyers.  The submarine dove and was another victim of poor charts.  She buried her bow in the mud at just 140 feet, was subjected to a heavy depth charging and suffered severe damage.  The destroyers became convinced that Perch was sunk.  Early the next morning, after repairs were made, Perch surfaced and was again spotted.  She dove and again hit the bottom, this time at 200 feet.  Another severe depth charging and more damage followed until the destroyers were again convinced that Perch was sunk.\r\n\r\nAfter more repairs, Perch surfaced and headed towards the nearest friendly port.  However, she could only make five knots speed on one engine and was still leaking badly.  The captain was feeling very vulnerable and tried another dive.  However, so much water poured in that there was danger of sinking.  While repairs were being attempted, she was spotted again.  At this point the captain decided there was just one way to save his men.  He ordered the crew to abandon the ship and had the boat scuttled.\r\n\r\nAlthough the entire crew was rescued, sources differ as to the number of the crew that died in captivity.  “The Last Patrol” and “U. S. Submarine Losses, World War II” both indicate nine men died in captivity.  The “history.navy.mil.com” website identifies three of those nine sailors, who were thought to have died, as having been liberated separately at the end of the war.  “Wikipedia” indicates that five of the crew died of malnutrition in captivity but does not explain the difference.\r\n\r\nIn any case, the crew was treated badly.  They were first taken to the infamous Ofuna interrogation camp.  This was an illegal interrogation camp where most submariners and pilots began their internment.  The Japanese normally did not notify the U. S. of prisoners in Ofuna until they were transferred to other camps.  Even though the men from Perch were later transferred to work in the Ashio mines, most of them were not reported to the U. S. as captured until the end of the war.', 'After commissioning and shakedown trial, Perch was assigned to the U S. Pacific Fleet.  She participated in fleet exercises and did some survey work in the Aleutian Islands.  In October of 1939, She was transferred to the Philippines.  In 1940 she made a summer cruise to China.  She spent 1941 around the Philippines.  A week before the attack on Pearl Harbor, Perch had escorted two transports carrying the 4th Marine regiment from China to the Philippines.\r\n\r\nPerch was in the Cavite Navy Yard when the war broke out.  She departed on the night of 8 December (the same day as the attack on Pearl Harbor due to the International Date Line) for her first war patrol.  During this patrol, she fired torpedoes at a large freighter, but missed.  Later in the patrol she fired torpedoes at another freighter and two hit the target.  Although the maru was never heard from again, Perch did not get credit for the sinking.\r\n\r\nPerch was lost on her second war patrol.  JANAC did not credit her with any sinkings.', 16, 'images/extracted/Perch_SS-176_boat.jpg', NULL, NULL, 'images/extracted/Perch_SS-176_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Perch was a Porpoise class submarine completed in November of 1936 by the Electric Boat Company in Groton, CT.'),
('19 June 1942', '1942-06-19', '0', 0, 17, 'SS-132', 'S-27', 'USS S-27 (SS-132)', 'S-27 was an S-1 class submarine completed in January of 1924 by Bethlehem Shipbuilding Company in Quincy, MA.', 'LT Herbert Jukes', 'St. Makarius Point, off Amchitka Island in the Aleutians', 'Grounding', 'On 18 June 1942, S-27 was surfaced after long daylight hours in order to recharge her battery.  Because of the poor visibility, no one noticed that the currents had pushed the boat five nautical miles toward the shore.  S-27 moved ahead slowly but at 00:43 on 19 June, she was on a solid rock reef.  Attempts to free the boat were not successful.  With breakers crashing over the boat, the captain ordered the crew to abandon ship.  At 15:50, the last group left the boat after destroying classified materials.\r\n\r\nThe 49-man crew all reached safety in groups of six using one small rubber boat.  They then found an abandoned village.  Members of the crew returned to the boat to retrieve supplies until chlorine gas from the battery prevented further recovery.  They remained in the village until being spotted by a PBY flying-boat (a large seaplane) on 24 June.  That aircraft, along with others, rescued all of the crew over the course of two days.\r\n\r\nThe crew was reassigned throughout the submarine force.  LT Jukes would later have success as captain of the USS Kingfish (SS-234).', 'S-27 was based in New London until she was transferred to the Pacific at the end of 1924.  After fleet exercises, She arrived at San Diego in June of 1925.  She operated from there until she was transferred to Pearl Harbor in February of 1931.  In June of 1939, S-27 returned to San Diego, often providing services for the Underwater Sound Training School.  In November of 1941, she proceeded to the Mare Island Naval Shipyard for an overhaul.\r\n\r\nAt the outbreak of WW2, S-27 was still undergoing the overhaul.  When the overhaul was completed, S-27 was again assigned to the sound school in San Diego for training missions.  On 20 May 1942, she was assigned to Dutch Harbor as part of the force patrolling the Aleutian Islands.\r\n\r\nS-27 was lost on her first war patrol and had no sinkings to her credit.', 17, 'images/extracted/S-27_SS-132_boat.jpg', NULL, NULL, 'images/extracted/S-27_SS-132_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'S-27 was an S-1 class submarine completed in January of 1924 by Bethlehem Shipbuilding Company in Quincy, MA.'),
('Unknown date, August 1942', '1942-08-01', '70', 70, 18, 'SS-216', 'Grunion', 'USS Grunion (SS-216)', 'Grunion was a Gato class submarine completed in April of 1942 by the Electric Boat Company in Groton, CT.', 'LCDR Mannert Abele', 'The Aleutian Islands', 'Uncertain', 'Grunion’s first war patrol was around Kiska, Alaska.  On 15 July, she reported being attacked by a destroyer and that they had fired torpedoes at the vessel but missed.  Later that day, Grunion engaged three sub chasers and claimed sinking two and damaging the third.  On 19 July, she set out to join other submarines patrolling near Kiska.  On 28 July, she reported attacking enemy shipping but missing.  On 30 July, she reported heavy anti-submarine activity and was told to leave the area for Dutch Harbor.  Grunion was never heard from again.  Air searches found nothing.\r\n\r\nThere are no records of an attack on Grunion after 30 July.  The Japanese had not planted mines in the area.  In August of 2007, a wreck was found in the Behring Sea.  In 2008, the Navy confirmed it was the Grunion.  Research of the wreck and Japanese records support two different possibilities.  One is that Grunion was struck by a shell from what had been the target, the Kano Maru.  That and a dive plane casualty could have forced the Grunion below crush depth.\r\n\r\nThere is also some evidence that Grunion could have been a victim of a circular-running torpedo. Such a torpedo could have hit the periscope without exploding.  The damage from such a collision might have caused significant flooding and sinking.  The Abele family believes this was the case.\r\n\r\nIt may be that neither suspected cause is true.  However, in any case, our malfunctioning torpedoes likely did contribute to the loss of Grunion.  The Kano Maru crew reported torpedoes that had missed and others that hit but didn’t explode.  Had the torpedoes worked properly, the Kano Maru likely would have been sunk and unable to fight.', 'En route to the Pacific, after her shakedown cruise, Grunion spotted 16 seamen in a lifeboat.  They turned out to be Americans from the USAT Jack (a U. S. Army cargo ship) which had been sunk by a U-boat that morning.  Grunion searched the area but could find no more survivors.  She landed the survivors she had recovered at Coco Solo in the Canal Zone on 3 June 1942.  From there, she proceeded to Pearl Harbor, Territory of Hawaii (TH.)  Grunion left Hawaii on 30 June for refueling at Midway and then on to her patrol area around Kiska.\r\n\r\nGrunion was lost on her first war patrol and JANAC credited her with sinking the two sub chasers.', 18, 'images/extracted/Grunion_SS-216_boat.jpg', NULL, NULL, 'images/extracted/Grunion_SS-216_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Grunion was a Gato class submarine completed in April of 1942 by the Electric Boat Company in Groton, CT.');
INSERT INTO `lost_submarines` (`date_lost`, `date_lost_sort`, `fatalities`, `fatalities_num`, `id`, `boat_number`, `name`, `designation`, `class_info`, `last_captain`, `location`, `cause`, `loss_narrative`, `prior_history`, `display_order`, `photo_boat`, `created_at`, `updated_at`, `photo_captain`, `image1`, `image1_subtitle`, `image2`, `image2_subtitle`, `image3`, `image3_subtitle`, `image4`, `image4_subtitle`, `image5`, `image5_subtitle`, `image6`, `image6_subtitle`, `image7`, `image7_subtitle`, `image8`, `image8_subtitle`, `image9`, `image9_subtitle`, `image10`, `image10_subtitle`, `construction`) VALUES
('16 August 1942', '1942-08-16', '0', 0, 19, 'SS-144', 'S-39', 'USS S-39 (SS-144)', 'S-39 was an S-18 class submarine completed in September of 1923 by the Bethlehem Shipbuilding Company in San Francisco, CA.', 'LT Francis E. Brown', 'Off Rossel Island in the Louisiade Archipelago, Papua New Guinea', 'Grounding', 'S-39’s fifth war patrol did not start auspiciously.   Twice, she had to return to port due to mechanical failures.  On her third attempt to set out on patrol, the XO had to be rushed to the hospital with pneumonia.  After a replacement for the executive officer was assigned, S-39 was finally able to get underway on 10 August 1942.  Early in the morning, just four days later, a navigational error left the boat on a reef in the Louisiades.\r\n\r\nEverything possible was done to get the boat off the reef.  However, the net result was just to have the 15 to 20-foot breakers push her further onto the reef with a 60-degree list to port.  On 16 August, the Australian minesweeper HMAS Katoomba arrived to assist.  Further efforts to free the submarine also failed and the Katoomba rescued the crew.  As the minesweeper left the scene, the S-39 was already breaking up due to the heavy seas and the rocks.  Therefore, no further attempt was made to destroy the stricken submarine.', 'During the last months of 1923 and early 1924, S-39 operated off the U. S. West Coast and in  the Caribbean.  By April, she was back at Mare Island for an overhaul.  In September of that year, she was assigned to the U. S. Asiatic Fleet and arrived at Manilla in November of 1924.  In May of 1925, she sailed to Tsingtao and operated briefly from there.  She returned to Manilla in September of 1925 and for the next 16 years operated from there and from Tsingtao during the summers.\r\n\r\nJust prior to the outbreak of the war, S-39 was patrolling off southern Luzon.  On 8 December, she was still at sea and began her first war patrol.  Under captain James (Red) Coe, she was ordered to the San Bernardino Strait to attack minelayers operating there.  However, the minelayers were well protected and S-39 suffered a serious depth charging for her efforts.  Her second war patrol consisted of a transit from the Philippines to Surabaya, with no sinkings.\r\n\r\nOn her third war patrol, S-39 was assigned to attempt a rescue of Rear Admiral Spooner RN and a group of British refugees.  After waiting two days for the party to appear, LT Coe sent a volunteer landing party to investigate.  Unfortunately, all they found were footprints and boat tracks in the sand.  It appeared that enemy soldiers had captured the party.  Later in the patrol S-39 sank a large tanker.  Her fourth patrol, under a new captain, yielded no sightings of Japanese shipping.\r\n\r\nLT Brown was reassigned and was lost with the USS S-44 (SS-155) in October of 1943.  LT Coe went on to be a successful commander of the USS Skipjack (SS-184) before being lost with the USS Cisco (SS-290) in September of 1943.\r\n\r\nS-39 was lost on her fifth war patrol.  JANAC credited her with one sinking for 6,500 tons.', 19, 'images/extracted/S-39_SS-144_boat.jpg', NULL, NULL, 'images/extracted/S-39_SS-144_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'S-39 was an S-18 class submarine completed in September of 1923 by the Bethlehem Shipbuilding Company in San Francisco, CA.'),
('10 January, 1943', '1943-01-10', '105', 105, 20, 'SS-166', 'Argonaut', 'USS Argonaut (SS-166)', 'Argonaut was a unique design, a class of just the one submarine.  She was completed in April of 1928 in the Portsmouth Naval Shipyard in Kittery, Maine.', 'LCDR John Pierce', 'Off New Britain', 'ASW forces', 'After reaching the assigned area for her third patrol, Argonaut found a convoy of five ships and three escort destroyers.  She attacked and hit one of the destroyers with a torpedo.  However, the other two destroyers attacked Argonaut and damaged her severely.  She was forced to the surface with a large up-angle.  Gunfire from the enemy destroyers riddled the bow and that resulted in the sinking of the Argonaut.  All of this was witnessed by an Army Air Corps bomber returning from a mission.  However, the plane had no bombs left and could only watch helplessly.', 'Argonaut was the largest submarine used by the U. S. in WW2.  She was 381 feet long, nearly 34 feet at the beam and displaced 2,710 tons.  (For comparison, the boats we built during the war, such as the Pampanito, were just less than 312 feet long, 27 feet at the beam and displaced 1,550 tons.)  Argonaut was designed as a minelayer and was armed with two six-inch guns.  She was underpowered which was a serious limitation even though she was designed for endurance rather that speed and maneuverability.\r\n\r\nAfter commissioning, Argonaut conducted a series of tests in the Atlantic in early 1929.  In March she was assigned to San Diego.  From there she participated in exercises and cruised the West Coast.  In 1931, she was featured in two movies as a U-boat.  She was also renamed from the V-4  to Argonaut  and designated as SM-1  indicating that she was a minelayer.\r\n\r\nOn 30 June 1932, Argonaut  arrived at Pearl Harbor.  From there she carried out minelaying exercises, joint operations and other routine work.  In April of 1941, she returned to the West Coast for fleet exercises and then sailed back to Hawaii.\r\n\r\nArgonaut’s first patrol had not been productive.  She had sailed on 29 November to patrol the area around Midway Island.  She learned of the attack on Pearl Harbor by radio on 7 December and set general quarters two hours later after sighting two Japanese destroyers shelling Midway.  She then made the first wartime approach on enemy forces but poor maneuverability prevented her from reaching a suitable firing position.  One of the destroyers spotted Argonaut as she dove for a second attempt to attack.  Argonaut was again unable to maneuver into an attack position and the destroyer was unable to locate the boat.  She surfaced after being held down all night only to be attacked by an American plane based at Midway.  On 20 January, she was escorted back into Pearl Harbor.\r\n\r\nOn 22 January, Argonaut departed for Mare Island for a major overhaul which included upgrading her engines and batteries.  Even after the upgrades, she was still slow and not very maneuverable.\r\n\r\nHowever, her second patrol was very unusual and was described as a success.  During her recent overhaul, she had been converted to a transport submarine.  On 17 August 1942, Argonaut and USS Nautilus (SS-168), together, carried 121 marines to Makin Island for a diversionary attack.  The goals of the raid were to inflict casualties on the Japanese garrison, to capture prisoners, to gather intelligence, and to relieve pressure on the marines landing at Guadalcanal.\r\n\r\nOnly the first objective was achieved.  Most of the Japanese forces were killed.  The raid did succeed in boosting morale and testing tactics.  However, 19 marines were killed in action.  Another 11 were captured, later transferred to Kwajalein and eventually executed.  Two days later Argonaut and Nautilus took the survivors, some of whom were injured, off the island and returned them to base.  Unfortunately, this raid prompted the Japanese to reinforce the Gilberts, likely making the future conquest more difficult.\r\n\r\nArgonaut was lost on her third war patrol and JANAC credited her with damaging the one destroyer but no sinkings.', 20, 'images/extracted/Argonaut_SS-166_boat.jpg', NULL, NULL, 'images/extracted/Argonaut_SS-166_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Argonaut was a unique design, a class of just the one submarine.  She was completed in April of 1928 in the Portsmouth Naval Shipyard in Kittery, Maine.'),
('16 February 1943', '1943-02-16', 'Fatalities: 74.\r\nThe chief pharmacist mate had been killed earlier on the patrol and one Japanese airman who had been taken prisoner died in the sinking.', 74, 21, 'SS-219', 'Amberjack', 'USS Amberjack (SS-219)', 'Amberjack was a Gato class submarine completed at the Electric Boat Company in Groton, CT in June of 1942.', 'LCDR John A. Boles Jr', 'Off the island of New Britain', 'Air and ASW forces', 'Amberjack began her third patrol after an abbreviated upkeep period, and wasn’t fully ready for sea.  The refit was just 12 days long, rather than the typical three to four weeks, due to the need for operational submarines for combat.  She began the patrol by sinking a large schooner by gunfire.  Then she was involved in a night gun battle with a 4,000-ton freighter.  In this engagement, the chief pharmacist mate, who had gone to the bridge to treat an injured officer, was killed.  Amberjack then torpedoed the freighter which sank after a huge explosion.  However, this could not be confirmed in postwar audits and Amberjack was not credited with either the schooner or the freighter.\r\n\r\nOn 14 February, Amberjack reported that she had picked up a Japanese airman as a prisoner and that she had been forced to submerge by two destroyers.  Japanese records indicate that a submarine was attacked on 16 February by a sub chaser which then guided other ships to the site.  Since USS Grampus (SS-207) was also sunk at about the same time and in the same area, it is highly probable, but not certain, that this sinking was of the Amberjack.', 'On her first patrol, Amberjack had torpedoed a large tanker which was claimed as sunk.  However, the tanker had settled into the mud and would be repaired.  The tanker would later be sunk by LCDR Bernard Clarey in command of the USS Pintado (SS-387).  Ironically, Clarey had been executive officer on Amberjack’s first patrol when the tanker was damaged.\r\n\r\nOn Amberjack’s second patrol, as she had been preparing to head back to base, she was ordered to Espiritu Santo.  There she picked up 9,000 gallons of aviation fuel, two hundred 100-pound bombs and 15 Air Corps personnel, and successfully delivered them to Tulagi.  Secret missions such as this were particularly hazardous because other U. S. forces would not know the boat was a “friendly”.\r\n\r\nAmberjack was lost on her third war patrol.  JANAC credited her with two sinkings for 5,225 tons total for her WW2 service.', 21, 'images/extracted/Amberjack_SS-219_boat.jpg', NULL, NULL, 'images/extracted/Amberjack_SS-219_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Amberjack was a Gato class submarine completed at the Electric Boat Company in Groton, CT in June of 1942.'),
('Estimated 5 March 1943', '1943-03-05', '71', 71, 22, 'SS-207', 'Grampus', 'USS Grampus (SS-207)', 'Grampus was a Tambor class submarine completed by the Electric Boat Company of Groton, CT in May of 1941.', 'LCDR John R. Craig', 'Thought to be in the Blackett Strait', 'Likely ASW forces', 'On her sixth patrol, after leaving her exercise area on February 12th, Grampus was not heard from again.  (Submarines don’t communicate often since it gives away their existence and location.)  She had been directed to patrol in the Blackett Strait.  On 5 March, she was warned that enemy destroyers would be transiting the strait.  It is thought likely that those destroyers sank Grampus.  Since no depth charges were heard by USS Grayback (SS-208), just 15 miles away, it is possible that Grampus was sunk by gunfire.  Because those Japanese destroyers were sunk on 6 March, they couldn’t contribute any helpful information to the record.\r\n\r\nGrampus, USS Amberjack (SS-219) and USS Triton (SS-201) (subject of the next entry) were all lost in the same general area at about the same time.  Reconciling the incomplete records was difficult and history has had to settle for best estimates.', 'On her first war patrol, Grampus sank a large tanker.  Her second and third patrols were without incident except for a gun battle with a patrol boat.  Grampus suffered one hit from this battle, but no serious damage.\r\n\r\nThe general policy was that captains would be relieved after two patrols with no successes.  That appears to be the case at this time on Grampus.  On her fourth patrol, the first under LCDR Craig, she carried four coast watchers and successfully landed them on Vella Lavella and Choiseul Islands.\r\n\r\nOn this patrol, Grampus encountered heavy anti-submarine activity, including at least 104 depth charges over the course of multiple attacks.  On her fifth patrol, she claimed torpedo hits on three transports plus a destroyer.  However, none of these could be verified and were not credited.\r\n\r\nGrampus was lost on her sixth war patrol.  JANAC credited her with one sinking for 8,636 tons.', 22, 'images/extracted/Grampus_SS-207_boat.jpg', NULL, NULL, 'images/extracted/Grampus_SS-207_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Grampus was a Tambor class submarine completed by the Electric Boat Company of Groton, CT in May of 1941.'),
('15 March 1943', '1943-03-15', '74', 74, 23, 'SS-201', 'Triton', 'USS Triton (SS-201)', 'Triton was a Tambor class submarine completed by Portsmouth Naval Shipyard in Kittery, Maine in August of 1940.', 'LCDR G. K. MacKenzie Jr', 'North of the Admiralty Islands', 'Likely ASW forces', 'Triton began her sixth patrol on 16 February 1943 under her new skipper.  On 7 March, she attacked a convoy in USS Trigger’s (SS-237) assigned area.  She claimed two freighters sunk but then had to go deep to evade a circular run of one of her own torpedoes.\r\n\r\nShe received credit for one of the freighters.  Triton reported on 11 March that she spotted two columns of smoke from five or more ships plus escorts and was chasing.  This was the last message from Triton.\r\n\r\nOn 13 March, Triton was alerted to three enemy destroyers that were operating in her area.  She was ordered to a new area and told to disregard assigned areas when chasing targets.  She was to avoid other submarines since there were other American boats in adjoining areas.  Triton did not acknowledge or report her new location.  It seems most likely that Triton was sunk by the three destroyers about which she was warned.', 'Until she was lost, Triton was perhaps the most effective boat in the Pacific Theater.  On her second patrol, she sank two ships.  On her third patrol, she began by sinking a trawler with her guns.  She followed that by sinking three marus, two sampans (with guns) and then sinking the Japanese submarine IJN I-64 with a single torpedo. The Japanese would renumber that submarine to I-164, not knowing it had already been sunk.  On her fourth patrol, she celebrated Independence Day, 1942, by sinking a Japanese destroyer.\r\n\r\nOn her fifth patrol, after an overhaul, she was given one of the early assignments of rescue duty for aviators whose planes may have been damaged during attacks on Japanese bases.\r\n\r\nIn this instance it was in support of an attack on Wake Island.  These assignments were known to submariners as “lifeguard duty.”  After that she sank a water carrier and a cargo ship.  Unreliable and malfunctioning torpedoes prevented any further success on this patrol\r\n\r\nTriton was lost on her sixth war patrol.  JANAC credited her with 11 sinkings for 31,788 tons total for her WW2 service.', 23, 'images/extracted/Triton_SS-201_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Triton was a Tambor class submarine completed by Portsmouth Naval Shipyard in Kittery, Maine in August of 1940.'),
('3 April 1943', '1943-04-03', '74', 74, 24, 'SS-177', 'Pickerel', 'USS Pickerel (SS-177)', 'Pickerel was a Porpoise class submarine completed by the Electric Boat Company of Groton, CT in January of 1937.', 'LCDR Augustus H. Alston', 'Likely off Shiramuka lighthouse on the northern tip of Honshu, the largest of the Japanese home islands', 'Uncertain – Likely air and ASW forces', 'Pickerel began her seventh war patrol when she sailed from Midway on 22 March 1943.  Her orders were to patrol the area to the northeast of Honshu.  She was never heard from again.\r\n\r\nDuring the JANAC review after the war, Japanese records showed an attack on a submersible.  Naval aircraft first spotted the boat on 3 April and attacked with a bomb.  The aircraft then directed a minelayer and a converted auxiliary subchaser to the site.  They dropped 26 depth charges on the suspected submarine.  Oil was reported to have come to the surface at the location of the attack.  Pickerel was the only submarine in the area.\r\n\r\nHowever, Japanese records also showed that their subchaser IJN CH-13 was sunk on 3 April in that area and the cargo ship Fukuei Maru was sunk 7 April.  Again, Pickerel was the only American submarine in the area.  She received credit for these sinkings after she was thought to have been sunk.  It is possible that she survived the depth charging on 3 April, only to succumb later to operational problems or even to damage from the depth charge attack.', 'Pickerel had sunk a cargo ship on her second war patrol, under a prior commanding officer and an auxiliary vessel on her sixth under LCDR Alston.  She claimed sinking two sampans on the sixth patrol, but credit was given only for vessels over 500 tons.  She also damaged a freighter on her fifth war patrol when en route to Mare Island for an overhaul.  Her other war patrols were not successful.\r\n\r\nPickerel was lost on her seventh war patrol.  JANAC credited her with four sinkings for 6,472 tons total for her WW2 service.', 24, 'images/extracted/Pickerel_SS-177_boat.jpg', NULL, NULL, 'images/extracted/Pickerel_SS-177_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Pickerel was a Porpoise class submarine completed by the Electric Boat Company of Groton, CT in January of 1937.'),
('22 April 1943', '1943-04-22', 'Fatalities: 4.\r\nAll 76 members of the crew were rescued when the boat was scuttled.  However, four men died in captivity.', 4, 25, 'SS-210', 'Grenadier', 'USS Grenadier (SS-210)', 'Grenadier was a Tambor class submarine completed by Portsmouth Naval Shipyard in Kittery, Maine in May of 1941.', 'LCDR John Fitzgerald', 'Lam Voalan Strait, in the Indian Ocean northwest of Penang', 'Scuttled', 'On her sixth patrol, on the night of 20 April 1943, Grenadier ventured west from an unproductive patrol area looking for targets.  She found two Japanese ships but they turned away.  Assuming they would return to their base course, the boat plotted a course on the surface to intercept.  Shortly before the planned dive time, she was spotted by a Japanese aircraft and dove.  As she passed 120 feet, she experienced a violent explosion.  All power and lighting were lost and she settled on the bottom at 270 feet.  There were many leaks in the after part of the boat.  A fire in the cubicle left the ship without propulsion and the propellor shafts had been knocked out of alignment.\r\n\r\nThe crew worked hard in repressive heat to repair the boat.  Bucket brigades kept the main motors dry.  Grenadier surfaced at dusk and continued working.  They were finally able to turn one shaft, but only at slow speed.  They had even rigged up a sail in the hope of moving the boat closer to land.  However, a cargo ship and escort appeared and closed on Grenadier.  An attacking aircraft was driven away by gunfire, but not before it had dropped another bomb close by.\r\n\r\nAt this point the captain decided to scuttle the boat to save the crew.  The merchant vessel picked up the entire crew and carried them to captivity.  Sources disagree but it appears that four of the crew died in POW camps.', 'Grenadier had participated in the search for the USS O-9 when that boat went missing.  Grenadier returned to Portsmouth Naval Shipyard for an overhaul on 5 November 1941.  Less than three weeks after the attack on Pearl Harbor, she sailed for Hawaii and her war patrols.\r\n\r\nGrenadier had sunk one freighter on her first patrol which began on 4 February 1942.  On her second patrol, beginning on 12 April, she fired four torpedoes at a large ship, the 14,457-ton Taiyo Maru.  All four were reported to have hit the target, although only two exploded.  That was still enough to destroy the ship.  After the war, it was learned that this maru was carrying a research crew, so the Japanese lost more than a large freighter.  Grenadier also may  have mistakenly sunk the Russian merchant ship Angarstroi on 1 May.  Later during this second patrol, Grenadier was part of the ring of submarines looking for the Japanese fleet that we knew was coming to attack Midway and to draw our carriers into battle.\r\n\r\nThe concerns voiced by the captain, LCDR Willis Lent, regarding the torpedoes were not well received.  Some sources claim that it may have cost him his command but questions about the sinking the Russian ship may also have been a factor.  Grenadier sailed for her third patrol with a new skipper.  On this patrol she claimed a 15,000-ton tanker but this was not confirmed.  Her fourth patrol was to lay mines, which she completed.  She also fired torpedoes at a freighter without any hits although she did receive a depth charging for her efforts.  On her fifth patrol, she sank a sampan and two small cargo vessels, all too small for credit.  Grenadier also hit a freighter with two torpedoes, but this ship was assessed as only being damaged.\r\n\r\nGrenadier was lost on her sixth war patrol and JANAC credited her with one sinking for 14,457 tons.', 25, 'images/extracted/Grenadier_SS-210_boat.jpg', NULL, NULL, 'images/extracted/Grenadier_SS-210_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Grenadier was a Tambor class submarine completed by Portsmouth Naval Shipyard in Kittery, Maine in May of 1941.'),
('Unknown date, between May and July, 1943', '1943-03-05', '78', 78, 26, 'SS-275', 'Runner', 'USS Runner (SS-275)', 'Runner was a Gato class submarine commissioned at Portsmouth Naval Shipyard in Kittery, Maine in July of 1942.  However, it was not completed until October.', 'LCDR Joseph Bourland', 'Unknown', 'Uncertain', 'Runner departed Midway for her third patrol on 28 May 1943.  She was to patrol the area off the Japanese home island of Hokkaido for about one month, returning to Midway on or about 11 July 1943.  She was never heard from again.  There are no attacks in that area at that time in Japanese records.  However, Runner received credit for sinking two Japanese ships in June since she was the only American submarine in the area.  Her loss was likely due to a mine, but could also be operational or an unreported enemy attack.', 'On her first war patrol, Runner fired torpedoes at three different freighters.  None was confirmed as sunk or damaged.  However, the third attack resulted in an attack by a Japanese aircraft.  A bomb exploded close to Runner’s port side while at periscope depth.  Repairs were made while at 200 feet.  However, due to the damage to the periscopes, she had to terminate the patrol.\r\n\r\nHer second patrol was a mine-laying mission, which she completed.  After that, she sighted a freighter and fired three torpedoes.  Only one exploded.  The Japanese claimed the vessel, which did not sink, was a hospital ship.  However, other records do not support the claim.\r\n\r\nRunner was lost on her third war patrol and JANAC credited her with two sinkings for 6,273 tons.', 26, 'images/extracted/Runner_SS-275_boat.jpg', NULL, NULL, 'images/extracted/Runner_SS-275_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Runner was a Gato class submarine commissioned at Portsmouth Naval Shipyard in Kittery, Maine in July of 1942.  However, it was not completed until October.'),
('12 June 1943', '1943-06-12', 'Fatalities: 42.\r\nFive men, including the captain, one other officer and three enlisted men had been on the bridge and survived.  Two Brazilian officers were among those lost.', 42, 27, 'SS-89', 'R-12', 'USS R-12 (SS-89)', 'R-12 was an R-1 class coastal defense submarine completed by Fore River Shipbuilding Company at Quincy, MA in September of 1919.  Fore River was building R boats during WW1 using the Electric Boat Company designs.', 'LCDR Edward E. Shelby', 'Off Key West', 'Foundered', 'On 12 June 1943, R-12 put to sea from Key West.  She was preparing for a torpedo exercise when the collision alarm was sounded due to flooding in the forward battery compartment.  (This was done so that all watertight doors would be closed.)  The captain immediately ordered all hatches closed and all main ballast blown.  However, the ocean was faster than the air blowing out main ballast.  The boat sank in about 15 seconds.\r\n\r\nThe five men on the bridge were the only survivors.  They were the captain, executive officer and three enlisted men.  The 42 men lost includes two Brazilian Navy officers.  Fortunately, 18 crew members of the R-12 were on liberty that day, and were spared the fate of their shipmates.\r\n\r\nAlthough the wreck has been located by the Lost 52 Project, we still don’t know the cause of the flooding in the forward battery.  A torpedo tube open to the sea is suspected even though there are interlocks to prevent such an occurrence.\r\n\r\n(The Lost 52 Project website indicates that they have, so far, located six of the missing WW2 boats.  We know the locations of 17 of the WW2 boats, including those that went aground or were bombed in port.  In addition. we know the locations of three of the boats lost after the war.)', 'R-12 was built during World War 1.  She operated on the East Coast until was assigned to the Pacific.  She transited the Panama Canal and arrived at San Pedro in July of 1920 and proceeded to Hawaii in September of that year.  She operated in Hawaiian waters until December of 1930.\r\n\r\nR-12 then got underway, along with other R boats, a tender and a submarine rescue ship, for New London, arriving there in February of 1931.  She then underwent an overhaul and trained sailors from the Submarine School.  In September of 1932, R-12 sailed to the Philadelphia Navy Yard and joined that reserve fleet.  She was decommissioned in December of 1932.\r\n\r\nR-12 was recommissioned in ordinary in July of 1940 to serve only as a training submarine.  She sailed for Panama where she arrived in December of 1940 for an inspection and shipyard availability.  After that, she returned to New London.  She operated on the East Coast and in Cuban waters.\r\n\r\nLCDR Shelby went on to a successful command of the USS Sunfish (SS-281), sinking over 45,000 tons of Japanese shipping in four patrols.\r\n\r\nR-12 was a training boat and did not have a combat record.', 27, 'images/extracted/R-12_SS-89_boat.jpg', NULL, NULL, 'images/extracted/R-12_SS-89_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'R-12 was an R-1 class coastal defense submarine completed by Fore River Shipbuilding Company at Quincy, MA in September of 1919.  Fore River was building R boats during WW1 using the Electric Boat Company designs.'),
('Estimated between 9 and 12 September 1943', '1943-09-09', '76', 76, 28, 'SS-209', 'Grayling', 'USS Grayling (SS-209)', 'Grayling was a Tambor class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in March of 1941.', 'LCDR Robert Brinker', 'West of Luzon, Philippine Islands', 'Likely rammed', 'Grayling departed Fremantle, Australia for her eighth patrol in July of 1943.  Her first mission was to deliver cargo to guerrillas in the Philippines which she completed on 31 July.  On 19 August, she reported damaging a freighter and sinking a small oiler.  This was the last report from Grayling.\r\n\r\nOn 23 August, she again delivered supplies to the guerrillas at Pucio Point, Panay, as reported by the guerrillas.  Grayling was credited with sinking a 5,480 ton freighter on 27 August.  On 9 September, the Japanese ship Hokuan Maru reports sighting a surfaced submarine in shallow water.  The maru cruised through that area and reported that she noted an impact with a submerged object.  That object was likely the Grayling.', 'After commissioning and sea trials, Grayling was part of the group searching for the USS O-9 (SS-70).  She then returned to Portsmouth after her shakedown cruise.  She then sailed for the Pacific arriving in San Diego on 10 December 1941.  One week later she sailed for Pearl Harbor where she was chosen as the flagship for ADM Chester Nimitz when he assumed command of the Pacific Fleet.\r\n\r\nPrior to her loss, Grayling had completed seven war patrols without an overhaul.  Her first patrol began on 5 January 1942 and she gained a great deal in training but was not successful.  She sank a freighter on 13 April on her second patrol.  This patrol ended on 16 May.\r\n\r\nNext, she was part of the group of scouting submarines around Midway, watching for the Japanese battle fleet.  Apparently, this was not credited as a patrol.  On 7 June, after the Japanese carriers had been sunk, Grayling was attacked by a group of our USAAF B-17 bombers.  The bombers reported that they had attacked an enemy cruiser and noted that it sank quickly.  In reality, it was the Grayling diving to escape the danger.  It is a good example of why submarine captains treated all aircraft as hostile.\r\n\r\nOn her third war patrol, which began on 14 July, Grayling claimed two hits on a freighter that were not confirmed.  An oil leak forced her to end the patrol early.  However, she was credited with damaging a Japanese submarine tender.  The patrol ended on 26 August.  During this refit, her damage was repaired and a surface search radar was added.\r\n\r\nOn her fourth, which began on 19 October, she was credited with a 4,000-ton freighter.  Her fourth patrol ended in Fremantle, Australia on 13 December.  On her fifth patrol, Grayling sank a 749-ton cargo ship.  This patrol ended on 24 February 1943.\r\n\r\nOn her sixth and seventh patrols, Grayling reported multiple attacks although only one, on a 4,103-ton freighter, could be confirmed as sunk.\r\n\r\nGrayling was lost on her eighth war patrol.  JANAC credited her with five sinkings for 20,575 tons total for her WW2 service.', 28, 'images/extracted/Grayling_SS-209_boat.jpg', NULL, NULL, 'images/extracted/Grayling_SS-209_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Grayling was a Tambor class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in March of 1941.'),
('Unknown date August or September of 1943', '1943-08-01', '76', 76, 29, 'SS-181', 'Pompano', 'USS Pompano (SS-181)', 'Pompano was a Porpoise class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in June of 1937.', 'LCDR Willis Thomas', 'Estimated in the shallow waters off Honshu or Hokkaido, Japan', 'Likely a mine', 'Pompano left Midway for her seventh patrol on 20 August 1943.  She was never heard from again.  However, Japanese records showed sinkings that were in Pompano’s patrol area and they were credited to her.  On 3 September, she sank a medium freighter and on 25 September a small auxiliary.  On 6 September, Pompano was notified that the patrol area to the north of her own was open, and she may have moved into that area.  She did not return to Midway around 5 October as expected.  Since Japanese records did not indicate an attack on Pompano, it was assumed that she was most likely lost to a mine.  However, recent research indicates that it may have been an air attack that sank her.\r\n\r\nPompano’s loss wasn’t announced until early 1944.  That news may have caused concern for the families of USS Pampanito (SS-383) sailors due to the similarity of the names.', 'Pompano was built with H.O.R. (Hooven-Owens-Rentschler) 8-cylinder double acting engines which were a complete failure.  They were wrecked during trials even before leaving Mare Island.  Pompano was laid up for eight months while the engines were replaced.  The new engines were 9-cylinder versions of the H.O.R. designs.  The new versions were little better and they had to be replaced with Fairbanks-Morse opposed piston engines in 1942.  All of the H.O.R. engines in our submarines would be replaced.\r\n\r\nAfter Pompano was finally ready and completed sea trials, she operated out of Mare Island, training and patrolling.  She was then assigned to Pearl Harbor arriving there shortly after the attack but soon enough to be awarded a battle star.  She began her first war patrol on 18 December 1941.\r\n\r\nPompano was thought to have conducted the first submarine reconnaissance mission of the war on her initial patrol.  The captain at the time, LCDR Lewis Parks, pioneered the use of camera photography through the periscope.  Pompano was investigating Japanese defenses in the Marshall Islands.  As if that weren’t dangerous enough, she was attacked by a Catalina flying boat and then by three SBD dive bombers from the carrier USS Enterprise (CV-6), each dropping a bomb on the boat.  One was close enough to do some damage and the resulting fuel leak was a problem for the rest of the patrol.  Pompano claimed three hits on a large freighter during the patrol, but that was not confirmed by Japanese records.\r\n\r\nPompano was credited with two sinkings on her second patrol.  She was also on the receiving end of 22 depth charges for her efforts although there was no damage.  She also sank a couple small vessels with her guns, but these were too small to be credited.  On her third patrol she was depth charged again but escaped with minor damage.  She also sank two freighters before returning for an overhaul at Mare Island.\r\n\r\nOn her fourth patrol, Pompano was able to damage three large ships but had no sinkings.  Her fifth patrol was near Tokyo Bay, but the weather was so poor that sightings were nearly impossible.  On 10 April 1943 she fired six torpedoes in a radar-guided attack at what she thought was a carrier and believed sonar heard two hits.  However, Japanese records showed nothing of the attack.  On her sixth patrol, Pompano fired two torpedoes at a grounded seaplane tender on 4 July.  On the 20th she fired two torpedoes at a large transport and thought she had missed.  However, Japanese records showed damage from this attack.  Occasionally, the JANAC audits added credit to a boat’s score.\r\n\r\nPompano was lost on her seventh war patrol.  JANAC credited her with five sinkings for 21,443 tons total for her WW2 service.', 29, 'images/extracted/Pompano_SS-181_boat.jpg', NULL, NULL, 'images/extracted/Pompano_SS-181_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Pompano was a Porpoise class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in June of 1937.'),
('28 September, 1943', '1943-09-28', '76', 76, 30, 'SS-290', 'Cisco', 'USS Cisco (SS-290)', 'Cisco was a Balao class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in May of 1943.', 'LCDR James Coe', 'The Sulu Sea', 'Air and ASW forces', 'Cisco reported to the Pacific Fleet. She sailed from Panama on 7 August 1943 for Darwin.  She arrived on 1 September and assumed local patrol duties until 18 September.  She sailed from Port Darwin, Australia for her first war patrol on 20 September 1943.  However, she had to return due to problems with the main hydraulic system.  After repairs, she departed on patrol the next day.  Nothing was heard from Cisco after that.\r\n\r\nOn 28 September, a Japanese aircraft noticed a submarine trailing oil.  The plane attacked, dropped a bomb and then called in surface vessels.  They depth charged the target and more oil came to the surface and continued to leak for days.  No other American submarines were in the area and this report is assumed to be about the loss of Cisco.\r\n\r\nLCDR Coe had previously commanded USS S-39 (SS-144) before she was lost and then the USS Skipjack (SS-184) before assuming command of Cisco.\r\n\r\nCisco was lost on her first war patrol and JANAC credited her with no sinkings.', NULL, 30, 'images/extracted/Cisco_SS-290_boat.jpg', NULL, NULL, 'images/extracted/Cisco_SS-290_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cisco was a Balao class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in May of 1943.'),
('7 October 1943', '1943-10-07', 'Fatalities: 56.\r\nTwo men survived.', 56, 31, 'SS-155', 'S-44', 'USS S-44 (SS-155)', 'S-44 was an S-42 class submarine completed by Bethlehem Shipbuilding Company at Quincy, MA in February of 1925.', 'LCDR Francis E. Brown', 'Off Paramushiro', 'Naval gunfire', 'S-44 departed Attu in the Aleutians for her fifth patrol on 26 September 1943.  She was not heard from again.  The details of this last patrol were provided by the two surviving crewmen.\r\n\r\nS-44 found what was thought, on radar, to be a small merchant ship.  The captain decided to surface and sink the vessel with gunfire.  However, the vessel turned out to be an escort ship, which opened fire.  The captain gave the order to submerge again, but for unknown reasons the boat was slow to respond.  S-44 was hit in the control room, conning tower and forward battery.\r\n\r\nAt this point, the captain gave the order to abandon ship and a crewman waved a pillowcase from the forward hatch.  However, the escort did not cease firing and S-44 was hit several more times.  Only about eight men managed to escape the sinking submarine and the Japanese picked up just two.  These two men went to the Ofuna interrogation camp and then to work in the Ashio mines.  They survived the war and were able to tell the story of the loss of S-44.', 'S-44 operated off New England until departing for Panama, arriving at Coco Solo on 5 September 1925.  She operated there, taking part in various exercises until the spring of 1927.  She operated from San Diego until December of 1930 when she was transferred to Hawaii.  Her division, SUBDIV 11, was home ported there for four years and then was transferred back to San Diego.  In 1937, the division was transferred back to Coc Solo.\r\n\r\nIn the spring of 1941, as U. S. involvement in WW2 increased, the S-boats in Panama were ordered to New London and then to Philadelphia  in November for overhauls.  S-44 arrived on 16 January 1942 and took part in the rescue operations for the USS S-26 (SS-131).  The division of S boats was ordered to the southwest Pacific, departing Panama in March and arriving in Brisbane , Australia in mid-April.\r\n\r\nPrior to her loss, S-44 had been the most successful of the S class boats.  She set out on her first war patrol on 24 April 1942.  On 12 May 1942, she sank a 5,600-ton merchant ship. This earned her a depth charging but she avoided significant damage.\r\n\r\nOn her second patrol, S-44 sank a converted gunboat.  The target blew up with such force that S-44 suffered some internal damage.  This was seen by an enemy aircraft which then dropped a bomb close aboard causing further damage.  S-44 managed to slip away.\r\n\r\nHer third patrol was her most successful.  In the Tulagi-Rabaul area near Guadalcanal, she spotted four Japanese cruisers.  She fired four torpedoes at the nearest one, and sank the IJN Kako, a heavy cruiser.  She was damaged again on her fourth war patrol, and was ordered back to the U. S. for an overhaul.  After that was completed, she was assigned to Attu, from which she began her final patrol.\r\n\r\nS-44 was lost on her fifth war patrol.  JANAC credited her with three sinkings for 17,070 tons total for her WW2 service.', 31, 'images/extracted/S-44_SS-155_boat.jpg', NULL, NULL, 'images/extracted/S-44_SS-155_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'S-44 was an S-42 class submarine completed by Bethlehem Shipbuilding Company at Quincy, MA in February of 1925.'),
('11 October, 1943', '1943-10-11', '80', 80, 32, 'SS-238', 'Wahoo', 'USS Wahoo (SS-238)', 'Wahoo was a Gato class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in May of 1942.', 'LCDR Dudley (Mush) Morton', 'La Perouse Strait', 'Air and ASW forces', 'Wahoo departed Pearl Harbor, Territory of Hawaii (TH.) for her seventh patrol on 9 September 1943.  LCDR Morton had specifically requested the patrol area in the Sea of Japan.  He had been frustrated on Wahoo’s sixth patrol by a lack of success primarily due to poor torpedo performance.  Dick O’Kane, who was Wahoo’s executive officer since commissioning, had been detached and assumed command of the Tang (SS-306).  O’Kane and Morton had made a formidable team with O’Kane generally functioning as the approach officer.  O’Kane was aggressive but was still thought to be a moderating influence on Morton.\r\n\r\nAfter a fuel stop at Midway, Wahoo was not heard from again.  She did not report that she had entered the Sea of Japan as expected.  However, four ships were sunk in the Sea of Japan at that time, and Wahoo was the only submarine in the area.  Records reviewed after the war indicate that a coastal defense battery had spotted a submarine on the surface and scored some hits on it.  Aircraft were dispatched to the area.  They dropped bombs on the shadow of the Conning Tower of a submerged submarine.  Japanese surface forces arrived later and dropped depth charges.  These attacks were determined to be the end of the Wahoo.', 'Wahoo’s first two patrols, under another captain, were much less successful.  She sank a single maru on her first war patrol.  Her second patrol consisted of missed opportunities and a lack of aggression by the captain.\r\n\r\nMorton, who was riding as a Prospective Commanding Officer, or PCO, and O’Kane, the executive officer, both recommended that the first captain be replaced.  In a somewhat unusual decision, Morton was given command of the Wahoo.  The previous captain went on to serve with distinction in command of a destroyer.\r\n\r\nOn Wahoo’s third patrol, she did a reconnaissance run into a bay for which we had no charts, providing the requested intelligence and severely damaging an enemy destroyer.  This patrol also resulted in the sinking of three ships and damage to a tanker.\r\n\r\nOne of the sunken ships had been carrying Japanese troops and became the source of controversy.  While charging the battery, Morton decided to return to the area where the troops were in small boats.  Wahoo proceeded to destroy the small boats.  This resulted in claims that the submarine was trying to kill helpless soldiers already in the water.  Morton stated that they were just trying to sink the small boats, not kill the soldiers.  The admiral agreed with Morton.  However, the controversy was never truly settled.\r\n\r\nFor her fourth war patrol, Wahoo was credited with nine ships sunk for 20,000 tons.  Two of these ships were sunk by gunfire due to torpedo problems.  This was the second highest number of sinkings for a single U.S. submarine patrol during the war.  It would only be exceeded later by Dick O’Kane, XO on the Wahoo for this patrol, when he was in command of USS Tang (SS-306).\r\n\r\nFor her fifth patrol, she was credited with three more ships for another 10,000 tons.  Wahoo was frustrated on both the fifth and sixth war patrols by recurring torpedo problems.  She found numerous targets on her sixth patrol in the Sea of Japan and conducted many attacks.  However, the torpedoes were all misses or duds.  That is why, after an overhaul at Mare Island, Morton requested to return to the Sea of Japan for what would be her final patrol.\r\n\r\nWahoo was lost on her seventh war patrol.  JANAC credited her with 20 sinkings for 60,038 tons total for her WW2 service.\r\n\r\nWahoo was awarded a Presidential Unit Citation for patrol 3.  The Presidential Unit Citation was the highest combat decoration for extraordinary heroism against an armed enemy by a ship or other military unit.', 32, 'images/extracted/Wahoo_SS-238_boat.jpg', NULL, NULL, 'images/extracted/Wahoo_SS-238_captain.jpg', 'images/extracted/Wahoo_SS-238_extra1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Wahoo was a Gato class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in May of 1942.'),
('12 October 1943', '1943-10-12', '76', 76, 33, 'SS-248', 'Dorado', 'USS Dorado (SS-248)', 'Dorado was a Gato class submarine completed by the Electric Boat Company at Groton, CT in August of 1943.', 'LCDR Earle Schneider', 'Likely in the Atlantic Ocean off Panama', 'Uncertain', 'Dorado had just completed sea trials and was en-route to the Pacific.  A PBM Mariner attacked a submarine in that area but maintained that it was not the Dorado.  They had been monitoring the submarine for some time and the crew was certain it was a German U-boat.  They believed it was outside the safety lane and 90 degrees off the expected course.  If the Mariner did not attack the Dorado, the cause of the loss of the boat is even less certain.  It could have been mines that had recently been laid by the U-214, or an operational loss.  Although it is not definite, the loss of Dorado seems more likely due to friendly fire.\r\n\r\nDorado was lost during her initial transit from the Electric Boat Company to Pearl Harbor, TH.  She never made it into combat.', NULL, 33, 'images/extracted/Dorado_SS-248_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Dorado was a Gato class submarine completed by the Electric Boat Company at Groton, CT in August of 1943.'),
('16 November 1943', '1943-11-16', '82', 82, 34, 'SS-226', 'Corvina', 'USS Corvina (SS-226)', 'Corvina was a Gato class submarine completed by the Electric Boat Company at Groton, CT in August of 1943.', 'CDR Roderick Rooney', 'South of Truk', 'Torpedoed', 'Corvina departed from Hawaii for her only patrol on 4 November 1943.  She stopped to top off fuel at Johnston Island and proceeded to the area south of Truk.  She was assigned to support surface operations in the Gilbert Islands.  The American boats in the area had been warned of the presence of a Japanese submarine in the area along with other U. S. boats.  Caution was the watchword.  When that part of the mission was completed, Corvina was to change operational command to the submarine commander at Brisbane, Australia.  However, Corvina had not been heard from after leaving Johnston Island.\r\n\r\nAfter the war ended, it was learned that IJN I-176, a submarine, had reported firing a spread of three torpedoes at an American submarine south of Truk on 16 November 1943.  Two of the torpedoes hit, causing a great explosion.  Corvina was almost certainly the target of I-176.  She would be the only American boat to be sunk by a Japanese submarine.\r\n\r\nCorvina was lost on her first war patrol and JANAC credited her with no sinkings.', NULL, 34, 'images/extracted/Corvina_SS-226_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Corvina was a Gato class submarine completed by the Electric Boat Company at Groton, CT in August of 1943.');
INSERT INTO `lost_submarines` (`date_lost`, `date_lost_sort`, `fatalities`, `fatalities_num`, `id`, `boat_number`, `name`, `designation`, `class_info`, `last_captain`, `location`, `cause`, `loss_narrative`, `prior_history`, `display_order`, `photo_boat`, `created_at`, `updated_at`, `photo_captain`, `image1`, `image1_subtitle`, `image2`, `image2_subtitle`, `image3`, `image3_subtitle`, `image4`, `image4_subtitle`, `image5`, `image5_subtitle`, `image6`, `image6_subtitle`, `image7`, `image7_subtitle`, `image8`, `image8_subtitle`, `image9`, `image9_subtitle`, `image10`, `image10_subtitle`, `construction`) VALUES
('19 November 1943', '1943-11-19', 'Fatalities: 63\r\nOf the 84-man crew:\r\n30 were killed in the gun battle or were not picked up by the Japanese,\r\n12 chose to go down with the boat when it was scuttled,\r\n1 badly wounded man was rescued by the Japanese and then thrown over the side,\r\n20 were lost on IJN Chuyo when it was sunk by the (USS Sailfish SS-192) while taking half the survivors to Japan,\r\n21 survived the war to tell the story.', 63, 35, 'SS-191', 'Sculpin', 'USS Sculpin (SS-191)', 'Sculpin was a Sargo class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in January of 1939.', 'CDR Fred Connaway', 'North of Truk', 'Scuttled', 'Sculpin began her ninth patrol on 5 November 1943 at Pearl Harbor, TH.  On board was CAPT John P. Cromwell who would be the wolfpack commander should one be formed.  Later, wolfpacks would be commanded by the senior CO in the pack, rather than an additional, senior officer.\r\n\r\nOrders to form a wolfpack had not been issued by CAPT Cromwell as of 29 November.  After hearing nothing from Cromwell, COMSUBPAC issued orders for a wolfpack on 1 December, in part to determine if Sculpin was all right.  In fact, Sculpin had already been lost.\r\n\r\nOn the night of 18 November, Sculpin had a radar contact on a fast convoy.  She began an end-around, to be ahead of the convoy for a dawn attack.  As she began her approach, she was detected and forced deep.  When Sculpin surfaced about an hour later, to make another end-around, she was spotted by a trailing destroyer.  The destroyer attacked with depth charges and inflicted only minor damage.\r\n\r\nLT George E. Brown, the diving officer, was relieved so he could check for damage.  When he returned to the control room, he found that the boat had broached the surface.  The depth gauge was stuck at 125 feet.  As a result, the ensign who had replaced Brown as diving officer did not know the actual depth when bringing the boat up to periscope depth and came up too far.  The depth charge attack began again.  A close string of 18 depth charges seriously damaged Sculpin.  The captain decided to surface and try to fight his way to safety.\r\n\r\nHowever, the destroyer soon put rounds through the main induction and the conning tower.  The captain, executive officer and gunnery officer were killed along with several other men.  LT Brown succeeded to command and decided to abandon ship and scuttle.  Twelve men chose to remain aboard the sinking boat.  This included CAPT Cromwell who feared that he might give up too much information about pending operations and about our success in breaking Japanese codes, our Ultra messages.  It also included the young diving officer who had inadvertently broached the boat.\r\n\r\n42 men were rescued by the Japanese.  However, one who was badly injured was thrown over the side.  Those who were prisoners were first taken to Truk for 10 days of questioning. Then they were divided into equal groups and loaded onto two Japanese escort aircraft carriers.  En route to Japan, the carrier IJN Chuyo, was sunk by the submarine USS Sailfish (SS-192).  Only one of the Sculpin’s sailors on the Chuyo was able to survive this sinking.\r\n\r\nThe sad irony of this story is that USS Sailfish (SS-192), then called Squalus, had been found by Sculpin. Squalus sank in May of 1939 off New Hampshire when her main induction valve failed, flooding the after (rear) compartments of the boat.  Sculpin quickly located Squalus and established communications, enabling the rescue vessel Falcon (ASR-2) to save 33 of the 59 men in the crew.  Now Sailfish, formerly the Squalus, inadvertently added to the tragedy of the loss of Sculpin.', 'As noted above, Sculpin was on her initial shakedown cruise in May of 1939 when she was directed to search for the missing Squalus.  Sculpin located the Squalus and stood by to assist.  She then engaged in training operations for the remainder of the year.  Transferred to the Pacific Fleet, she departed Portsmouth on 28 January 1940.  She arrived at San Diego on 6 March and at Pearl Harbor on 9 April.  She departed Pearl Harbor on 23 October 1941 and arrived at Cavite on 8 November.\r\n\r\nPrior to her ninth patrol, Sculpin was beset by torpedo problems.  She began her first war patrol from Cavite in the Philippines on escort duty shortly after the war began.  She claimed hits on a 5,000-ton cargo vessel but this was not confirmed.  On her second patrol, she fired torpedoes at an enemy cruiser and claimed two hits.  These are thought to be premature explosions since the cruiser was not damaged.  Later in this patrol she received a heavy depth charging, damaging her starboard main controller and propellor shaft.  She was directed to Exmouth, Australia for repairs.\r\n\r\nHer third patrol was a frustrating mix of misses, duds and prematures.  On her fourth patrol, she reported torpedoing a cargo ship, two large tankers and a large freighter.  However, none of these were confirmed by JANAC.\r\n\r\nOn her fifth patrol, she scored two hits on a new seaplane tender.  However, Sculpin could not confirm the damage due to a depth charge attack.  There was significant damage to Sculpin from the attack, but the crew was able to patch it up well enough to remain on patrol.  This paid off since she sank two ships in October of 1942 for which she finally received credit.  One other claim was not confirmed.  On her sixth patrol, she received credit for damaging a large tanker.  After this patrol she had a three-month overhaul at Mare Island Naval Shipyard.\r\n\r\nOn her seventh patrol, Sculpin sank two very small vessels for which JANAC did not normally give credit and may have damaged a cargo ship.  On her eighth patrol, she sank another medium cargo ship.  Two other attacks were thwarted by malfunctioning torpedoes.  Then there was a short overhaul period before embarking on her final patrol.\r\n\r\nSculpin was lost on her ninth war patrol.  JANAC credited her with three sinkings for 9,835 tons total for her WW2 service.\r\n\r\nCAPT Cromwell, the wolfpack commander on the last patrol, was awarded the Medal of Honor for his sacrifice.', 35, 'images/extracted/Sculpin_SS-191_boat.jpg', NULL, NULL, 'images/extracted/Sculpin_SS-191_captain.jpg', 'images/extracted/Sculpin_SS-191_extra1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Sculpin was a Sargo class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in January of 1939.'),
('Estimated to be 9 December 1943', '1943-09-09', '78', 78, 36, 'SS-289', 'Capelin', 'USS Capelin (SS-289)', 'Capelin was a Balao class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in June of 1943.', 'CDR Elliot Marshall', 'Celebes Sea', 'Uncertain', 'Capelin departed Darwin, Australia for her second war patrol on 17 November 1943.  She was assigned to an area in the Molucca and Celebes seas.  Nothing was heard from Capelin after leaving Darwin.  However, USS Bonefish (SS-223) reported having seen an American submarine in Capelin’s area on 2 December.  Attempts to reach Capelin on 9 December were not successful.\r\n\r\nThe only certainty is that Capelin was lost in the Celebes Sea or the Molucca Sea.  She was likely lost in December to a mine.  She was the last submarine lost in the Southwest Pacific area.', 'Capelin’s first patrol was brief, lasting only 17 days.  She departed Darwin, on 30 October with orders to rescue the crew of a bomber that had gone down in the area of the Celebes Sea.  This order was cancelled while she was en route.  On 11 November, she sank the Kunitama Maru.  Five days later, she returned to Port Darwin for some urgent repairs.  A defective conning tower hatch mechanism, noisy bow planes and a defective radar tube all needed immediate repair.  However, everything was quickly completed to the captain’s satisfaction and the submarine sailed the next day for her last patrol.\r\n\r\nCapelin was lost on her second war patrol.  JANAC credited her with one sinking for 3,127 tons.', 36, 'images/extracted/Capelin_SS-289_boat.jpg', NULL, NULL, 'images/extracted/Capelin_SS-289_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Capelin was a Balao class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in June of 1943.'),
('Unknown, likely between 6 January and 16 February 1944', '1944-01-06', '76', 76, 37, 'SS-278', 'Scorpion', 'USS Scorpion (SS-278)', 'Scorpion was a Gato class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in October of 1942.', 'CDR Maximilian Schmidt', 'Near the entrance to the Yellow Sea', 'Likely a mine', 'On her fourth patrol, Scorpion left Pearl Harbor, TH after a brief break for Christmas of 1943.  She topped off fuel at Midway and departed for the area of the East China Sea and the Yellow Sea on 3 January 1944.  On 5 January, Scorpion reported that they had a man with a badly broken arm.  She requested that they meet with USS Herring (SS-233), which was ending a patrol, to transfer the injured man.  The boats did meet, but the transfer was prevented by heavy weather.  Scorpion was never seen or heard from again.', 'On previous patrols, Scorpion had an eventful career.  Her first assignment was to lay 22 mines off the Japanese island of Honshu which she completed on 19 April 1943.  On the next day, she sank a converted gunboat.  That was followed by damaging a large freighter and sinking four sampans, which were too small for JANAC credit.  Then she sank a medium passenger/cargo ship.\r\n\r\nDuring this attack, Scorpion used a new device called a bathythermograph or BT.  This device shows the water temperature at various levels as the boat descends or ascends through the water.  Sonar is distorted by changes in temperature and may even be reflected by an abrupt change, allowing a submarine to “hide” beneath a “layer.”  Scorpion used this device effectively, and enemy depth charges were not accurate.\r\n\r\nWhile returning to base, Scorpion engaged a heavily armed patrol boat with her guns.  After her main gun jammed, she turned and fired a torpedo into the vessel.  The patrol boat exploded and went down.  Scorpion did not get credit for this sinking.\r\n\r\nDuring the fight, the XO, LCDR Reginald Raymond, was killed while manning a Browning automatic rifle.  LCDR Raymond was due to assume command of the USS Runner (SS-275) at the end of the patrol.  As the Scorpion was preparing to bury LCDR Raymond at sea, the boat was attacked and forced to dive.  The XO’s body was washed over the side, and the formal service had to be carried out later that evening.  A new destroyer escort would be named in his honor.\r\n\r\nScorpion’s second patrol began on 29 May 1943.  After topping off fuel at Midway, she headed for the Yellow Sea.  She spotted a five-ship convoy and fired torpedoes at overlapping targets.  (Two or more targets in the same line of fire with the nearest partially blocking the view of the more distant.)  Scorpion had to go deep when escorts attacked.  In the shallow water, she hit bottom at only 90 feet and destroyed her sonar heads.  She did get credit for sinking a freighter and a passenger/cargo ship but had to return to Midway for repairs.  During training after the repairs, Scorpion ran aground on the coral which surrounds Midway.  This time she had to return to Pearl Harbor for major repairs.\r\n\r\nHer third patrol began on 13 October 1943 with the usual stop at Midway for fuel.  Scorpion spotted a Japanese heavy cruiser but was unable to gain firing position.  Later, Scorpion went after a freighter.  However, the target turned out to be a “Q” ship which attacked the submarine.  Scorpion opted to clear the area.\r\n\r\nShe then attacked a large tanker and managed to hit it with one torpedo before being driven deep by escorts.  The tanker had to be towed to Singapore and did not return to the war.  Scorpion ended this patrol on 5 December 1943 at Pearl Harbor.\r\n\r\nScorpion was lost on her fourth war patrol.  JANAC credited her with four sinkings for 18,316 tons total for her WW2 service.', 37, 'images/extracted/Scorpion_SS-278_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Scorpion was a Gato class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in October of 1942.'),
('26 February 1944', '1944-02-26', '80', 80, 38, 'SS-208', 'Grayback', 'USS Grayback (SS-208)', 'Grayback was a Tambor class submarine completed by the Electric Boat Company at Groton, CT in June of 1941.', 'CDR John A. Moore', 'East China Sea', 'Aircraft', 'For her tenth patrol, Grayback left Pearl Harbor on 28 January 1944 and stopped at Midway for fuel.  Her patrol area was the East China Sea.  Her first report on 24 February claimed 44,000 tons of shipping sunk or damaged.  She had just six torpedoes left, five aft and one forward.  The next day she reported that she had fired four torpedoes from aft and scored three hits on two cargo ships.  She was then ordered to return to Midway.  On 27 February, Grayback’s last two torpedoes sank a freighter.\r\n\r\nJapanese records indicate that, on 26 February, a land-based attack plane dropped two bombs on a surfaced submarine, hit it and sank it.  In spite of the date discrepancies, Grayback had to be the boat that sank the ships and the one sunk by the aircraft’s bomb.', 'On Grayback’s first patrol, beginning on 15 February 1942, she had orders to patrol the area near Saipan and Guam in the Marianas.  There she played tag with a Japanese I class submarine before losing contact.  She then sank a former collier before ending the patrol on 10 April.\r\n\r\nHer second patrol was uneventful and ended in her new home port in Fremantle, Australia.  Her third patrol was also uneventful.  Her fourth patrol began with a new captain.  He claimed many hits on targets, firing all his torpedoes, but only damage to one large transport was confirmed.\r\n\r\nGrayback’s fifth patrol began on 7 December 1942 under the same captain.  One week into the patrol, the pharmacist mate performed the second appendectomy on board an American submarine.  (There would be a third before the Navy forbade any others.)  On 25 December, Grayback destroyed four landing barges with her deck gun.  On 3 January she claimed a Japanese submarine, but the target could not be confirmed.  Then she was directed to rescue aviators from a downed USAAF B-26 bomber who were stranded on an island.  The rescue was an adventure but successful.  The patrol ended after Grayback suffered significant damage from depth charges.\r\n\r\nHer sixth patrol was unsuccessful.  However, during her seventh, things improved.  An attack on a convoy resulted in one cargo ship sunk and two damaged.  Next, an attack left a destroyer badly damaged from two torpedoes.  Grayback added a cargo ship sunk and another damaged before returning to Pearl Harbor and then on to Mare Island Naval Shipyard for an overhaul and an upgrade to a 5-inch gun.\r\n\r\nCDR Moore assumed command of the Grayback for her eighth patrol, departing on 26 September 1943.  She was part of a three submarine wolfpack.  The wolfpack was a great success, claiming 38,00 tons sunk and 63,300 tons damaged.  Grayback contributed by sinking two ships of over 7,000 tons and combined with USS Shad (SS-235) to sink another of over 9,000 tons.\r\n\r\nGrayback’s ninth patrol began on 2 December 1943.  CDR Moore soon spotted a convoy of four ships with three escorts.  He sank one maru and damaged two others.  The IJN Numakaze, a destroyer stayed behind the convoy.  When Grayback surfaced to chase the rest of the convoy, the destroyer attacked the submarine from behind.  Grayback dived, fired four torpedoes from the after tubes and sank the destroyer.  Grayback later sank another cargo ship and a net layer and damaged two more freighters.  The final victim for this patrol was a small fishing boat sunk with the new 5-inch gun.\r\n\r\nGrayback was lost on her tenth war patrol.  JANAC credited her with 14 sinkings for 63,835 tons total for her WW2 service.\r\n\r\nGrayback was awarded a Presidential Unit Citation for the combined patrols 7, 8, 9 and 10.  This was the highest award for bravery in combat for a unit, such as a ship, rather than an individual.', 38, 'images/extracted/Grayback_SS-208_boat.jpg', NULL, NULL, 'images/extracted/Grayback_SS-208_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Grayback was a Tambor class submarine completed by the Electric Boat Company at Groton, CT in June of 1941.'),
('Approximately 29 February 1944', '1944-02-29', '81', 81, 39, 'SS-202', 'Trout', 'USS Trout (SS-202)', 'Trout was a Tambor class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in November of 1940.', 'LCDR Albert Clark', 'East China Sea', 'ASW forces', 'For her 11th patrol, Trout left Pearl Harbor on 8 February 1944 and topped off fuel at Midway Island.  She left Midway on 16 February and was never heard from again.  Information available after the war indicates that Trout attacked a convoy, sinking one ship and damaging another on 29 February.  Records also indicated that the IJN Asashimo, a destroyer, detected a submarine and, after dropping 19 depth charges, noted oil and debris rising to the surface.  Since Trout was the only submarine in the area, this is assumed to be her sinking.', 'After completing her shakedown tests Trout, along with the USS Triton (SS-201), departed New York City on 2 July 1941 headed to Panama, San Diego and Pearl Harbor.  The two boats arrived in Hawaii on 4 August 1941.  Trout conducted training operations until departing Pearl Harbor on 29 November 1941 for a simulated war patrol around Midway Island.\r\n\r\nSince she was still at sea when Pearl Harbor was attacked, Trout had already begun her first war patrol.  She noted Japanese destroyers firing at Midway Island but couldn’t get close enough to engage.  She returned to her assigned patrol area but saw nothing further.  She ended this first war patrol at Pearl Harbor on 20 December.\r\n\r\nHer captain, LCDR Frank W. (Mike) Fenno, took Trout out on an unusual second patrol beginning on 12 January 1942.  The mission was to deliver ammunition to MacArthur’s troops on Corregidor.  After delivering her cargo, Trout needed ballast to replace the weight of the ammunition.  The new ballast would be 20 tons of gold bars and silver coins which had been removed from banks in Manila.  Trout then continued her patrol, sinking a converted gunboat and a small patrol craft.  She returned to Pearl Harbor on 3 March 1942 to transfer her precious cargo to the cruiser USS Detroit (CL-8).  However, the inventory came up one gold bar, or $14,500, short.  A search of the submarine found the bar in the galley being used as a paperweight.  The cook claimed not to know what his paperweight was made of.\r\n\r\nLater in the war, LCDR Fenno would serve on the USS Pampanito (SS-383) , initially as a trainer for her first captain and then as a relief for LCDR Paul (Pete) Summers on Pampanito’s fourth war patrol.\r\n\r\nTrout began her third patrol from Pearl Harbor on 24 March 1942.  After a fuel stop at Midway Island, she arrived off the coast of Honshu two weeks later.  Beginning on 11 April, she damaged a very large tanker, the Nishin Maru, and then damaged another tanker and a cargo ship.  These last two beached themselves to prevent sinking.  Trout then sank a patrol boat, and two freighters.  Her very successful third patrol ended at Pearl Harbor on 17 May.\r\n\r\nFour days later, Trout went to sea to join the other submarines of Task Group 7.1.  The task group was the ring of submarines around Midway looking for the Japanese fleet headed that way.  This was her fourth patrol, although Trout was not involved in the battle.  She picked up two Japanese sailors floating on a raft and returned to Pearl Harbor on 14 June.\r\n\r\nTrout began her fifth patrol on 27 August 1942 under the command of LCDR Lawson (Red) Ramage.  (LCDR Ramage would later win the Medal of Honor as captain of the USS Parche [SS-384]).  Trout’s patrol was in the area around Truk.  She was detected and the Japanese dropped 45 depth charges, but Trout was not damaged.  She then sank a small net-tender and damaged the Japanese carrier Taiyo with two torpedoes.  Later Trout was badly damaged by aircraft bombs while at periscope depth.  She had to terminate the patrol at Brisbane, Australia on 13 October.\r\n\r\nOn her sixth patrol, from 26 October to 13 November, Trout fired a spread of torpedoes at a Kongo class battleship but with no detonations.  Trout set out on her seventh patrol on 11 January 1943.  She fired a spread at a large tanker and damaged it with two hits.  Despite serious damage, the tanker made it to safety.  Trout sank two sampans with her deck gun.  She thought she had also sunk a freighter.  As Trout cleared the area, the maru’s stern was under water.  Somehow, the maru survived, only to be sunk by the USS Pampanito (SS-383) in early 1945.  Trout was credited with the sinking of a cargo vessel.  On 7 February 1943, Trout again ran across the tanker Nishin Maru and, once more, was only able to damage it.  One more sinking, of a converted gunboat, would complete the score for this patrol.\r\n\r\nTrout’s eighth patrol assignment was to lay mines in the Api Passage.  That was completed and Trout sank two sampans.\r\n\r\nTrout began her ninth patrol on 26 May 1943 under a new captain, LCDR Clark.  This patrol consisted of special missions.  She landed six agents along with two tons of equipment on Basilan Island in the Philippines.  Then she landed a six-man army team with supplies and ammunition at Labangan, Mindanao, also in the Philippines.  Finally, she evacuated five officers from Mindanao.  In between, she sank three small cargo ships with her deck gun and another with torpedoes.\r\n\r\nHer tenth patrol was a transit from Fremantle to Hawaii.  En route, she was to patrol in the Surigao and San Bernardino Strait where she sank a medium-sized cargo ship and a transport ship.  After this, she ended the patrol on 4 October 1943 and headed to Pearl Harbor and then on to Hunters Point in San Francisco for a much-needed overhaul.\r\n\r\nTrout was lost on her 11th war patrol.  JANAC credited her with 12 sinkings for 37,144 tons total for her WW2 service.\r\n\r\nTrout was awarded a Presidential Unit Citation for the combined patrols 2, 3 and 5.  This was the highest award for bravery for a unit, such as a ship, rather than an individual.', 39, 'images/extracted/Trout_SS-202_boat.jpg', NULL, NULL, 'images/extracted/Trout_SS-202_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Trout was a Tambor class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in November of 1940.'),
('26 March 1944', '1944-03-26', 'Fatalities: 79.\r\nOne man survived to tell the tale of the torpedo circular run.', 79, 40, 'SS-284', 'Tullibee', 'USS Tullibee (SS-284)', 'Tullibee was a Gato class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in February of 1943.', 'CDR Charles Brindupke', 'North of Palau', 'Own torpedo', 'Tullibee departed for her fourth patrol on 5 March 1944. She was to take part in “Operation Desecrate”, a carrier air strike at Palau scheduled for 30 March.  On 26 March, Tullibee found a convoy of three good-sized marus and attacked.  She fired two torpedoes at the largest maru.  However, one of the two made a circular run and sank Tullibee.  The bridge party was thrown into the sea.  One man, gunner’s mate C. W. Kuykendall was able to swim long enough to be rescued the next day.  He endured many interrogations at the Ofuna prison camp before winding up in the Ashio mines for the duration.', 'Tullibee first arrived at Pearl Harbor on 15 May 1943 but didn’t begin her first patrol until 19 July.  She was assigned to an area around the Caroline Islands.  She made a few attacks without results.  On 10 August, she was rammed by an enemy ship which damaged a periscope.  On 22 August, she sank a passenger/cargo ship and damaged a freighter.  She ended the patrol at Midway on 6 September.\r\n\r\nHer second patrol began on 28 September 1943 when she headed to the East China Sea.  On 15 October, she sank a transport and damaged another.  Two torpedoes aimed at the larger target exploded prematurely.  Tullibee also claimed the sinking of a large tanker on 25 October, but that could not be verified.  On 5 November, she used her deck gun to shell the army barracks at Okino Erabu Island, north of Okinawa.  She returned to Pearl Harbor via Midway on 16 November.\r\n\r\nTullibee departed Pearl Harbor on 14 December 1943 for her third patrol, near the Marianas.  For this patrol she was part of a wolfpack with USS Halibut (SS-232) and USS Haddock (SS-231).  CDR Brindupke was the senior officer and in command of the pack.  On 2 January, Tullibee fired four torpedoes at a Japanese submarine but missed.  A Japanese float plane then dropped four bombs at Tullibee but caused no damage.  During the patrol Tullibee tried to transfer fuel to Halibut, but was not successful.  Tullibee sank a net-tender on this patrol and Halibut damaged the IJN Unyo, a carrier.  Overall, the results of this wolfpack were disappointing.\r\n\r\nTullibee was lost on her fourth war patrol.  JANAC credited her with three sinkings for 10,579 tons total for her WW2 service.', 40, 'images/extracted/Tullibee_SS-284_boat.jpg', NULL, NULL, 'images/extracted/Tullibee_SS-284_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tullibee was a Gato class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in February of 1943.'),
('Unsure, between 7 April and 12 May 1944', '1944-04-07', '78', 78, 41, 'SS-211', 'Gudgeon', 'USS Gudgeon (SS-211)', 'Gudgeon was a Tambor class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in April of 1941.', 'LCDR Robert Bonin', 'In the Marianas or near Iwo Jima', 'Uncertain', 'Gudgeon sailed for her 12th patrol on 4 April 1944.  After stopping for fuel, Gudgeon was never heard from again.  Japanese records indicate two possible locations and two different dates for her sinking.  Some sources indicate the boat was likely to have been sunk by depth charges on 12 May near the Maug Islands in the Marianas.  Uboat.net claims Gudgeon was lost to an aircraft attack on 18 April 1944 southeast of Iwo Jima.  Mike Ostlund, a relative of one of the officers lost on Gudgeon and author of “Find ‘Em, Chase ‘Em, Sink ‘Em”, supports the Uboat.net version.', 'After shakedown, Gudgeon headed north to assess sites in Alaska for a possible submarine base.  From there, she headed to Pearl Harbor, arriving on 10 October 1941.  She was at Lahaina Roads, off Maui, TH, when the Japanese attacked Pearl Harbor on 7 December 1941.\r\n\r\nShe returned to Pearl Harbor immediately and began her first war patrol on 11 December, departing on the same day as the USS Plunger (SS-179).  She was the first American boat to patrol along the Japanese coast and first to make contact.  When she was returning to base, she was advised that an enemy submarine that had shelled Midway might cross her path.  The IJN I-73, a submarine, (later renumbered to I-173) was spotted on the surface about 240 miles west of Midway.  Gudgeon hit it with three torpedoes, sinking the first Japanese warship of the conflict.  She returned to Pearl Harbor on 31 January.\r\n\r\nGudgeon departed for her second patrol, to the East China Sea, on 22 February 1942.  Near Marcus Island she was attacked by a dive bomber from the carrier USS Enterprise (CV-6) but suffered no damage.  This showed again that submarines had to assume all aircraft were hostile and submerge quickly.  Gudgeon sank two freighters on this patrol and returned to Pearl Harbor on 15 April.\r\n\r\nFor her third patrol, Gudgeon was taken out of drydock three weeks early, loaded and sent to sea in just 40 hours.  This was done so she could be a part of Task Group 7.1 looking for the Japanese fleet headed toward Midway.  This patrol lasted from 18 May until 14 June.\r\n\r\nShe departed for her fourth patrol on 11 July 1942.  She sank one medium freighter and damaged two larger ones en route to Fremantle, Australia.  The patrol ended there on 2 September.\r\n\r\nHer fifth patrol began on 8 October 1942.  Gudgeon sank a medium freighter.  On 11 November, she made a daring attack on a seven-ship convoy.  She fired torpedoes at overlapping targets and heard many explosions.  However, JANAC showed no damage.  The torpedoes may have exploded prematurely.  She returned to Australia on 1 December.\r\n\r\nGudgeon was able to celebrate Christmas before departing for her sixth patrol on 27 December 1942.  She sank no ships on this patrol but carried out special missions.  She landed six men and a ton of supplies at Catmon Point, Negros in the Philippines.  As she was returning from the patrol, she was sent to the south coast of Timor to evacuate 28 men.  She returned to Fremantle , Australia on 18 February 1943.\r\n\r\nGudgeon’s seventh patrol lasted just from 13 March to 6 April 1943 because she had used all of her torpedoes.  First, she sank one medium freighter and damaged another.  Then she sank a patrol boat with her gun.  Then she sank a tanker of almost 10,000 tons, even though this required five torpedoes.  Shortly after, she damaged a small ship which escaped only to be sunk later by the Dace (SS-247).\r\n\r\nHer eighth patrol lasted from 15 April to 25 May 1943.  This patrol again had a special mission, landing four guerrillas and three tons of equipment near Pucio Point, Panay, The Philippines.  Before that was completed, Gudgeon attacked a freighter and believed it was damaged.  However, escorts prevented confirmation.  Then Gudgeon sank the 17,526-ton liner Kamakura Maru which was due to be converted to an escort carrier.  Gudgeon completed the special mission and evacuated three men at the same time.  After this success, she destroyed a trawler with the deck gun.  The next day, she left a small freighter with decks awash after a gun action.  However, since there was nothing in Japanese record to support the sinking, there was no credit given.  Gudgeon added one more medium freighter to her patrol total.  Then it was time to head for an overhaul at Mare Island.\r\n\r\nWith the overhaul completed, Gudgeon departed Pearl Harbor on 1 September 1943 for her ninth patrol, this time in the Marianas.  She returned to Midway on 6 October having expended all her torpedoes and having sunk one cargo ship and damaged others.\r\n\r\nHer tenth patrol, along the China coast, began on 31 October 1943.  In her first contact with enemy ships, she sank a large troop transport and a frigate, and damaged a large tanker and a small freighter.  The patrol ended at Pearl Harbor on 11 December.\r\n\r\nHer eleventh patrol was less successful.  Gudgeon sighted a damaged carrier, but was not able to get close.  She did put two torpedoes into a freighter that was already sinking from an air attack so Gudgeon did not claim the sinking.  She returned to Pearl Harbor on 5 March 1944.\r\n\r\nGudgeon was lost on her 12th war patrol.  JANAC credited her with 12 sinkings for 71,047 tons total for her WW2 service.\r\n\r\nGudgeon was awarded a Presidential Unit Citation for patrols 1, 2, 3, 4, 5, 6, 7 and 8.', 41, 'images/extracted/Gudgeon_SS-211_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Gudgeon was a Tambor class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in April of 1941.'),
('1 June 1944', '1944-06-01', '84', 84, 42, 'SS-233', 'Herring', 'USS Herring (SS-233)', 'Herring was a Gato class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in May of 1942.', 'LCDR David Zabriskie', 'Near the Kurile Islands', 'Shore gunfire', 'Herring departed Pearl Harbor on 16 May 1944 for her eighth patrol.  She topped off fuel at Midway Island and headed to her assigned area around the Kuriles.  She rendezvoused with USS Barb (SS-220) on 31 May.  After that Herring began the run of luck that accounted for most of her Pacific sinkings.  She soon sank a frigate and another small ship.  The next day she sank two small-to-medium freighters that were at anchor.  Sadly, that was the end of her good luck.  That same day, she was spotted by a shore battery that opened fire and soon made two hits on the conning tower.  The Herring sank, ending her most productive patrol.', 'For her first patrol, Herring was one of the few boats assigned temporarily to the Atlantic.  She supported Operation Torch, our landings in North Africa in November of 1942.  Soon after arriving, Herring sank the medium sized freighter, Ville de Havre, which was being operated by the pro-German Vichy Government.\r\n\r\nDuring her second patrol, targets were hard to find and Herring scored no successes.  On her third patrol, she was able to sink the U-163 on 21 March 1943 in a night surface attack.  However, her fourth and fifth patrols did not yield any sinkings.  Her fifth patrol ended on 26 July 1943 back in New London, CT.  (We did send a few boats to support the British, but they weren’t particularly effective and they would eventually be reassigned to the Pacific Theater.)\r\n\r\nHerring sailed from Pearl Harbor on 15 November 1943 for her sixth patrol.  In December, she sank a medium transport and damaged a large tanker.  She claimed to have sunk a destroyer escort, but that was not confirmed.  On New Years Day, she sank a large transport/aircraft ferry.  She also claimed another large freighter but that was not confirmed.\r\n\r\nHerring’s seventh patrol was not productive.  LCDR Zabriskie was warned about his lack of sinkings.  However, he remained in command for her successful but ill-fated eighth patrol.\r\n\r\nHerring was lost on her eighth war patrol.  JANAC credited her with six sinkings for 19,959 tons total.  However, JANAC only considered action in the Pacific.  The summary “U. S. Losses, World War II”, compiled by the office of the Commander Submarine Force U. S. Pacific Fleet in 1946 credits Herring with nine ships for 45,200 tons.  This includes the Vichy transport and the U-boat.  It appears that COMSUBPAC also included a third sinking during the sixth patrol that JANAC didn’t credit.', 42, 'images/extracted/Herring_SS-233_boat.jpg', NULL, NULL, 'images/extracted/Herring_SS-233_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Herring was a Gato class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in May of 1942.'),
('14 June 1944', '1944-06-14', '82', 82, 43, 'SS-361', 'Golet', 'USS Golet (SS-361)', 'Golet was a Gato class submarine completed by the Manitowoc Shipbuilding Company at Manitowoc, WI in September of 1943.', 'LCDR James Clark', 'Off northern Honshu', 'ASW forces', 'Golet departed Midway on 28 May 1944 on her second patrol.  She was never heard from again.  Postwar records indicate that she was lost off Honshu, Japan on 14 June due to depth charging.', 'Golet’s first patrol began from Pearl Harbor on 18 March 1944.  She patrolled near the Kurile Islands, as well as Hokkaido and Honshu.  However, the severe weather hampered operations so badly that Golet ended the patrol at Midway with all her torpedoes on 3 May.\r\n\r\nThere were many unusual things about Golet’s history.  The fact that she was built in Manitowoc may have been one of the least unusual.  We built 28 submarines at Manitowoc Wisconsin on Lake Michigan.  Since Golet was the 11th boat built in that yard, the differences there had become almost routine.  Those differences included the launching of the boats sideways, the lower density of fresh water in calculating diving trim, sea trials in Lake Michigan even in winter, and the process of taking the boats down the Mississippi River on a floating drydock to the Gulf of Mexico.  These had all been addressed ten times before Golet was completed.\r\n\r\nThe next unusual thing was that Golet was intended to be a Balao class boat.  However, the Electric Boat Company – the supervising yard for the Manitowoc contracts – was backed up and wasn’t ready to provide the plans for the Balao class boats when Manitowoc was ready to build them.  As a result, the first four boats in Manitowoc’s second contract were built as Gato boats.  There is probably no way of knowing whether the thinner Gato hull was a factor in Golet’s loss.\r\n\r\nThe last unusual thing is that Golet had three different commanding officers in her short history.  The commissioning captain was relieved after training at Pearl Harbor.  According to Clay Blair Jr. in “Silent Victory” (page 667), the inspection cruise for the new boat found the wardroom to be “ill-trained and ill-led”.  There was discussion about replacing all the officers, but the decision was to replace just the commanding and executive officers.  The new CO was on loan from the training command.  The new XO was the prospective commanding officer (PCO) who would assume command for the ill-fated second patrol.  This third and last CO, LCDR Clark, had recommended that four more officers and two chief petty officers be sent ashore, but this was not done.\r\n\r\nGolet was lost on her second war patrol and JANAC credited her with no sinkings.', 43, 'images/extracted/Golet_SS-361_boat.jpg', NULL, NULL, 'images/extracted/Golet_SS-361_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Golet was a Gato class submarine completed by the Manitowoc Shipbuilding Company at Manitowoc, WI in September of 1943.'),
('4 July 1944', '1944-07-04', '50', 50, 44, 'SS-133', 'S-28', 'USS S-28 (SS-133)', 'S-28 was an S-1 class submarine completed Bethlehem Shipbuilding Company at Quincy, MA in December of 1923.', 'LCDR Jack Campbell', 'Training area near Hawaii', 'Foundered', 'S-28 was providing training exercises for enlisted personnel and sonar exercises for destroyers.  At 17:30 local time she was conducting a practice approach on the Reliance, a Coast Guard cutter when sound contact with S-28 was lost.  It was briefly regained and then lost again.  No distress signals were heard nor were there any sounds of explosions.  S-28 was lost in 8,400 feet of water making rescue or recovery impossible.', 'After commissioning and trials, S-28 took part in winter exercises in the Caribbean.  In April of 1924, she returned to New London.  In June of 1925, S-28 was assigned to San Diego.  She operated from there until mid-February of 1931.  Then she was assigned to Pearl Harbor for the next eight years until she went back to San Diego in mid-1939 to resume work at the Underwater Sound Training School.\r\n\r\nWhen the war broke out for the U. S. in December of 1941, S-28 was undergoing an overhaul in Mare Island Naval Shipyard.  The overhaul was completed on 22 January 1942 and S-28 returned to duty at the Underwater Sound Training School in San Diego.  However, she was soon needed to make patrols around the Aleutians.  She completed five uneventful patrols from Dutch Harbor.  From 15 March to 15 April 1943, she operated with the Royal Canadian Navy and then was overhauled in the Puget Sound Naval Shipyard.\r\n\r\nHer sixth patrol, from 13 July to 16 August 1943 was again uneventful.  On 20 September 1943, her seventh patrol, she had her only victory, sinking a converted gunboat.  Injuries to a crewman, followed by a case of appendicitis, caused the S-28 to end the patrol at Attu on 13 October 1943.  The severe weather had taken a toll on the old S boat and she was ordered to Pearl Harbor for training duties where she would later be lost.\r\n\r\nS-28 was lost on training duties after seven war patrols.  JANAC credited her with one sinking for 1,368 tons total for her WW2 service.', 44, 'images/extracted/S-28_SS-133_boat.jpg', NULL, NULL, 'images/extracted/S-28_SS-133_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'S-28 was an S-1 class submarine completed Bethlehem Shipbuilding Company at Quincy, MA in December of 1923.'),
('26 July 1944', '1944-07-26', 'Fatalities: 81.\r\n77 men died in the sinking.  Four others swam to shore but died after being imprisoned.', 81, 45, 'SS-273', 'Robalo', 'USS Robalo (SS-273)', 'Robalo was a Gato class submarine completed by the Manitowoc Shipbuilding Company at Manitowoc, WI in September of 1943.', 'CDR M. M. Kimmel', 'Two miles off the west coast of Palawan', 'Likely a mine', 'Robalo began her third patrol from Fremantle on 22 June 1944.  She reported sighting a Japanese task force with a battleship supported by destroyers and air cover on 2 July.  Nothing was heard from the submarine after that.\r\n\r\nAt the end of the war, we learned that a note had been dropped from a window in the prison camp at Palawan in the Philippines.  It identified four sailors from the Robalo and stated that the boat had been lost due to a battery explosion.  (It was later judged to be more likely due to a mine.)  The four sailors were being held as guerrillas rather than as POWs.  Nothing was heard of the Robalo survivors after that.  They might have been executed or they may have been taken to Japan on a ship that was sunk en route.  In any case, there is no record of their eventual fate.', 'After commissioning, Robalo sailed and was towed from Manitowoc, through Chicago and the Illinois Waterway and down the Mississippi River.  She then sailed through the Panama Canal and on to Fremantle, Australia as her first war patrol.  She fired four torpedoes at a large cargo ship at long range and claimed one hit.  After this unsuccessful patrol, the captain was judged not to have the temperament needed to command a submarine.  He was replaced by LCDR Kimmel, the son of Admiral Kimmel who was in command at Pearl Harbor on the day of the Japanese attack.\r\n\r\nHer second war patrol was in the East China Sea.  She made a series of attacks but without results.  On 24 April 1944, Robalo was attacked by Japanese aircraft and seriously damaged.  Additional personnel errors caused the boat to descend to 350 feet, below test depth but not below design depth.  The crew was able to make enough repairs to stay on patrol.  On 17 May 1944, Robalo claimed to have sunk a tanker of 7,500 tons but this was not confirmed.\r\n\r\nRobalo was lost on her third war patrol and JANAC did not credit her with any sinkings.', 45, 'images/extracted/Robalo_SS-273_boat.jpg', NULL, NULL, 'images/extracted/Robalo_SS-273_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Robalo was a Gato class submarine completed by the Manitowoc Shipbuilding Company at Manitowoc, WI in September of 1943.'),
('13 August 1944', '1944-08-13', 'Fatalities: 78.\r\nEight men survived.', 78, 46, 'SS-250', 'Flier', 'USS Flier (SS-250)', 'Flier was a Gato class submarine completed by the Electric Boat Company at Groton, CT in October of 1943.', 'CDR John Crowley', 'Balabac Strait', 'Mine', 'For her second patrol Flier departed on 2 August 1944 for an area off Indo China.  However, on 13 August, while crossing the Balabac Strait, Flier hit a mine and sank in 20 to 30 seconds.  About 15 men had survived the sinking, but only eight reached Mantangula Island after swimming for 15 hours.  There they made contact with friendly natives who led them to an Australian coast-watcher.  The coast-watcher alerted U.S. forces in Australia and the eight survivors from the Flier were rescued by the submarine USS Redfin (SS-272) on the night of 30-31 August 1944.', 'While Flier was en route to Pearl Harbor for her first patrol, she was fired upon, but not hit, by a friendly merchant ship.  No doubt, the merchantman thought it was firing on a U-boat.  However, that is just one more hazard that our submarines faced during the war.\r\n\r\nFlier prepared for her first patrol in the area off Hawaii.  She departed on 12 January 1944 for that patrol, with the usual stop at Midway for fuel.  She arrived at Midway at the height of a big storm and ran aground on a reef when trying to enter the harbor.  (Midway was notorious for being difficult to enter due to the coral reefs.)  The damage forced Flier to be towed to the mainland for repairs at the Mare Island Naval Shipyard.\r\n\r\nFlier did not actually begin her first war patrol until 21 May 1944.  She was assigned to the area off Luzon in the Philippines.  On 4 June, she found an enemy convoy and chased it on the surface.  After diving, Flier was able to get between two columns of ships.  She fired three torpedoes at each of two targets.  As she was preparing to fire at a third from the stern tubes, the captain noticed that one of the enemy ships had turned to ram.  The submarine went deep and lost contact with the convoy.  However, she had sunk a large transport and damaged another ship.  About two weeks later, she found another convoy and managed to damage three ships from that group although none were sunk.  The patrol ended on 5 July.\r\n\r\nFlier was lost on her second war patrol and JANAC credited her with one sinking for 10,380 tons.', 46, 'images/extracted/Flier_SS-250_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Flier was a Gato class submarine completed by the Electric Boat Company at Groton, CT in October of 1943.');
INSERT INTO `lost_submarines` (`date_lost`, `date_lost_sort`, `fatalities`, `fatalities_num`, `id`, `boat_number`, `name`, `designation`, `class_info`, `last_captain`, `location`, `cause`, `loss_narrative`, `prior_history`, `display_order`, `photo_boat`, `created_at`, `updated_at`, `photo_captain`, `image1`, `image1_subtitle`, `image2`, `image2_subtitle`, `image3`, `image3_subtitle`, `image4`, `image4_subtitle`, `image5`, `image5_subtitle`, `image6`, `image6_subtitle`, `image7`, `image7_subtitle`, `image8`, `image8_subtitle`, `image9`, `image9_subtitle`, `image10`, `image10_subtitle`, `construction`) VALUES
('24 August 1944', '1944-08-24', '79', 79, 47, 'SS-257', 'Harder', 'USS Harder (SS-257)', 'Harder was a Gato class submarine completed by the Electric Boat Company at Groton, CT in December of 1942.', 'CDR Sam Dealey', 'Off the Philippine Island of Luzon', 'ASW forces', 'Harder departed Fremantle , Australia on 5 August 1944 for her sixth war patrol.  She was part of a wolfpack with the USS Haddo (SS-255) and the USS Hake (SS-256).   On 21 August, the wolfpack, plus three other boats, attacked a convoy.  They sank five freighters for a total of over 32,000 tons, although Harder was not credited with any of the sinkings.  The next day, Harder did sink two escort ships.\r\n\r\nOn 23 August, Haddo damaged a Japanese destroyer which later sank while under tow.  The remaining escorts then searched the area in an effort to protect a tanker.  The search found the Harder and on 24 August she was sunk by depth charges from an escort.', 'After her shakedown cruise, Harder headed for Pearl Harbor via the Panama Canal.  While crossing the Caribbean on 2 May 1943, she sighted a U. S. Navy PBY flying boat.  Harder flashed recognition signals for that day and was rewarded with machine gun fire.  As the boat did a crash dive, the PBY dropped two bombs.  One was close enough to shake the submarine but she was able to continue her voyage.  CDR Dealey wrote in his log “The aviator’s poor approach was exceeded only by his poor marksmanship … but whose side are these crazy aviators on?”(Quoted in “Silent Victory”, page 444.)\r\n\r\nHarder had a very good record starting with her first patrol, also under the command of CDR Dealey.  She left Pearl Harbor on 7 June 1943 for a patrol off the island of Honshu, Japan.  On 21 June Harder made its first attack, firing four torpedoes at two ships.  One prematured and Dealy believed the others hit.  An escort attacked Harder and the boat went deep. However, it went too deep to escape the depth charges and buried her nose in the mud bottom at 300 feet.  The joke about being first to land on Japanese soil wasn’t so funny when it took 45 minutes to break free of the mud.\r\n\r\nOn 23 June, Harder detected a large ship on radar.  She fired four torpedoes at the enemy vessel.  Only one appeared to hit the former seaplane-tender Sagara Maru, but it was a mortal blow.  In all, Harder made seven attacks on three convoys during this first patrol and believed they sank three ships and damaged four others.  However, JANAC credited only the Sagara Maru.  This patrol ended on 7 July at Midway with one of the H.O.R. engines “completely broken down”.  (“Silent Victory”)\r\n\r\nHer second patrol began on 24 August 1943 when she departed Pearl Harbor, refueled at Midway and then headed for the Japanese coast.  On this patrol she sank four cargo ships plus a tanker.  After she used up all her torpedoes, she damaged two armed trawlers with her guns.  During this patrol, beginning after attacking two ships on 13 September, Harder underwent a depth charging over the course of two days before she could get away.\r\n\r\nHarder began her third patrol on 30 October 1943 as part of a wolfpack.  Communications between the boats left much to be desired.  The captain of the USS Pargo (SS-264) was taking aim at a freighter only to watch it blow up before he could fire.  Harder had fired first but she somehow did not get credit.  However, in a later series of attacks, she did get credit for sinking three freighters.  The patrol ended on 30 November at Pearl Harbor.  She was then sent to Mare Island Naval Shipyard to have her H.O.R. diesel engines replaced.  (The H.O.R engines never were satisfactory in our subs.)  She did not return to Pearl Harbor until 27 February 1944.\r\n\r\nHer fourth patrol began on 16 March 1944 proceeding with USS Seahorse (SS-304) to the Caroline Islands for lifeguard duty for downed pilots.  On 1 April, Harder rescued an aviator who had been forced into trees by the Japanese.  Dealey put the nose of the Harder on a reef and held it there while three crew members used a rubber boat to extract the pilot.  A floatplane tried to help but only complicated things.  Fortunately, the Navy aircraft providing cover were more effective.\r\n\r\nOn 13 April, a Japanese destroyer was vectored to Harder’s position and attacked.  Harder sank the destroyer.  This is how Harder began to earn her reputation as a destroyer killer.  Four days later, she sank a freighter and damaged an escort.   The patrol ended at Fremantle, Australia.\r\n\r\nHer fifth patrol began on 26 May 1944 in the area around Tawi Tawi.  On 6 June, Harder chased a convoy of tankers on the surface and one of the escorts turned to attack.  Dealey held position and fired three torpedoes to sink the destroyer.  The next day he spotted another destroyer hunting for Harder and sank it.  During the night of 8-9 June, Dealey evacuated six coast watchers from British North Borneo.\r\n\r\nThe next day, Harder fired four torpedoes at overlapping destroyers.  One was sunk but the other was not credited by JANAC.  On the 10th, Harder found a task force that included two of Japan’s super battleships.  She was detected during the approach and a destroyer attacked.  Explosions were heard but Harder did not get credit.  She did send a contact report but no other submarine was in position to attack.\r\n\r\nHarder was then out of torpedoes and headed for Darwin to replenish.  She then went right back out again, but found no other targets.  The patrol ended in Darwin on 3 July 1944.\r\n\r\nHarder was lost on her sixth war patrol.  JANAC credited her with 16 sinkings for 54,002 tons total for her WW2 service.\r\n\r\nCDR Dealey was awarded the Medal of Honor posthumously.\r\n\r\nHarder was awarded a Presidential Unit Citation for patrols 1, 2, 3, 4 and 5.', 47, 'images/extracted/Harder_SS-257_boat.png', NULL, NULL, 'images/extracted/Harder_SS-257_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Harder was a Gato class submarine completed by the Electric Boat Company at Groton, CT in December of 1942.'),
('3 October 1944', '1944-10-03', 'Fatalities: 82.\r\n17 embarked U. S. Army personnel also died.', 82, 48, 'SS-197', 'Seawolf', 'USS Seawolf (SS-197)', 'Seawolf was a Sargo class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in December of 1939.', 'LCDR Albert Bontier', 'Off Manus, Admiralty Islands', 'Friendly fire', 'Seawolf departed Brisbane , Australia on her 15th war patrol on 21 September 1944 on a special mission.  She was carrying 17 Army soldiers and their supplies to Samar in the Philippines.  On 3 October, she exchanged recognition signals with USS Narwhal (SS-167).  Shortly after this, the IJN RO-41, a submarine, sank an American destroyer escort (a DE).  Another U. S. escort went in search of the Japanese submarine.  Aircraft sighted a diving submarine nearby and dropped two bombs.  The DE sped to the position marked by the aircraft.\r\n\r\nThere were four friendly submarines in the area and they were asked to give their positions.  Only three did so.  Seawolf failed to reply or perhaps was unable to.  The destroyer escort then made sonar contact and attacked.  It reported hearing sounds from the submarine sending signals but assumed the sub was just trying to jam their sonar equipment.  After six attacks with hedgehogs, underwater explosions were heard and debris rose to the surface.  Unfortunately, all of this occurred in a submarine safety lane, where no attacks at all were supposed to be made.  It is assumed that this was the end of Seawolf, her crew and passengers.', 'After sea trials and shakedown cruise, Seawolf was assigned to the Pacific Fleet at San Diego.  In the autumn of 1940, she proceeded to Manila Bay and operated from Cavite.  She continued training operations from there.\r\n\r\nRight after the war broke out, Seawolf left Cavite in the Philippines on 8 December 1941 for her first war patrol.  On the 14th, she fired eight torpedoes at a seaplane tender but missed.  One was reported to hit but failed to explode.  The patrol ended on 26 December.  Her next patrol was a transit to Port Darwin, arriving on 9 January 1942.  One week later, Seawolf was underway again, this time taking 30 tons of ammunition to the forces on Corregidor.  There, she evacuated 25 airmen, spare parts and torpedoes, departing for Surabaya the next day.\r\n\r\nSeawolf sailed from Surabaya for her fourth patrol on 15 February 1942 to patrol the Java Sea.  She found plenty of targets but had limited success. She attacked two freighters, claiming only damage.  Attacks on two more freighters, a destroyer and a cruiser netted nothing.  However, on 1 April she did damage a cruiser.  Her fifth patrol was more of the same with many attacks and few results.  However, Seawolf did score her first sinking, a converted gunboat.\r\n\r\nHer sixth patrol began on 25 July, 1942.  On 2 August, she damaged a large tanker.  On 14 August, she sank a small freighter.  She sank another on 25 August.  Her seventh patrol was more successful, sinking a freighter, a large transport and converted gunboat.  This patrol ended on 1 December 1942 in Pearl Harbor before sailing to Mare Island Naval Shipyard for an overhaul.  The shipyard period lasted until 24 February 1943.\r\n\r\nShe began her eighth patrol under a new captain on 3 April 1943.  This patrol resulted in the sinkings of a freighter, an auxiliary, a patrol boat and a couple sampans.  Her ninth patrol began on 17 May 1943.  On this patrol she attacked two convoys with spreads of torpedoes.  In the first attack, one torpedo hit a freighter but didn’t explode.  Another ran under a target but hit a destroyer for damage.  On the other attack, Seawolf sank a cargo ship carrying many soldiers.  She ended the patrol at Midway and then proceeded to Pearl Harbor, arriving on 12 July.\r\n\r\nSeawolf left Pearl Harbor on 14 August 1943 headed out for her tenth patrol which was in the East China Sea.  There she found a six-ship convoy.  She sank two medium freighters and seriously damaged a torpedo boat.  Seawolf continued to track the remains of the convoy and sank a smaller freighter with a torpedo and then the deck gun.  Two more sampans were sunk with the deck gun.  The patrol ended on 15 September.\r\n\r\nHer 11th patrol began on 5 October 1943 and took her to the South China Sea.  She sank two more freighters and damaged another.  After this, she sailed to Pearl Harbor for a refit.  Her 12th patrol began on 22 December 1943 and Seawolf again sailed for the East China Sea.  This was a very successful patrol, resulting in the sinkings of two large cargo ships and two more of medium size.  Two additional ships were damaged.  The patrol ended on 27 January 1944.\r\n\r\nAfter this, Seawolf came to Hunters Point in San Francisco for a major overhaul.  She would not return to action until 4 June 1944 under a new captain.  Seawolf’s 13th patrol was primarily a reconnaissance mission around Peleliu in preparation for that invasion.  The patrol ended at Darwin.  Her 14th patrol began on 7 August 1944 and was another special mission.  It entailed landing six men and ten tons of supplies on Tawi Tawi and a similar landing a few days later at Palawan.  This patrol ended in Brisbane.\r\n\r\nSeawolf was lost on her 15th war patrol.  JANAC credited her with 18 sinkings for 71,609 tons total for her WW2 service.\r\n\r\nSeawolf was awarded a Presidential Unit Citation for patrols 4. 7, 10 and 12.', 48, 'images/extracted/Seawolf_SS-197_boat.jpg', NULL, NULL, 'images/extracted/Seawolf_SS-197_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Seawolf was a Sargo class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in December of 1939.'),
('Estimated 17 October 1944', '1944-10-17', '82', 82, 49, 'SS-294', 'Escolar', 'USS Escolar (SS-294)', 'Escolar was a Balao class submarine completed by the Cramp Shipbuilding Company at Philadelphia, PA in June of 1944.', 'CDR William Millican', 'Estimated to be Tsushima Strait', 'Likely a mine', 'Escolar departed Pearl Harbor for her first patrol on 18 September 1944.  After topping off fuel at Midway, she joined USS Croaker (SS-246) and USS Perch II (SS-313) as the lead in a wolfpack.  CDR Millican was experienced and the senior officer.\r\n\r\nOn 30 September, she reported to the other wolfpack members that she had attacked a patrol boat with guns.  The transmission was breaking up but Escolar did not indicate any damage to herself nor the status of the patrol boat.  On 17 October Croaker reported receiving a message from Escolar indicating she was heading for the Tsushima Strait.  Escolar did not respond to messages after that and was never heard from again.  It was assumed that she was lost to a mine since there are no records of Japanese attacks in the area.\r\n\r\nEscolar was lost on her first war patrol and JANAC credited her with no sinkings.', NULL, 49, 'images/extracted/Escolar_SS-294_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Escolar was a Balao class submarine completed by the Cramp Shipbuilding Company at Philadelphia, PA in June of 1944.'),
('24 October 1944', '1944-10-24', '0', 0, 50, 'SS-227', 'Darter', 'USS Darter (SS-227)', 'Darter was a Gato class submarine completed by the Electric Boat Company at Groton, CT in September of 1943.', 'LCDR David McClintock', 'Bombay Shoal in the Palawan Passage', 'Grounding', 'Darter departed on 10 September 1944 for her fourth patrol from Darwin after some minor repairs.  She sailed with the USS Dace (SS-247) on what would turn out to be two of the more important submarine patrols in WW2.  Darter and Dace located the central Japanese force attempting to stop our invasion of Leyte in the Philippines.  They immediately radioed the information about the large Japanese force moving through the San Bernardino Strait.  The submarines then positioned themselves on either side of the Palawan Passage.  Each boat sank a heavy cruiser as the Japanese fleet sailed by.  Darter sank the IJN Atago, a heavy cruiser and Admiral Kurita’s flagship, and damaged the IJN Takao, a cruiser.  Dace sank the IJN Maya, a heavy cruiser.  However, the intelligence information was almost certainly the most valuable part of the patrol.\r\n\r\nDarter then started tracking the damaged Takao in the hope of sinking it too.  However, due to the action of the previous days, Darter had been unable to get a position fix.  Just after midnight, she ran aground.  Because she had been running at high speed, she was firmly grounded on the reef and efforts to get clear failed.  Darter had to radio Dace for help and Dace rescued the entire Darter crew after all classified material was destroyed.\r\n\r\nThe abandoned Darter would be shelled by the Dace and later by the larger guns of the USS Nautilus (SS-168).   However, the battered hulk of the Darter remained on the reef for 20 years.  The whole crew of the Darter was transferred to the submarine USS Menhaden (SS-377), then under construction in Manitowoc, WI.  Menhaden would not be commissioned until June of 1945 and would not make a war patrol.\r\n\r\nThe Takao escaped but was so badly damaged that she never reentered the war.  In July of 1945, while still being repaired, Takao was sunk by British midget submarines.  The Battle of Leyte Gulf was the end of the Japanese fleet as an effective fighting force.', 'After sea trials, Darter arrived at Pearl Harbor on 26 November 1943.  Darter’s first patrol began on 21 December 1943.  It was interrupted twice for repairs, first at Pearl Harbor from 29 December to 3 January 1944 and then from 30 January to 8 February at Milne Bay.  After the needed repairs were completed, Darter went back on patrol.  On 13 February 1944, she damaged a large cargo ship and received a heavy depth charging in return.  After completing lifeguard duty off Truk, she ended the patrol on 29 February at Brisbane, Australia.\r\n\r\nHer second patrol began on 17 March 1944 with a fuel stop at Milne Bay, Papua New Guinea.  Her patrol area was north of Western New Guinea and south of Davao.  There she sank a small cargo ship.  This patrol ended on 23 May in Brisbane.  During that refit, Darter suffered her only casualty of the war when  a motor mac was electrocuted.\r\n\r\nOn her third patrol she sank a 4,400-ton minelayer and received a depth charging for her efforts.  The rest of this patrol was uneventful and it ended on 8 August 1944, again in Brisbane.  She needed minor repairs before starting the fourth patrol and becoming a key factor in the Battle of Leyte Gulf.\r\n\r\nDarter was lost on her fourth war patrol.  JANAC credited her with three sinkings for 19,429 tons total for her WW2 service.\r\n\r\nDarter was awarded a Presidential Unit Citation for patrol 4.', 50, 'images/extracted/Darter_SS-227_boat.jpg', NULL, NULL, 'images/extracted/Darter_SS-227_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Darter was a Gato class submarine completed by the Electric Boat Company at Groton, CT in September of 1943.'),
('24 October 1944', '1944-10-24', '87', 87, 51, 'SS-314', 'Shark II', 'USS Shark II (SS-314)', 'Shark II was a Balao class submarine completed by the Electric Boat Company at Groton, CT in February of 1944.', 'CDR Edward Blakely', 'Luzon Strait', 'ASW depth charges', 'Shark II left Pearl Harbor on 23 September and began her third patrol on 2 October 1944 from Saipan in the Mariannas.  CDR Blakely was the senior officer in a wolfpack that included USS Blackfish (SS-221) and USS Seadragon (SS-194).  On 24 October, Shark II radioed Seadragon that she had found a lone freighter and was going to attack.  That was the last heard from Shark II.\r\n\r\nWikipedia states that Shark II sank the Arisan Maru, a Japanese prison ship with 1,800 American prisoners aboard.  The loss of American lives was reported to be the greatest loss in a single sinking during the war.  The ship carried no special markings so submarines would not have known there were prisoners aboard.  It was reported that the Arisan Maru split in two after being hit by a torpedo aft of amidships.  However, JANAC did not credit Shark for sinking that transport.  The book “U. S. Submarine Losses, World War II” does credit Shark II with the sinking, but “The Last Patrol” does not.  (Refer to the “Bibliography” section of this document.)\r\n\r\nJapanese records indicate that a submarine was sunk by depth charges from a destroyer at that location.  Although other submarines were attacked in that area at about that time, none mentioned this particular attack.  Therefore, this is thought to be the end of Shark II.', 'Shark II’s first patrol was very successful.  She left Midway as part of a wolfpack on 16 May 1944.  Between 2 and 5 June, Shark sank four ships, often hitting her targets with all of the torpedoes fired at them.  The patrol ended at Midway on 17 June 1944.\r\n\r\nHer second patrol began on 10 July 1944 from Midway.  Her assigned area was around the Volcano and Bonin Islands.  Shark II claimed damage to two ships, but this was not confirmed.  She went on to provide lifeguard duty services around Iwo Jima.  On 4 August, she rescued two aviators from a torpedo bomber off the carrier USS Lexington (CV-16.)  The patrol ended at Midway on 19 August with Shark II continuing on to Pearl Harbor, arriving there on 29 August.\r\n\r\nShark II was lost on her third war patrol.  JANAC credited her with four sinkings for 21,672 tons total for her WW2 service.', 51, 'images/extracted/Shark_II_SS-314_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Shark II was a Balao class submarine completed by the Electric Boat Company at Groton, CT in February of 1944.'),
('24 October 1944', '1944-10-24', 'Fatalities: 78.\r\nNine survived.', 78, 52, 'SS-306', 'Tang', 'USS Tang (SS-306)', 'Tang was a Balao class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in October of 1943.', 'CDR Richard (Dick) O’Kane', 'Luzon Strait', 'Own torpedo', 'Tang’s fifth war patrol began on 24 September 1944 from Pearl Harbor.  She left Midway after a fuel stop and on 27 September headed to the Luzon Strait.  On 10 October, Tang sank a small freighter and another the next day.  On 23 October, Tang found a large convoy and, in a night surface attack, sank at least three ships.  The Japanese lost another ship in the attack on the convoy but, for some reason, JANAC did not credit that to Tang.  The next day, Tang found another convoy and sank two large tankers.  Four more large vessels were claimed as sunk, but were not credited.\r\n\r\nThe last torpedo fired in this attack, the last torpedo Tang had on board, was a circular run.  Tang recognized the circular run and turned hard to avoid it.  However, she could not turn quickly enough and the torpedo hit in the after torpedo room.  The boat sank quickly in 180 feet of water with the stern on the bottom and the bow out of the water.  Three men on the bridge swam free and one from the conning tower managed to get out as well.  The survivors inside the boat opened the forward ballast tank vents to put the boat level on the bottom.  Although 13 men were then able to get out through the forward escape trunk, only five survived and were picked up.  The nine sailors swam long enough to be picked up by the Japanese and survived the war.\r\n\r\nThe escort ship that picked up the Tang survivors had also picked up survivors from the ships that the boat had sunk.  O’Kane stated “When we realized that our clubbings and kickings were being administered by the burnt, mutilated survivors of our own handiwork, we found we could take it with less prejudice.”  O’Kane weighed just 88 pounds when the war ended.', 'Tang departed Pearl Harbor and began her first war patrol on 22 January 1944.  She was  headed for the area around the Caroline and Mariana Islands.  On 17 February, she sank a large cargo ship.  Another large cargo ship went down at the same time, but Tang did not get credit for it.  On 22 February, Tang attacked a three-ship convoy and sank two of them.  Two days later, she found a tanker and a freighter.  Bad weather prevented Tang from getting into firing position.  However, she tracked the convoy and sank the freighter.  The next day, 25 February, she sank a small tanker.  On 26 February, Tang fired her last four torpedoes at a freighter but missed.  The patrol ended at Midway.\r\n\r\nTang’s second patrol began on 16 March 1944.  She made a number of contacts but could not attack.  Then she was ordered to lifeguard duty around Truk.  There she rescued 22 aviators: the crew of a Kingfisher seaplane plus the men who had already been picked up by the plane.  Tang was ordered to end the patrol at Pearl Harbor.  O’Kane’s insights into lifeguard communications contributed to increased submarine safety during lifeguard duty and possibly greater success since they didn’t need to submerge as often.\r\n\r\nHer third war patrol began on 8 June 1944.  On this patrol, Tang set the record for the most ships confirmed sunk in one patrol.  This was in the areas of the East China Sea and the Yellow Sea.  On 24 June, she attacked a convoy of six marus escorted by 16 warships.  In a surface attack, Tang sank four of the marus.  On 30 June, she sank an unescorted cargo ship and then two more small ships on 1 July.  Two more followed on 4 July.  The last sinking was on 6 July and Tang was again out of torpedoes.  She had sunk 10 ships for 39,100 tons on a single patrol.\r\n\r\nTang began her fourth patrol on 31 July 1944 headed for the area off Honshu.  On 10 August, she fired three torpedoes at a tanker but missed.  The next day she sank a cargo ship with one torpedo.  She claimed damage to another.  A depth charge attack lasted 38 minutes but Tang evaded.  Afterwards, there was no sign of the ship and escorts were rescuing survivors, but Tang did not get credit.  She then sank a patrol yacht with her deck guns.  On 22 August, she sank a small freighter and on the next day she sank a large transport.  On 25 August, Tang sank a small tanker and its escort with her last torpedoes.  This patrol ended on 1 September 1944 at Pearl Harbor.\r\n\r\nTang was lost on her fifth war patrol.  JANAC originally credited her with 24 sinkings for 93,824 tons total for her WW2 service.  According to Wikipedia, this has been revised to 33 ships for 116,454 tons, placing O’Kane first in the list of most successful U. S. submarine captains.  These numbers are in addition to O’Kane’s successes on USS Wahoo (SS-238) as XO and approach officer under CDR Morton.\r\n\r\nWe did not realize until the end of the war that Darter, Shark II and Tang were all lost on the same day.\r\n\r\nCDR O’Kane was awarded the Medal of Honor for his last two engagements.\r\n\r\nTang was awarded Presidential Unit Citations for patrols 1, 2, 3, 4 and 5.\r\n\r\nNOTE: ADM O’Kane’s cribbage board is on loan to the oldest attack submarine in the U. S. fleet.  When that boat is decommissioned, the cribbage board is transferred to the next oldest attack boat.', 52, 'images/extracted/Tang_SS-306_boat.jpg', NULL, NULL, 'images/extracted/Tang_SS-306_captain.jpg', 'images/extracted/Tang_SS-306_extra1.jpg', NULL, 'images/extracted/Tang_SS-306_extra2.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tang was a Balao class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in October of 1943.'),
('7 November 1944', '1944-11-07', '86', 86, 53, 'SS-218', 'Albacore', 'USS Albacore (SS-218)', 'Albacore was a Gato class submarine completed by the Electric Boat Company at Groton, CT in June of 1942.', 'LCDR Hugh Rimmer', 'South of Hokkaido', 'Likely a mine', 'Albacore left Pearl Harbor on 24 October 1944 for her eleventh war patrol.  She departed Midway on 28 October headed for the northeast coast of Honshu and south of Hokkaido.  She was never heard from again.  After the war, we learned that, on 7 November, a Japanese patrol boat in that area witnessed an underwater explosion followed by debris and floating oil.  This was assumed to be the loss of the Albacore.', 'Albacore departed on her first war patrol from Pearl Harbor on 28 August 1942.  She claimed damage to three ships.  She also sighted a Japanese carrier escorted by a cruiser and a destroyer, but could not get into firing position.  She was depth charged a few times for her trouble.  The patrol ended at Midway on 20 October.\r\n\r\nOn her second patrol, beginning 11 November 1942, Albacore claimed to have sunk the 10,438-ton Gokoku Maru based on debris in the water.  However, that ship survived and was later confirmed to have been sunk by the USS Barb (SS-220) in 1944.  Albacore’s first confirmed sinking was a light cruiser on 18 December.  This patrol ended in Brisbane, Australia.\r\n\r\nAlbacore’s third patrol began on 20 January 1943.  She was patrolling in the Bismarck Archipelago.  She sank one frigate and one destroyer.  After a brief dry-docking for repairs and some refresher training, Albacore began her fourth patrol on 6 April 1943.  She sighted many convoys but scored no hits.  This patrol ended on 26 May in Brisbane.  A new captain assumed command there.\r\n\r\nHer fifth patrol began on 16 June 1943 and was in the area around the Bismarck and Solomon Islands.  She sighted a few convoys but only recorded damage to one ship.  Her sixth patrol, in generally the same area, began on 23 August 1943.  On this patrol she found a two-ship convoy and sank an auxiliary gunboat.  She pursued the other ship for two days but was only able to inflict minor damage.  This patrol ended on 26 September, also at Brisbane.\r\n\r\nAlbacore began her seventh patrol on 12 October 1943.  She received a report of a convoy that had been sighted by USS Steelhead (SS-280).  Albacore found it on 8 November.  However, she was bombed and strafed by a USAAF B-25 bomber aircraft.  Fortunately, four bombs did little damage other than forcing Albacore to lose contact with the convoy.  Two days later, she was attacked by another USAAF bomber, this time a B-24 and the damage was significant.  It took two and one-half hours to regain depth control as the boat cycled between 30 and 450 feet.  Eventually, the boat surfaced and then submerged under control to continue repairs.  Albacore was able to remain on patrol and sank a medium sized freighter.  She was then ordered to finish off a Japanese cruiser damaged by USS Scamp (SS-277).  However, Albacore was detected and depth charged for four hours.  On 25 November, Albacore sank a Japanese army transport before ending the patrol at Brisbane on 5 December.\r\n\r\nShe began her eighth patrol in the same general area on 26 December 1943.  On this patrol she sank a small freighter, the small motor gunboat it was towing and a destroyer.  Another destroyer attacked Albacore with a total of 59 depth charges.  This depth charging allowed USS Scamp (SS-277) and USS Guardfish (SS-217) to pursue three tankers and sink two of them.  A couple uneventful weeks later, Albacore ended the patrol and headed to Mare Island Naval Shipyard for a much-needed overhaul.\r\n\r\nAlbacore arrived at Pearl Harbor on 13 May and returned to action for her ninth patrol on 29 May 1944.  This time, her patrol area was west of the Marianas.  Two days after our landings on Saipan had begun, on 18 June, ADM Charles Lockwood ordered Albacore to move south 100 miles hoping to intercept the Japanese task force under Admiral Ozawa, reported to be steaming toward Saipan.\r\n\r\nThe next day, at about 08:00, Albacore found herself in the middle of the Japanese task force.  As the captain selected the second carrier he saw as his target, the torpedo data computer began to act up.  The captain decided to fire a spread of six torpedoes to compensate.  The carrier was launching an air strike and one Japanese pilot flew his plane into one of Albacore’s torpedoes.  Only one of the other torpedoes hit the IJN Taiho, a carrier.  Although that torpedo caused some damage to the largest carrier in their fleet, the Japanese were not concerned and flight operations continued.  Albacore received a depth charging as a result of the attack.\r\n\r\nTaiho operated as normal and by 11:30 had launched two more raids.  Meanwhile, damage control had been taken over by a junior officer.  He decided that the best way to clear the gasoline fumes, resulting from the single torpedo hit, was to open up the ship to vent them.  He did not understand that Taiho would become a time-bomb as a result.  At about 3:30 that afternoon, Taiho suffered a huge explosion.  The flight deck heaved up and the side blew out.  A little while later, Taiho suffered a second large explosion and sank stern first.  Albacore did not know at the time that they had sunk the carrier, albeit with the help of the Japanese damage control team.\r\n\r\nEarlier that same day, the USS Cavalla (SS-244) had sunk the IJN Shokaku, a carrier.  This was the second largest Japanese carrier.  The U. S. victory by American pilots and submarines in the Battle of the Philippine Sea, known as the Marianas Turkey Shoot, cost the Japanese two of their largest carriers and many of their front-line carrier pilots.\r\n\r\nAlbacore’s tenth patrol was in September of 1944 in the area south of Shikoku, Japan.  She sank a small freighter and a sub chaser.\r\n\r\nAlbacore was lost on her 11th war patrol.  JANAC credited her with 10 sinkings for 49,861 tons total for her WW2 service.  With the carrier, cruiser, destroyers and sub chasers to her credit, Albacore had sunk the highest tonnage of Japanese warships by any of our submarines.\r\n\r\nAlbacore received a Presidential Unit Citation for patrols 2, 3, 7 and 8.', 53, 'images/extracted/Albacore_SS-218_boat.jpg', NULL, NULL, 'images/extracted/Albacore_SS-218_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Albacore was a Gato class submarine completed by the Electric Boat Company at Groton, CT in June of 1942.'),
('8 November 1944', '1944-11-08', '85', 85, 54, 'SS-215', 'Growler', 'USS Growler (SS-215)', 'Growler was a Gato class submarine completed by the Electric Boat Company at Groton, CT in March of 1942.', 'CDR T. B. (Ben) Oakley', 'Western coast of the Philippines, the South China Sea', 'Uncertain', 'Growler departed Fremantle, Australia for her eleventh patrol on 20 October 1944.  CDR Oakley was the senior officer in command of a wolfpack that included USS Hake (SS-256) and USS Hardhead (SS-365).  On 8 November, Growler made contact with a small convoy and ordered the other boats to join the attack.  The other boats reported hearing a torpedo explosion and a number of depth charges.  After this, Growler was not heard from again, in spite of three days of searching.  Japanese records show no claims in the area at that time.  Still, it seems most likely that Growler was sunk by the IJN Shigure, a destroyer; the IJN Chiburi, an escort vessel; and the IJN CD-19, a coastal defense vessel.', 'Growler departed Pearl Harbor for her first patrol on 24 June 1942 under the command of CDR Howard Gilmore.  Her patrol area would be in the area of Dutch Harbor, Alaska.  On 5 July, she sank one Japanese destroyer and heavily damaged two more.  This patrol ended at Pearl Harbor on 17 July at Pearl Harbor.\r\n\r\nHer second patrol began on 5 August 1942.  Growler arrived off Formosa on 21 August.  Two days later she fired three torpedoes at a freighter, but they failed to explode.  Two days after that, she fired torpedoes at a passenger/cargo ship but missed.  For her efforts, Growler was the target of 53 depth charges that did little damage.  Growler then sank a gunboat, three freighters and a sampan before arriving back at Pearl Harbor on 30 September 1942.\r\n\r\nGrowler’s third patrol was in the area of the Solomon Islands.  She sighted a number of ships but was unable to attack.  She ended the patrol at Brisbane, Australia, on 10 December.\r\n\r\nGrowler’s fourth patrol began on New Year’s Day, 1943 and was in the area of the Gilberts and Palau.  She sank a freighter on 16 January.  On 30 January, she attacked a convoy but could only damage one ship before being driven deep by escorts.  On 7 February, Growler spotted what was thought to be a gunboat.  Instead, it was the new IJN Hayasaki, a supply ship.  As Growler approached for a surface attack, the supply ship spotted the submarine and turned to ram.  By now, Growler was too close for torpedoes to arm, so Gilmore ordered left rudder and rammed the supply ship amidships.  The Japanese then opened fire with machine guns, killing two and wounding two others.  Gilmore himself was hit and realized he couldn’t make it back into the boat.  He ordered “Take her down.”  Reluctantly, the executive officer complied.  Gilmore gave his life to save his boat.  For this, he would be awarded the Medal of Honor.\r\n\r\nThe XO was able to get the boat under control, in spite of the 18 feet of the bow bent at 90 degrees and the conning tower leaking water through the machine gun holes.  Growler limped into Brisbane , Australia where a whole new bow was grafted on.  Other changes and improvements were made.  LCDR Arnold Schade, the XO, would be given command of the Growler for the next three patrols.  However, the patrols were uneventful except for sinking one freighter and damaging another on the boat’s fifth patrol.  Mechanical problems caused Growler to end the seventh patrol early and head to Hunters Point in San Francisco for an overhaul.\r\n\r\nGrowler began her eighth patrol on 21 February 1944.  This patrol was plagued by bad weather.  It ended at Majuro on 16 April and the captain was transferred to new construction.\r\n\r\nGrowler’s ninth patrol, under CDR Oakley, began at Majuro on 14 May 1944.  It would be in the area off Luzon.  Growler was part of a wolfpack with the USS Seahorse (SS-304) and the USS Bang (SS-385).  She was only able to sink one small transport and damage a large tanker.\r\n\r\nFor her tenth patrol, Growler was lead in a wolfpack with the USS Sealion II (SS-315) and the USS Pampanito (SS-383) .  This was in the area of the Formosa Straits.  On 31 August, the wolfpack attacked a convoy and claimed a number of sinkings.  (Pampanito was out of position for these first attacks.)  On 12 September, the wolfpack attacked another convoy.  Growler sank a frigate and a destroyer while the rest of the pack sank a number of other vessels.  This was the patrol where Pampanito rescued 73 British and Australian soldiers who were POWs on one of the marus.  This occurred near Hainan Island.  Sealion II came to assist and rescued 54 men.  USS Barb (SS-220) and USS Queenfish (SS-393) arrived two days later and rescued 32 more soldiers.  Growler ended her tenth patrol on 26 September at Fremantle , Australia.\r\n\r\nGrowler was lost on her 11th war patrol.  JANAC credited her with 10 sinkings for 32,607 tons total for her WW2 service.\r\n\r\nGrowler was awarded a Presidential Unit Citation for patrols 1, 2, 4 and 10.', 54, 'images/extracted/Growler_SS-215_boat.jpg', NULL, NULL, 'images/extracted/Growler_SS-215_captain.jpg', 'images/extracted/Growler_SS-215_extra1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Growler was a Gato class submarine completed by the Electric Boat Company at Groton, CT in March of 1942.'),
('11 November 1944', '1944-11-11', '83', 83, 55, 'SS-277', 'Scamp', 'USS Scamp (SS-277)', 'Scamp was a Gato class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in September of 1942.', 'CDR John Hollingsworth', 'Off Tokyo Bay', 'ASW depth charges', 'Scamp began her eighth patrol from Pearl Harbor on 16 October 1944 headed for the area around the Bonin Islands.  On 9 November, she acknowledged a message changing her patrol area and indicated the fuel and torpedoes she had remaining.  She was never heard from again.  After the war, it was determined that Scamp was sighted by Japanese planes south of Tokyo Bay on 11 November.  She was then attacked by  IJN CD-4, a coastal defense vessel which dropped a total of about 70 depth charges until it was apparent Scamp was sunk.', 'Scamp left Pearl Harbor for her first war patrol on 1 March 1943.  She left Midway on 5 March, headed for the area off the island of Honshu.  On her first attack, on 16 March, the magnetic detonators caused so much trouble that the captain ordered them turned off, using the contact exploder instead.  This seemed to improve things and Scamp was able to damage two freighters before ending the patrol at Pearl Harbor on 7 April 1943.\r\n\r\nHer second patrol began on 19 April, headed for the Bismarck Archipelago.  Late on 28 May, she damaged a converted seaplane tender.  However, the captain wasn’t going to let the large target get away, and sank it the next day with two more torpedoes.  This patrol ended with no further action.  Scamp put in at Brisbane, Australia on 4 June 1943.\r\n\r\nHer third patrol was off the Solomon Islands beginning on 22 June 1943.  No potential targets were seen until 27 July, when Scamp spotted a convoy.  She fired six torpedoes at a large tanker, with two hits damaging the almost new ship.  The tanker survived, but only until 6 October when it was sunk by two other submarines.  On the afternoon of 27 October, Scamp sighted a Japanese submarine which had fired a torpedo in her direction.  Scamp evaded by going deep.  Upon returning to periscope depth, Scamp fired four torpedoes and blew up the IJN I-168.  The I-168 was the submarine that sank the carrier USS Yorktown (CV-5) and the destroyer USS Hammann (DD-412) at the Battle of Midway.  The patrol ended on 8 August at Brisbane.\r\n\r\nScamp began her fourth war patrol on 9 September 1943, again in the area of the Solomons.  She damaged an escort vessel on 18 September.  Scamp suffered minor damage herself from depth charges.  She sank a cargo ship the next day.  She later claimed another cargo ship, but this was not confirmed.  This patrol ended at Brisbane on 1 October.\r\n\r\nHer fifth patrol began on 22 October 1943 and was in the area of Truk.  On 4 November, Scamp damaged a passenger-cargo vessel with a single torpedo.  Scamp saw the damaged vessel being towed.  However, it sank a few days later while under tow.  Later, Scamp damaged a cruiser and put it out of service for a few months.  Scamp suffered some damage due to a bomb from a Japanese float plane and ended the patrol at Brisbane on 26 November.  Scamp began her sixth patrol from Brisbane on 16 December 1943.  She sank a large tanker on this patrol.  This patrol ended on 6 February 1944 with a much-needed refit at Milne Bay and a change of command.\r\n\r\nThe seventh patrol began on 3 March 1944 with orders to patrol shipping lanes between Mindanao, Palau and New Guinea.  On 4 April, she damaged a small trawler with her guns.  However, she was too vulnerable, due to jamming guns, to stay on the surface and sink the trawler.  On 7 April, Scamp sighted six cruisers with escorts.  Scamp was spotted before she could attack.  A bomb from a float plane exploded close by resulting in severe damage.  Her crew did a great job keeping the boat afloat.  Scamp limped into Seeadler Harbor, Manus on 16 April for repairs that would allow her to sail to Pearl Harbor for an overhaul.  She would be laid up for nearly six months before she was ready for her eighth patrol.\r\n\r\nScamp was lost on her eighth war patrol.  JANAC credited her with five sinkings for 34,108 tons total for her WW2 service.', 55, 'images/extracted/Scamp_SS-277_boat.jpg', NULL, NULL, 'images/extracted/Scamp_SS-277_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Scamp was a Gato class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in September of 1942.');
INSERT INTO `lost_submarines` (`date_lost`, `date_lost_sort`, `fatalities`, `fatalities_num`, `id`, `boat_number`, `name`, `designation`, `class_info`, `last_captain`, `location`, `cause`, `loss_narrative`, `prior_history`, `display_order`, `photo_boat`, `created_at`, `updated_at`, `photo_captain`, `image1`, `image1_subtitle`, `image2`, `image2_subtitle`, `image3`, `image3_subtitle`, `image4`, `image4_subtitle`, `image5`, `image5_subtitle`, `image6`, `image6_subtitle`, `image7`, `image7_subtitle`, `image8`, `image8_subtitle`, `image9`, `image9_subtitle`, `image10`, `image10_subtitle`, `construction`) VALUES
('12 January 1945', '1945-01-12', '89', 89, 56, 'SS-193', 'Swordfish', 'USS Swordfish (SS-193)', 'Swordfish was a Sargo class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in July of 1939.', 'CDR Keats Montross', 'Off Okinawa', 'Uncertain', 'After a complete overhaul, Swordfish left Pearl Harbor on 22 December 1944 for her thirteenth war patrol off Okinawa.  She was on a reconnaissance mission regarding the beaches there prior to the invasion.  On 2 January 1945, she was ordered to stay clear due to our carrier air strikes of the island.  Swordfish acknowledged the order the next day.  On 9 January, she was ordered to resume her mission.  On 12 January, Swordfish exchanged recognition signals with USS Kete (SS-369).  Four hours later, Kete heard what seemed to be a series of depth charges.  Swordfish was not heard from again.\r\n\r\nJapanese records, which were often incomplete, did not show an attack in that area at that time.  However, the area was heavily mined and it is also possible that Swordfish ran into a mine and triggered a series of explosions.', 'After post-shakedown repairs at Mare Island, Swordfish operated out of San Diego until early 1941 when she sailed to Pearl Harbor.  On 3 November 1941, Swordfish and three other submarines departed Hawaii and arrived at Manila in the Philippines on 22 November.\r\n\r\nWhen WW2 broke out in the Pacific, in December of 1941, Swordfish was still in Manila.  Her first war patrol began on 8 December, heading for the area off Hainan Island, China.  On 14 December, she claimed sinking a small freighter.  However, it was reported to have run aground and could be refloated.  On 16 December, she sank a large freighter.  On 27 December, she embarked the staff of the Submarines Asiatic Command at Manila and delivered them to Surabaya, Java.  The patrol ended there.\r\n\r\nFor Swordfish’s second patrol, she departed Surabaya on 16 January 1942 headed for the Celebes Sea.  She sank one ship and damaged another.  Then she completed two special missions.  First, she evacuated President Quezon of the Philippines, his family and some senior officers to San Jose, Panay.  Then she returned to Manila to evacuate other high-ranking officials.  The patrol ended in Fremantle , Australia on 9 March.\r\n\r\nFor her third patrol, she was to deliver 40 tons of supplies to U. S. forces on Corregidor.  However, while en route, Swordfish learned the island had been overrun by the Japanese.  She was directed to patrol in the area of Ambon Island, but there were few targets.  This patrol ended in Fremantle on 1 May 1942.\r\n\r\nOn her fourth patrol, from 15 May to 4 July 1942, Swordfish was assigned an area in the Makassar Strait.  She damaged one cargo ship and sank another.  However, the second ship had just been damaged by the USS Seal (SS-183) and that boat got the credit.  Swordfish did get credit for another sinking on this patrol.\r\n\r\nThe most notable fact about her fifth patrol was that the captain had caught a bad cold at the end of the previous patrol.  Command of the boat was temporarily given to another officer and was returned to LCDR Smith for the sixth patrol.  Neither the fifth or sixth were productive patrols.  However, Swordfish was attacked by a USAAF B-25 bomber on the sixth patrol.  Fortunately, the four bombs detonated far enough behind her so that they caused no damage.\r\n\r\nThe seventh patrol began on 19 January 1943 with a new captain.  Swordfish sank a medium-sized freighter.  On 7 February, she was cruising on the surface when she was again attacked by a friendly aircraft.  This time it was a USAAF B-17 bomber.  Swordfish did a crash dive, but the plane’s .50 caliber armor piercing shells did extensive damage to the conning tower and some systems.  The patrol was terminated at Pearl Harbor on 23 February.  The boat then proceeded to Mare Island Naval Shipyard for an overhaul.\r\n\r\nSwordfish’s eighth patrol began on 29 July 1943 at Pearl Harbor, again with a new captain.  The previous captain had been reassigned to new construction.  This patrol was essentially a transfer from Hawaii to Australia.  En route, Swordfish sank two ships and damaged another.  The patrol ended at Brisbane , Australia on 5 September 1943.\r\n\r\nThe ninth patrol, under yet another captain, was plagued with mechanical problems.  It lasted only three weeks.  After putting in at Brisbane, this captain asked to stand down, feeling that he was somehow responsible for the problems.  His request to be relieved was granted.  However, since he was considered a capable officer, he was then assigned to new construction.\r\n\r\nSwordfish’s tenth patrol began on 26 December 1943.  The new commanding officer, CAPT Karl Hensel, was a senior officer who wanted to prove some of his theories.  The patrol would be off Tokyo Bay.  Swordfish sank a passenger/cargo ship on 13 January 1944, and was then depth charged.  This resulted in extensive but minor damage.  The next day, she lost all electrical power and dove out of control.  She blew all ballast and got back to the surface.  While still working on repairs, Swordfish spotted a Japanese patrol vessel.  She submerged with only one working propeller and wasn’t spotted.  On 16 January, she sank what she thought was an ammunition ship because of the large explosion.  However, it was Japan’s first genuine Q-Ship, the Delhi Maru.  The Swordfish sank the Q-Ship with three of the recently corrected Mark 14 torpedoes.  Later, she sank a converted salvage vessel.  CAPT Hensel was satisfied with his one patrol, which ended at Pearl Harbor on 7 February 1944.  He thought the patrol included two sinkings.  However, Wikipedia claims that the tonnage was reduced but the count was raised from two sinkings to three.\r\n\r\nThe fifth new captain in five patrols, CDR Montross, took Swordfish out for her eleventh patrol near the Marianas.  She departed Pearl Harbor on 13 March 1944.  On 5 April, she damaged two cargo ships in a night surface attack, but no sinkings were confirmed at the time.  This patrol ended on 29 April at Majuro in the Marshall Islands.\r\n\r\nSwordfish’s twelfth patrol began on 22 May 1944, departing Majuro for the area of the Bonin Islands.  On 9 June, she sank a Japanese destroyer.  On 15 June, she sank a medium-sized cargo ship.  She was ordered to end the patrol at Pearl Harbor, arriving there on 30 June 1944.  She then had an extensive overhaul and did not return to sea until she began her thirteenth patrol on 22 December 1945.\r\n\r\nSwordfish was lost on her thirteenth war patrol.  JANAC credited her with 12 sinkings for 47,928 tons total for her WW2 service.\r\n\r\nSwordfish was awarded a Presidential Unit Citation for patrols 1, 2 and 4.', 56, 'images/extracted/Swordfish_SS-193_boat.jpg', NULL, NULL, 'images/extracted/Swordfish_SS-193_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Swordfish was a Sargo class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in July of 1939.'),
('4 February 1945', '1945-02-04', '81', 81, 57, 'SS-316', 'Barbel', 'USS Barbel (SS-316)', 'Barbel was a Balao class submarine completed by the Electric Boat Company at Groton, CT in April of 1944.', 'CDR Conde Raguet', 'Southwest of Palawan', 'Aircraft', 'Barbel departed from Fremantle, Australia for her fourth war patrol on 5 January 1945.  Her assigned area was in the South China Sea.  On 3 February, she reported having been attacked three times by Japanese aircraft on 31 January and 1 February.  Barbel indicated that more details would follow the next day.  Nothing was heard from Barbel after that.  Efforts by the USS Tuna (SS-203) to contact Barbel failed.\r\n\r\nJapanese aviators reported sinking a submarine on 4 February southwest of Palawan.  The report claimed that one bomb had landed near the bridge of the boat.', 'Barbel began her first war patrol at Pearl Harbor on 15 July 1944.  She stopped for fuel at Midway on 19 July, on her way to the Bonin Islands.  On 5 August, she sank a small freighter.  On 7 August, she claimed four hits on a large tanker, but this was not confirmed.  Two days later she attacked a convoy and was credited with sinking two more freighters.  This patrol ended on 21 August 1944 at Majuro.\r\n\r\nHer second patrol began on 13 September proceeding to the Nansei Shoto, also known as the Ryukyu Islands which included Okinawa.  On 25 September, she sank a freighter and damaged another.  Barbel also claimed sinking a destroyer escort but this was not confirmed.  On 13 October, she damaged a destroyer and a tanker.  On 18 October, she rendezvoused with USS Salmon (SS-182) to transfer a critically ill officer from that boat and take him to Saipan.  The patrol ended there on 24 October.\r\n\r\nBarbel’s third patrol began on 30 October after a very short refit.  This patrol was in the area around the Philippines.  On 14 November, she found a convoy and sank two medium cargo ships.  After a Japanese destroyer managed to evade a spread of six torpedoes, Barbel cleared the area and ended the patrol on 7 December 1944 at Fremantle , Australia.  This refit included a change of command.\r\n\r\nBarbel was lost on her fourth war patrol.  JANAC credited her with six sinkings for 15,263 tons total for her WW2 service.', 57, 'images/extracted/Barbel_SS-316_boat.jpg', NULL, NULL, 'images/extracted/Barbel_SS-316_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Barbel was a Balao class submarine completed by the Electric Boat Company at Groton, CT in April of 1944.'),
('Unknown, estimated between 21 and 31 March 1945', '1945-03-21', '87', 87, 58, 'SS-369', 'Kete', 'USS Kete (SS-369)', 'Kete was a Balao class submarine completed by the Manitowoc Shipbuilding Company at Manitowoc, WI in July of 1944.', 'LCDR Edward Ackerman', 'Unknown, somewhere between Okinawa and Midway', 'Unknown', 'Kete departed Guam for her second patrol on 1 March 1945.  She was assigned to the area around the Nansei Shoto.  In addition to the usual hunt for Japanese shipping, Kete was to report on the weather and stand by for lifeguard duties.  On the night of 9 to 10 March, Kete sank three cargo ships.  On the night of 14 March, she attacked what was reported to be a minelayer but with no success.  Since she had only three torpedoes left, Kete was ordered back to Pearl Harbor via Midway.  The message was acknowledged on 19 March.  Kete sent a weather report the next day.  However, she did not arrive at Midway on 31 March as expected.  Her loss could have been due to operational problems, a mine or unreported enemy action.', 'Kete’s first war patrol began at Pearl Harbor on 31 October 1944.  She reached her assigned area in the East China Sea on 4 November.  However, extreme weather and problems with her bow planes forced her to sail to Saipan for repairs.  She sailed from Saipan on 24 December and resumed her patrol on 28 December.  She provided lifeguard services from 1 January until the 27th of the month.  On 12 January, Kete tried to contact a submarine that was thought to be the USS Swordfish (SS-193).  Shortly after that, Kete heard a barrage of explosions, which is now thought to be the demise of Swordfish.  After collecting weather data, she ended the patrol at Guam on 30 January 1945.\r\n\r\nKete was lost on her second war patrol.  JANAC credited her with three sinkings for 6,881 tons total for her WW2 service.', 58, 'images/extracted/Kete_SS-369_boat.jpg', NULL, NULL, 'images/extracted/Kete_SS-369_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Kete was a Balao class submarine completed by the Manitowoc Shipbuilding Company at Manitowoc, WI in July of 1944.'),
('28 March 1945', '1945-03-28', '89', 89, 59, 'SS-237', 'Trigger', 'USS Trigger (SS-237)', 'Trigger was a Gato class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in January of 1942.', 'CDR David Connole', 'Southwest of Ibusaki in the Nansei Shoto', 'Air and ASW forces', 'Trigger left Guam on her twelfth patrol on 11 March 1945.  Her assignment was in the Nansei Shoto.  On 18 March, she sank a small cargo ship and damaged another.  On 26 March, she transmitted a weather report.  On 4 April. she was ordered back to Midway.  Trigger never acknowledged this message and did not appear at Midway as expected.\r\n\r\nJapanese records at the end of the war indicated that aircraft bombed a submarine in Trigger’s area and then called in surface vessels.  After two hours of intensive depth charging, a large pool of oil appeared, and Trigger was gone.  Japanese records also showed a repair ship had been sunk in the area the day before.  Trigger was credited with that sinking.', 'Trigger had an unfortunate start to her career.  She sailed for Hawaii on 22 May 1942.  She arrived at Pearl Harbor a week later and then sortied as part of the ring of submarines around Midway looking for the Japanese fleet prior to that battle.  However, on 6 June, Trigger ran aground on a submerged reef.  Her ballast tank was holed and the sonar heads were destroyed.  She returned to Pearl Harbor on 9 June for repairs.\r\n\r\nIt was 26 June before Trigger was ready to sail on her first war patrol in the Aleutian Islands.  Many targets were sighted but the submarine was always out of position and unable to attack.  Trigger stopped at Dutch Harbor on 8 August, and then continued on to Pearl Harbor for a refit and a change of command.\r\n\r\nHer second patrol began on 23 September 1942, from Hawaii.  Her patrol area was the waters around Japan.  On 5 October, Trigger spotted what was thought to be a small ship and planned to attack with guns on the surface.  When the target began firing and turned to ram, Trigger put two torpedoes into it to try to stop it.  It was stopped but not sunk.  On 17 October, Trigger sank a transport.  Later that day, she was spotted by a destroyer which attacked.  Trigger fired three torpedoes in a “down the throat” shot which resulted in a huge explosion.  When the smoke and spray cleared, the destroyer was still unharmed.  The assumption was that the first torpedo was a premature, and that detonated those that followed.  (This was yet another symptom of the extensive problems with our torpedoes.)  Trigger then cleared the area.  Later in the patrol, Trigger claimed damage to two more ships before the patrol ended on 8 November 1942 at Pearl Harbor.\r\n\r\nTrigger’s third patrol, which began on 3 December, was a combination minelaying and offensive patrol off the coast of Japan.  She had recently finished laying half her mines when a Japanese cargo ship, carrying aircraft, steamed through the new minefield and found one of them.  Trigger got to see the rewards of her handiwork and was credited with the sinking.  On 10 January, Trigger sank a destroyer.  The patrol ended on 22 January 1943 at Pearl Harbor.\r\n\r\nThe fourth patrol began on 9 February 1943 and would be around the Palau Islands.  On 15 March, she sank a medium transport and damaged another.  That night, Trigger again experienced torpedo problems.  She fired six torpedoes at a freighter under tow.  Five missed the target and the sixth was a circular run.  Trigger avoided the wayward torpedo by going deeper and listening as it passed over an engine room.  Trigger was able to inflict significant damage on a gunboat before the patrol ended on 6 April 1943 in Hawaii.\r\n\r\nTrigger headed out to Japanese waters for her fifth patrol on 30 April 1943.  This patrol would also be plagued with torpedo problems.  On 28 May, she damaged a small tanker.  The next day, Trigger fired three torpedoes at a freighter.  Two missed and one exploded prematurely.  She quickly fired a fourth torpedo but it was a dud.  On 1 June, she sank a small freighter.  On 10 June, Trigger had the good fortune to be in position to attack the IJN Hiyo, a carrier.  Trigger fired all six bow torpedo tubes at the carrier.  As Trigger went deep, they heard four explosions and were confident that they had sunk the carrier.  In actuality, one was a premature, one was a dud, two missed and two hit the carrier and exploded.  The Hiyo did not sink, but was out of action until the end of September of 1943.  It would eventually be sunk in June of 1944 by our carrier aircraft.\r\n\r\nWhen Trigger returned to Pearl Harbor, ADM Lockwood was furious.  He knew, from Ultra intercepts, that the Hiyo had not been sunk, but probably would have been had the torpedoes worked correctly.  ADM Lockwood then requested and received permission to turn off the magnetic exploder because of this and other incidents.\r\n\r\nTrigger’s sixth patrol was successful in spite of some continuing torpedo problems.  It began on 1 September 1943 after an overhaul and a change of command.  She was assigned to the East China Sea north of Formosa.  On the 17 September, she fired two torpedoes at a freighter.  Both hit but were duds.  Trigger tracked the vessel and sank it the next day.  On 21 September, she sighted a convoy of three tankers and three freighters.  She sank two large tankers and a large cargo ship.  She also damaged another large tanker and another cargo ship.  In the midst of the attacks, while going deep, the captain slipped and fell into the periscope well.  He supported himself on his elbows until the quartermaster heard his shouts and stopped lowering the periscope, preventing serious injury.  The patrol ended at Midway on 30 September.\r\n\r\nThe seventh war patrol began on 22 October 1943 and Trigger was assigned to the East China and Yellow Seas.  On 1 November, two transports were hit but escorts prevented confirming any sinkings and JANAC did not credit these attacks.  However, on the following day Trigger did sink a large transport and a small cargo ship.  On 5 November, she attacked a small convoy and was depth charged as a result.  Thinking the enemy had all departed, Trigger came to periscope depth and was greeted by five aircraft bombs which were near misses. On 13 November, Trigger sighted a convoy and found herself between the two columns of ships.  She had no more torpedoes in her forward tubes.  She sank a medium transport with the after tubes.  The subsequent counter-attack consisted of only five depth charges, but that was enough to damage a main motor and its reduction gear.  Trigger remained on patrol and sank a small cargo ship before ending the patrol at Pearl Harbor on 8 December.\r\n\r\nTrigger sailed for her eighth patrol on 1 January 1944.  Her patrol area was in the shipping lanes between Truk and Guam.  There were no contacts until 27 January when a Japanese RO class submarine was spotted.  Apparently, both boats were surprised; neither could get into position; no torpedoes were fired; and they sailed away from each other.  On 31 January, Trigger found a convoy and sank a large Japanese submarine depot ship.  A small minelayer was claimed but was not confirmed.  The patrol ended on 23 February 1944 in Hawaii.\r\n\r\nHer ninth patrol began on 23 March 1944 under a new captain.  Her patrol area would be in the Palau Islands.  On 8 April, Trigger found herself in a huge convoy of about 20 vessels and 25 escorts.  After firing four torpedoes, she was detected and forced to go deep.  Six escorts would keep Trigger down for 17 hours.  There was a great deal of damage.  The temperature in the boat reached 135 degrees.  At dusk, the escorts relaxed and Trigger was able to evade.  The crew made repairs and they rendezvoused with USS Tang (SS-306) for parts for the air compressors.  In the evening of 26 April, Trigger found a convoy of six ships.  In the early hours of 27 April, Trigger attacked and claimed five freighters sunk and one damaged.  JANAC credited Trigger with just one very large freighter sunk and another large cargo ship and an escort damaged.  The patrol ended at Pearl Harbor on 20 May 1944.  Four days later, Trigger was on her way to Mare Island Naval Shipyard for a complete overhaul.\r\n\r\nTrigger’s tenth patrol began on 24 September 1944, assigned to lifeguard duty off the northern coast of Formosa.  She rescued a pilot from a burning Hellcat.  On 19 October, Trigger sighted a large Japanese task force of cruisers and destroyers but was too far away to attack.  She could only report the sighting.  On 30 October, she damaged a large tanker which was sunk soon after by USS Salmon (SS-182)..  Trigger was the target of 79 depth charges but damage was minimal.  Salmon was also depth charged but her damage was severe.  She radioed for help. Trigger, the USS Silversides (SS-236) and the USS Sterlet (SS-392) responded.  Those three boats escorted Salmon to Saipan.  One week later, Trigger went back on patrol.  However, on 17 November, she was ordered to end the patrol in Guam.\r\n\r\nSalmon was so badly damaged that she did not return to combat.  She was written off as a “constructive war loss”.  She was patched up just enough to be used as a training boat.\r\n\r\nTrigger began her eleventh patrol on 28 December 1944, proceeding to the area around Bungo Suido and Kii Suido.  A submarine fired at Trigger on 3 January and Trigger cleared the area.  On 19 January 1945, she sighted a large convoy, but it was too far away for an attack.  This patrol ended at Guam on 3 February.\r\n\r\nTrigger was lost on her twelfth war patrol.  JANAC credited her with 18 sinkings for 86,552 tons total for her WW2 service.\r\n\r\nTrigger was awarded Presidential Unit Citations for patrols 5, 6, 7 and 9.', 59, 'images/extracted/Trigger_SS-237_boat.jpg', NULL, NULL, 'images/extracted/Trigger_SS-237_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Trigger was a Gato class submarine completed by the Mare Island Naval Shipyard at Vallejo, CA in January of 1942.'),
('Unknown, estimated between 8 and 20 April 1945', '1945-04-08', '84', 84, 60, 'SS-279', 'Snook', 'USS Snook (SS-279)', 'Snook was a Gato class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in October of 1942.', 'CDR John Walling', 'East of Formosa', 'Unknown', 'Snook began her ninth patrol on 25 March 1945.  She was operating as lead of a wolfpack that included USS Burrfish (SS-312) and USS Bang (SS-385).  Her orders included daily weather reports and, if requested, lifeguard duty.  Snook returned to Guam for emergency repairs on 27 March and sailed again on the next day to rejoin the wolfpack.  She provided weather reports until directed to discontinue them on 1 April.  She reported her position to USS Tigrone (SS-419) on 8 April but that boat could not raise Snook on the next day.  On 12 April, Snook was ordered to lifeguard duty in support of British carrier operations.  When an aircraft went down in her assigned sector on 20 April, Snook did not respond.  Bang rescued the three aviators and then searched for Snook without success.', 'Snook’s first patrol began on 11 April 1943 from Hawaii.  She was assigned to the area of the East China and Yellow Seas.  Her first duties were to lay 24 mines off Saddle Island near Shanghai.  That was completed on 30 April.  On 5 May, Snook sighted two freighters and tracked them.  She sank them the next day.  On the morning of 7 May, she sighted two more cargo ships and sank them.  However, credit was given for just one of these ships.  Snook claimed two more sinkings on this patrol but JANAC did not credit them.  The patrol ended on 23 May 1943 at Midway.\r\n\r\nThe second patrol began on 9 June 1943, headed to the area around the Ryukyu Islands.  On 24 June, Snook heavily damaged a large tanker.  On 4 July, she heavily damaged another transport and sank two medium marus.  This patrol ended on 18 July 1943 at Pearl Harbor.\r\n\r\nSnook sailed on 18 August 1943 for her third war patrol.  Her first assignment was lifeguard duty off Marcus Island on 1 September.  However, no rescues were needed.  After doing some photo reconnaissance, Snook then proceeded on to the East China Sea for her normal patrol.  On 13 September, she sank a large tanker with one torpedo.  On 22 September, she sank one small freighter.  She also hit another but the torpedo did not explode.  Snook attacked a small trawler on 29 September.  She sank the trawler, but four men on the Snook were injured by gunfire.  The patrol ended on 8 October 1943 at Pearl Harbor.\r\n\r\nThe fourth patrol began on 20 October.  Snook was accompanied by USS Pargo (SS-264) and USS Harder (SS-257) off the Marianas.  On 28 November, Snook along with Pargo damaged a large cargo ship.  She then sank a medium freighter, but this was not credited by JANAC.  Early the next morning, she sank a passenger/cargo ship and a cargo ship, both of which JANAC did credit.  She also damaged an escort.  After a stop at Midway, Snook ended the patrol at Pearl Harbor on 7 December 1943.\r\n\r\nSnook left Pearl Harbor on 6 January 1944 for her sixth patrol.  She was headed to the western coast of Kyushu.  While off the Bonin Islands, on 23 January, she sank a converted gunboat.  Two days later, she sank a freighter and damaged another.  The sunken vessel had been carrying Japanese troops and more than 2,700 soldiers lost their lives at sea.  The damaged vessel would be sunk by the USS Raton (SS-270) before the year was out.  With a night surface attack on 14 February, Snook sank a cargo ship.   The next day she sank a smaller ship with one torpedo.  On 23 February, while en route to Midway, she spotted a convoy.  She made a daring approach through a screen of 11 escorts and fired five torpedoes.  Two hits sank a passenger/cargo ship.  This patrol ended on 6 March 1944.\r\n\r\nSnook proceeded on to Hunters Point in San Francisco for an overhaul. Her captain, Chuck Triebel had complained often and loudly about the quality of our torpedoes.  That, and five very successful patrols, earned him a transfer to the Bureau of Ordnance to assist in development.\r\n\r\nFor her sixth patrol, Snook departed Pearl Harbor on 24 June 1944.  She fired at two freighters on 2 July 1944 but missed.  This patrol ended without sinkings on 14 August 1944 at Midway.\r\n\r\nSnook began her seventh patrol on 6 September 1944 from Midway. However, she had to stop at Saipan for repairs on 25 September.  Repairs took longer than expected and Snook didn’t sail again until 4 October 1944.  On 23 October, Snook sank three ships, first a tanker, then a large cargo ship and lastly a medium cargo ship.  On 3 November, Snook rescued a Navy pilot.  The patrol ended on 18 November 1944 at Pearl Harbor.\r\n\r\nSnook’s eighth patrol, which began on Christmas Day of 1944, was non-productive.  She was assigned to the area off Kuril Island.  The only sightings of note were two Russian vessels.  Fortunately, Snook’s captain had determined their identity before attempting an attack.  The patrol ended on 17 February 1945 at Midway.\r\n\r\nSnook was lost on her ninth war patrol.  JANAC credited her with 17 sinkings for 75,473 tons total for her WW2 service.', 60, 'images/extracted/Snook_SS-279_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Snook was a Gato class submarine completed by the Portsmouth Naval Shipyard at Kittery, Maine in October of 1942.'),
('3 May 1945', '1945-05-03', '84', 84, 61, 'SS-371', 'Lagarto', 'USS Lagarto (SS-371)', 'Lagarto was a Balao class submarine completed by the Manitowoc Shipbuilding Company at Manitowoc, WI in October of 1944.', 'CDR Frank Latta', 'Gulf of Siam', 'ASW forces', 'Lagarto’s second patrol began on 12 April 1945 from Subic Bay.  Later that month, she was ordered to patrol the Gulf of Siam along with USS Baya (SS-318).  On 2 May, Baya sent Lagarto a contact report about a large, heavily escorted tanker.  The next day, the two submarines developed a plan of attack.  However, when the day was over, Baya had been driven off and Lagarto was missing.  Japanese records contained a report of an attack on a submarine on that date in that area.  The minelayer that attacked Lagarto would be sunk before the month was out.', 'Since Lagarto was a Manitowoc boat, she went through the usual sideways launch, sea trials on Lake Michigan and the tow down the Mississippi before being fully fit out in New Orleans.  From there, she sailed through the Panama Canal and on to Hawaii.\r\n\r\nLagarto began her first patrol on 7 February 1945 in the company of USS Haddock (SS-231) and USS Sennet (SS-408).  Orders were to patrol around Nansei Shoto.  The group sank three gunboats.  On 24 February, Lagarto sank a small cargo vessel.  Strangely, she was also given credit for sinking a Japanese submarine although that submarine was never positively identified.  This patrol ended on 20 March 1945 at Subic Bay in the Philippines.\r\n\r\nIn another strange note, Lagarto was originally given credit for sinking a cargo ship on 30 June 1945, almost two months after Lagarto was sunk.\r\n\r\nLagarto was lost on her second war patrol.  JANAC credited her with two sinkings for 1,845 tons total for her WW2 service.', 61, 'images/extracted/Lagarto_SS-371_boat.jpg', NULL, NULL, 'images/extracted/Lagarto_SS-371_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Lagarto was a Balao class submarine completed by the Manitowoc Shipbuilding Company at Manitowoc, WI in October of 1944.'),
('18 June 1945', '1945-06-18', '85', 85, 62, 'SS-223', 'Bonefish', 'USS Bonefish (SS-223)', 'Bonefish was a Gato class submarine completed by the Electric Boat Company at Groton, CT in May of 1943.', 'CDR Lawrence Edge', 'Toyama Wan, Sea of Japan', 'ASW forces', 'Bonefish left Guam for her eighth war patrol on 28 May 1945 accompanied by USS Tunny (SS-282) and USS Skate (SS-305).  This wolfpack was part of the larger wolfpack of nine submarines called the Hellcats.  All of these submarines were equipped with a new FM sonar, which allowed them locate mines.  The objective was to sail through the minefields that had closed off the Sea of Japan to U. S. boats for nearly two years.  These nine submarines were an attempt to sever the last exterior supply routes that Japan had.\r\n\r\nBonefish and the other submarines in the pack entered the Sea of Japan from the south, through the Tsushima Strait.  They crept through the minefields without incident from 4 to 6 June 1945.  To enhance the element of surprise, the submarines were not to open fire until 9 June.  The plan was then to exit the Sea of Japan to the north, through the La Perouse Strait on 24 June.\r\n\r\nThe three wolfpacks were assigned to different areas in the Sea of Japan.  When they arrived, they found Japanese ships sailing straight courses and using running lights - a submariner’s dream.  After all, there had been no submarines in the area for nearly two years.  That changed quickly.  The nine American submarines sank 27 merchant ships plus one IJN submarine over the next two weeks.\r\n\r\nBonefish sank her first ship for this patrol on 13 June.  On 18 June, CDR Edge asked his pack leader for permission to sail into Toyama Bay, which was granted.  There Bonefish sank another cargo ship on 19 June.  However, the Japanese counterattack used concentrated depth charges to sink her.  Bonefish was the only boat of the nine not to make it out of the Sea of Japan.', 'After commissioning, Bonefish began by sailing to Brisbane, Australia.   She arrived there on 30 August 1943.  After additional training in Moreton Bay, her first war patrol began there on 16 September.  She topped off fuel in Darwin on the way to the Balabac Strait and then into the South China Sea.  Using “Ultra” intelligence, she caught up with a fast convoy and sank the lead ship, a large transport on 27 September.  Two cargo ships were attacked on 6 October and hits were heard.  However, neither was credited.  On 10 October, Bonefish sank a large transport plus one of medium size.  She then sank a large schooner with her deck gun before ending the patrol at Fremantle, Australia on 21 October.\r\n\r\nHer second patrol began on 22 November.  Bonefish entered the Flores Sea on 28 November.  The next day, she sank a medium cargo ship.  She sank a smaller cargo ship on 1 December and damaged an escorting destroyer.  She damaged a minelayer on 11 December with guns before ending the patrol at Fremantle on 19 December 1943.\r\n\r\nAfter Christmas in Australia, Bonefish began her third patrol on 12 January 1944.  This would take her to an area off Indo-China.  On 22 January, while passing through the Makassar Strait, Bonefish encountered a large schooner.  The crew behaved suspiciously when approached.  When Bonefish opened fire, the schooner’s crew finally went overboard.  So did 39 Japanese soldiers.  On 6 February, Bonefish found a large convoy.  She got in position and fired four torpedoes at a large tanker and two at a cargo ship.  As she turned to bring the after tubes to bear, the escorts charged.  As Bonefish went deep three hits were heard.  However, this was never confirmed.  On 9 February, Bonefish fired torpedoes at a very large tanker and had to go deep due to the escorts.  The crew thought they had heard three hits.  There were actually four hits, but the ship was able to limp away.\r\n\r\nOn the return to Australia, the captain did not want to end the patrol since he still had 13 torpedoes aboard.  However, food and fuel were running low.  Bonefish pulled in at Exmouth, Australia to replenish supplies.  Then Bonefish patrolled around Fremantle.  However, hurricane force winds for three days battered the boat and sickened the crew.  The patrol ended on 15 March 1944.\r\n\r\nBonefish’s fourth patrol began on 13 April 1944.  She was headed to an area off Mindanao in the Philippines.  On 26 April, she sank a small passenger-cargo ship in a night surface attack using radar.  She claimed damage to another smaller ship.  The next day she claimed three hits on a cargo ship but failed to sink it.  Bonefish was then ordered to the Tawi Tawi area and, en route, damaged a large freighter.  On 3 May, Bonefish approached a convoy, but two bombs and 25 depth charges drove her away.  On 14 May, Bonefish approached a convoy of three tankers and three escorts.  Two hits left one tanker in flames.  Although that tanker did not sink, one of the escorts did.  This patrol ended on 24 May 1944.\r\n\r\nFor the fifth patrol, Bonefish left Fremantle on 25 June 1944.  Beginning on 5 July, she sank four small ships with guns.  On 30 July, she sank a large tanker.  On 3 August, she damaged another tanker.  Bonefish returned to Fremantle on 13 August 1944.\r\n\r\nBonefish left Fremantle on her sixth war patrol and stopped at Darwin for fuel.  On 12 September 1944 she left Darwin headed to the area west of Luzon in the Philippines.  The successful wolfpack consisted of Bonefish, USS Flasher (SS-249) and USS Lapon (SS-260).  Bonefish sank a small tanker on 28 September.  On 10 October, she attacked a small convoy and claimed hits on two freighters.  However, the depth charging that followed prevented confirmation.  On 14 October, Bonefish sank a small freighter.  On 18 October, she picked up two Navy aviators who had been adrift for a few days.  The patrol ended on 8 November at Pearl Harbor.  Bonefish then proceeded to San Francisco for an overhaul.\r\n\r\nBonefish left Guam on 6 April 1945 for her seventh patrol.  She was headed to the East China Sea and the lower Tsushima Strait.  Hunting was poor.  For this patrol, Bonefish could only claim rescuing two Japanese fliers floating in life jackets in a large patch of oil.\r\n\r\nBonefish was lost on her eighth war patrol.  JANAC credited her with 12 sinkings for 61,345 tons total for her WW2 service.\r\n\r\nBonefish was awarded a Presidential Unit Citation for patrols 1, 3, 4, 5 and 6.', 62, 'images/extracted/Bonefish_SS-223_boat.jpg', NULL, NULL, 'images/extracted/Bonefish_SS-223_captain.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Bonefish was a Gato class submarine completed by the Electric Boat Company at Groton, CT in May of 1943.'),
('6 August 1945', '1945-08-06', '84', 84, 63, 'SS-332', 'Bullhead', 'USS Bullhead (SS-332)', 'Bullhead was a Balao class submarine completed by the Electric Boat Company at Groton, CT in December of 1944.', 'LCDR Edward Holt', 'Lombok', 'Aircraft', 'Bullhead left Fremantle, Australia on 30 July 1945 for her third patrol.  She was to operate in the Java Sea until 5 September and then proceed to Subic Bay in the Philippines.  On 6 August, Bullhead reported that she had passed through Lombok Strait.  On that day, just north of Bali, she was bombed by a Japanese aircraft.  The pilot claimed that both bombs hit Bullhead.\r\n\r\nBullhead was the 52nd and last submarine that we lost during World War 2.  Ironically, she appears to have been lost on the same day that the first atomic bomb was dropped on Hiroshima.', 'Bullhead left Pearl Harbor on 9 March 1945 for Guam.  She left that base on 21 March for her first patrol.  She was headed to the South China Sea and her primary assignment was lifeguard duty.  However, on 8 April, she had to survive a near miss by a USAAF B-24 bomber.  The three bombs dropped about 75 feet astern, which shook Bullhead quite a bit but did no major damage.  In spite of this attack, Bullhead did rescue three aviators from a USAAF B-25 bomber on 16 April.  She ended the patrol on 28 April 1945 at Subic Bay in the Philippines.\r\n\r\nHer second patrol began on 21 May 1945.  Targets were few.  Bullhead claimed five small ships in gun attacks, but none were large enough to be credited.  This patrol ended on 2 July 1945 at Fremantle , Australia.\r\n\r\nBullhead was lost on her third war patrol.  JANAC credited her with no sinkings.\r\n\r\nSection 3, Submarines Lost After WW2', 63, 'images/extracted/Bullhead_SS-332_boat.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Bullhead was a Balao class submarine completed by the Electric Boat Company at Groton, CT in December of 1944.'),
('26 August, 1949', '1949-08-26', 'Fatalities: 0.\r\nOne civilian contractor on Cochino was lost.  All 76 men from the Cochino’s crew were rescued.  However, six sailors from the Tusk were lost during the rescue.', 0, 64, 'SS-345', 'Cochino', 'USS Cochino (SS-345)', 'Cochino was a Balao class submarine completed in August of 1945 by the Electric Boat Company in Groton, CT.', 'CDR Rafael Benitez', 'Off the coast of northern Norway', 'Battery explosion and fire', 'Cochino sailed from Portsmouth, England on 12 August 1949, accompanied by the USS Tusk (SS-426), for operations in the Barents Sea above the Arctic Circle.  The plan was to return home in late August.  The boats sailed on a Cold War patrol along the Kola Peninsula in order to determine if the Soviet Union had detonated a nuclear weapon and to test new equipment in arctic weather.\r\n\r\nOn 25 August, Cochino ran into a violent polar storm.  She secured charging batteries at 05:00.  She ran submerged and then commenced snorkeling at about 10:30.  Depth control was difficult.  After a few minutes, the forward engine room reported water coming through the air induction system.  At about 10:46, the engines shut down due to a high vacuum in the boat.  Right after that, a series of muffled explosions occurred in the after battery compartment.\r\n\r\nThe explosions released hydrogen gas from the battery.  Engines were restarted to clear the smoke.  Fuel was then shut off although one engine continued to accelerate for some time due to the hydrogen.  An explosion then occurred in the after battery compartment.  Two chief petty officers managed to put out the small fires in the adjoining forward engine room.\r\n\r\nAt about 11:45, the captain ordered all excess personnel topside through the conning tower.  At 12:15, another explosion occurred in the after battery.  The captain then requested that Tusk come alongside with medical supplies and to evacuate some personnel.  They were only able to transfer the supplies.\r\n\r\nAt 14:20, one officer and the civilian technician attempted to transfer to Tusk by rubber boat.  The boat overturned, dumping them both into the water.  While Tusk was hauling them aboard, the technician received a severe head injury.  As Tusk personnel were administering artificial respiration, two huge waves washed the technician and 11 of the Tusk sailors over the side.  Only five of the Tusk sailors could be found and brought back aboard.  The other six sailors and the technician were lost.\r\n\r\nAt 16:10, Cochino’s engines stopped because the clean fuel tank ran dry.  At about 18:00, power was restored and Cochino was able to get underway for the nearest land.  At 23:06, another explosion occurred, this time probably in the forward engine room.  Around midnight, all remaining personnel were ordered topside.  Tusk managed to come alongside and began taking personnel from Cochino aboard.  At 00:43 on 26 August, the captain transferred to Tusk.  He was last to leave the Cochino.  Three minutes later, after a 14-hour battle, Cochino sank.', 'Cochino did not complete initial sea trials until after WW2 had ended.  She then operated out of Key West, FL providing training services with the Operational Development Force.  On 26 April 1948, while submerged, she collided with the fleet tug USS Salinan (ATF-161).  She suffered damage to her periscopes, periscope shears and radar mast.  She returned to the Electric Boat Company for repairs and, while there, for conversion to a GUPPY 2 boat.  That was completed on 4 February 1949.\r\n\r\nCochino then visited Boston and New London before returning to her home port at Key West.  She returned to New London, CT on 16 July 1949 and proceeded to Argentia, Newfoundland.  She arrived there on 22 July and then went on to Derry, Northern Ireland and Portsmouth England.  She would begin her last patrol from Portsmouth.', 64, 'images/extracted/Cochino_SS-345_boat.jpg', NULL, NULL, 'images/extracted/Cochino_SS-345_captain.jpg', 'images/extracted/Cochino_SS-345_extra1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cochino was a Balao class submarine completed in August of 1945 by the Electric Boat Company in Groton, CT.');
INSERT INTO `lost_submarines` (`date_lost`, `date_lost_sort`, `fatalities`, `fatalities_num`, `id`, `boat_number`, `name`, `designation`, `class_info`, `last_captain`, `location`, `cause`, `loss_narrative`, `prior_history`, `display_order`, `photo_boat`, `created_at`, `updated_at`, `photo_captain`, `image1`, `image1_subtitle`, `image2`, `image2_subtitle`, `image3`, `image3_subtitle`, `image4`, `image4_subtitle`, `image5`, `image5_subtitle`, `image6`, `image6_subtitle`, `image7`, `image7_subtitle`, `image8`, `image8_subtitle`, `image9`, `image9_subtitle`, `image10`, `image10_subtitle`, `construction`) VALUES
('29 May, 1958', '1958-05-29', '0', 0, 65, 'SS-415', 'Stickleback', 'USS Stickleback (SS-415)', 'Stickleback was a Balao class submarine completed in March of 1945 by the Mare Island Naval Shipyard in Vallejo, CA.', 'LCDR Quinly R. “Dutch” Schulz', 'Operations area near Hawaii', 'Collision', 'On 28 May 1958, Stickleback was participating in ASW exercises with the destroyer escort Silverstein.  Exercises continued into the next afternoon.  When going to a safe depth, Stickleback lost power and, with it, depth control.  She broached the surface just 200 yards ahead of the speeding USS Silverstein (DE-534).  Although the escort had backed full and put her rudder hard left, she hit Stickleback near the bulkhead between the control room and forward battery.  Although attempts were made to keep Stickleback afloat, they were futile.  However, they were effective enough to allow all of the 82-man crew to escape.', 'Stickleback completed initial outfitting on 26 May, 1945.  She then held her shakedown cruise off the California coast.  She reported to Pearl Harbor on 21 June to have more equipment installed.  She sailed to Guam, arriving there on 2 August.  She began her only war patrol on 6 August.  Stickleback had only been in the Sea of Japan for two days when the war ended.   On 21 August, she picked up 19 survivors from a Japanese ship sunk earlier by the USS Jallao (SS-368).  After providing food, water and medical treatment, the Japanese were set afloat again near one of their home islands.\r\n\r\nStickleback returned to Guam on 9 September and to San Francisco on 28 September 1945.  She was decommissioned on 26 June 1946.  She was one of more than 30 WW2 submarines decommissioned that year, some of which would be brought back into service for the Korean Conflict.  Stickleback was recommissioned on 6 September 1951 for use as a training boat off San Diego.  On 14 November 1952, she was decommissioned again, this time for conversion to a GUPPY 2A submarine.\r\n\r\nStickleback was recommissioned on 26 June 1953.  Her conversion to GUPPY 2A was completed on 9 September.  She had been reassigned to Submarine Squadron 7 and headed to Pearl Harbor on 16 September 1953.  The boat conducted drills and exercises there until departing for Yokosuka, Japan on 5  January 1954.  Stickleback arrived at her new home on 19 January.\r\n\r\nStickleback began her first Cold War patrol on 29 March 1954.  The patrol lasted four weeks.  She made contact with Soviet ships and photographed them. She returned to Pearl Harbor on 2 July and conducted training exercises in the Hawaiian Islands for the next year.\r\n\r\nOn 27 July 1955, Stickleback left Pearl Harbor on her second Cold War patrol.  The patrol included reconnaissance in the shipping lane between Cape Chaplino, Soviet Union and the Bearing Strait.  Beginning on 18 August, Stickleback sighted and photographed Soviet cruisers, naval auxiliary ships, twelve submarines, twelve submarine chasers and a submarine tender.  She completed her patrol and set course for Pearl Harbor, arriving on 19 September.  Overall, Stickleback made contact with 149 Soviet ships, including 55 naval vessels, during the nearly two-month patrol.\r\n\r\nAfter a routine overhaul Stickleback had a month of training before returning to Yokosuka on 9 March 1956.  She deployed on her third Cold War patrol on 10 May 1956.  On 23 May, Stickleback detected and recorded multiple underwater explosions.  The same day she sighted Soviet hydrographic research vessels, which led her to conclude that the explosions were likely related to hydrographic experimentation.  However, she could not get closer to investigate.  She ended the patrol in Yokosuka on 1 June.\r\n\r\nRather than returning to Pearl Harbor, Stickleback remained in Yokosuka.  She left for her fourth Cold War patrol on 24 August 1956, assigned to the shipping lanes off Petropavlovsk, Soviet Union. Over the next several weeks, she photographed and collected sonar information on 119 Soviet vessels. She ended the patrol and moored at Pearl Harbor on 10 October.\r\n\r\nOn 6 June 1957, Stickleback left for her fifth Cold War patrol. During this patrol, she returned to the Siberian coast and patrolled the shipping lanes between Petropavlovsk and Provideniya, Soviet Union. During this brief patrol, the submarine collected intelligence information on 40 Soviet ships before returning to Pearl Harbor on 26 July.  She then conducted local training operations there until she was lost in May of 1958.\r\n\r\nUSS Thresher (SSN-593).\r\n\r\nThresher was completed in August of 1961 by the Portsmouth Naval Shipyard in Kittery, Maine.  Thresher was the lead boat of its class.  However, after its loss, the class was renamed after the second boat, the USS Permit (SSN-594).\r\n\r\nLast captain: LCDR John Wesley Harvey.\r\n\r\nDate lost: 10 April 1963.\r\n\r\nLocation: 220 miles east of Cape Cod, MA.\r\n\r\nFatalities: 127.\r\n\r\nThis includes on-board observers and shipyard workers.\r\n\r\nCause: Uncertain.\r\n\r\nOn 9 April 1963, Thresher left the Portsmouth Naval Shipyard to meet with the submarine rescue ship USS Skylark (ASR-20).  She did an initial trim dive and then gradually dove to 650 feet, half her test depth.  She would then remain submerged for the evening.  She contacted Skylark the next morning to conduct deep dive testing.\r\n\r\nThresher dove deeper in 100-foot increments, testing all systems at each depth.  She was operating in circles to remain close to Skylark.  Thresher reported her course as 090 and her depth as 1,000 feet.  Communications begin to deteriorate, perhaps due to a thermocline.\r\n\r\nAs Thresher neared her test depth of 1,300 feet, Skylark received a garbled message indicating “minor difficulties, have positive up angle, attempting to blow.”  A later, even more garbled message, included the phrase “900 N”.  There were multiple possible meanings to the phrase, and it is unclear which Thresher meant.  There were no further communications from the boat.\r\n\r\nThresher lies on the ocean floor at a depth of about 8,000 feet.  By 22 July 1963, the boat had been located and photographed.\r\n\r\nPrior History:\r\n\r\nIn 1961-62, Thresher conducted lengthy sea trials to test new systems and weapons.  In November of 1961, she was in San Juan, Puerto Rico.  She was accompanied by the diesel boat USS Cavalla (SS-244).  Per the usual procedure, Thresher shut down her reactor while in port.  Her diesel engine and generator provided the power for the ship.  Several hours later, the backup generator failed, and the electrical load was shifted to the battery.  Lighting and air conditioning were shut down to preserve enough power in the battery to restart the reactor.  After about 10 hours in this configuration, the temperature in the boat reached 140 degrees.  When it became apparent that the battery would run too low, the crew tried to restart the reactor.  However, that failed when there was not enough power left in the battery.  The crew then had to borrow cables from another ship.  Cavalla started her diesels and provided enough power to Thresher to restart the reactor.\r\n\r\nThresher spent much of early 1962 evaluating systems.  She took part in various exercises.  She went to Port Canaveral, FL, for SUBROC tests.  While there, she was hit by a tug which damaged a ballast tank.  Repairs were completed by the Electric Boat Company in Connecticut.  More tests followed.\r\n\r\nOn 16 July 1962, Thresher entered the Portsmouth Naval Shipyard for a scheduled post shakedown overhaul.  However, as frequently happens with a first-in-the-class boat, this took longer than expected.  It wasn’t until 8 April 1963 that Thresher was recertified and undocked.  Next were the post-overhaul trials during which she was lost.\r\n\r\nAnalysis of the Cause:\r\n\r\nThe latest analysis indicates it was likely that a circuit failure led to a reactor shutdown.  Ice in the emergency ballast blow system then prevented Thresher from getting to the surface.  The prior theory was that the initial event was the failure of a silver brazed weld that caused electrical failures and the reactor shutdown.  However, SOSUS did not pick up any flooding noises.  Other submarines have had silver-brazed welds fail without catastrophic results.\r\n\r\nTests on another submarine of the class, while moored at a dock, confirmed the problem with ice in the emergency blow system.  The strainers, which should have been removed on Thresher, almost certainly did ice over.  That prevented the emergency blow system from functioning and doomed the Thresher.\r\n\r\nNotes:\r\n\r\nDuring the 1963 inquiry, Admiral Hyman Rickover stated:\r\n\r\n“I believe the loss of the Thresher should not be viewed solely as the result of failure of a specific braze, weld, system or component, but rather should be considered a consequence of the philosophy of design, construction and inspection that has been permitted in our naval shipbuilding programs.  I think it is important that we re-evaluate our present practices where, in the desire to make advancements, we may have forsaken the fundamentals of good engineering.”  (Cited in the Wikipedia Thresher entry)\r\n\r\nAs part of the changes due to the loss of Thresher, the SUBSAFE program was developed to enhance safety.  All nuclear-powered submarines were to go through the program.  The only submarine we have lost since then, the USS Scorpion (SSN-589), had not yet gone through the program.\r\n\r\nSurveys indicate that the nuclear fuel on Thresher is intact.  There is no significant effect on the environment.\r\n\r\nIn the late 60s, Robert Ballard, a Commander in the U. S. Navy Reserves, reached an agreement with the Navy.  The Navy would fund the surveys of the Thresher and Scorpion.  The Navy also provided the deep submersible Alvin.  Ballard could then use the Alvin to search for the Titanic, as long as the other surveys were completed first.\r\n\r\nUSS Scorpion (SSN-589).\r\n\r\nScorpion was a Skipjack class nuclear powered submarine completed in July of 1960 by General Dynamics Electric Boat in Groton, CT.\r\n\r\nLast captain: CDR Francis Slattery.\r\n\r\nDate lost: 22 May 1968.\r\n\r\nLocation: 400 nautical miles southwest of the Azores.\r\n\r\nFatalities: 99.\r\n\r\nCause: Uncertain.\r\n\r\nAfter her abbreviated overhaul in 1967, Scorpion had her emergency ballast tank blow system tagged out as unusable.  Her speed was not limited, but she was conservatively limiting her depth to 500 feet.  However, she still got underway for a Mediterranean deployment on 15 February 1968.  She operated with the 6th Fleet into May of that year.  During the deployment, Scorpion suffered various equipment failures and chronic problems.\r\n\r\nOn 16 May, after departing the Mediterranean, Scorpion stopped at Rota, Spain to drop off two crew members.  One was ill and the other had a family emergency.  On her departure, Scorpion likely provided noise cover or interference for one of our missile submarines operating from Rota.  Those departures were often monitored by Soviet trawlers or submarines trying to track our missile boats.\r\n\r\nScorpion was then directed to observe Soviet naval activities near the Azores on her way home.  After observing the Soviets, Scorpion had problems getting a message out to the base in Rota, to be forwarded to SUBLANT.  She was finally able to get the message out via a base in Greece.  Just after midnight on 21 May 1968, Scorpion reported that she was running at 15 knots at a depth of 350 feet.  She was due to return home to Norfolk at 13:00 on 27 May.\r\n\r\nOn 27 May, when Scorpion was a few hours overdue, the Navy a began a search along the route she would have taken to Norfolk.  She was declared “presumed lost” on 5 June 1968.  Aided by SOFAR and AFTAC recordings, Scorpion was located a couple months later.  (SOSUS was of no help in the acoustic search.)  Scorpion lies on the bottom, in almost 10,000 feet of water.  The wreck was photographed by the end of October of 1968.\r\n\r\nThe cause of the loss of Scorpion cannot yet be definitely determined and may never be known.  The most likely cause now appears to be a hydrogen explosion in the boat’s battery.\r\n\r\nPrior History:\r\n\r\nAfter commissioning, Scorpion left New London on 24 August 1960 for a two-month European deployment.  She operated with our 6th Fleet and NATO navies.  She returned in October and trained along the East Coast until May of 1961.\r\n\r\nIn September of 1961, she changed home port to Norfolk, VA.  Scorpion specialized in developing tactics.  From June of 1963 to May of 1964, she was in Charleston, SC for an overhaul.  She then completed a transatlantic patrol.  In the spring of 1965, she completed a similar patrol in European waters.\r\n\r\nIn 1966, she took part in special operations.  On this deployment, Scorpion is said to have entered a Soviet inland sea and filmed a missile launch.  The captain and crew received many awards and commendations.\r\n\r\nOn 1 February 1967, Scorpion entered the Norfolk Naval Shipyard for an overhaul and a nuclear refueling.  Scorpion needed a complete overhaul.  That would have included the SUBSAFE modifications which would have extended the shipyard time to as much as 36 months.  However, operational requirements could not afford to have Scorpion off-line for that long.  Operational requirements led to delays on all SUBSAFE overhauls.  As a result, the Chief of Naval Operations had already  approved the reduced scope for Scorpion’s overhaul back on 17 June 1966.\r\n\r\nAnalysis of the Cause:\r\n\r\nThere have been various theories as to the cause of the loss of Scorpion.  One of the initial estimates was that one of Scorpion’s Mark 37 electric torpedoes experienced a battery fire and that caused a torpedo explosion.  However, the lack of a bubble pulse from an explosion, along with the lack of visible damage to Scorpion, doesn’t support this theory.  In addition, it was difficult to simulate the recorded sounds with explosives during testing.  This led even the supporters of the exploding torpedo theory to doubt this possibility.\r\n\r\nAnother theory is that the Soviets torpedoed Scorpion in retaliation for what they believed was our sinking of their submarine K-129.  The damage and the lack of a bubble pulse do not support this theory either.  The difficulty in simulating the acoustic signal also casts doubt on this theory.  SOSUS tells us she was no longer near any Soviet ships when she went down.\r\n\r\nWe may never know for certain why the Scorpion was lost.  However, Bruce Rule’s book lays out the acoustic evidence that supports a battery explosion as the most likely cause.  He states that such an explosion would have killed everyone on the submarine.  (However, there are indications that a few of the engineers in the after section of the boat may have survived and tried to use the escape trunk.)  Scorpion would then have descended below crush depth and imploded.  RADM Dave Oliver, in his book “Against the Tide”, supports this theory by his experience.  Under certain conditions during a battery charge, ventilation in the battery well is restricted.  If this is near the end of the charge, when the most hydrogen is generated, the concentration of that gas can quickly rise to dangerous levels.  It is also noteworthy that battery charging procedures were changed after the loss of Scorpion.\r\n\r\nSurveys indicate that the nuclear fuel on Scorpion is intact.  There is no significant effect on the environment.', 65, 'images/extracted/Stickleback_SS-415_boat.jpg', NULL, NULL, 'images/extracted/Stickleback_SS-415_captain.jpg', 'images/extracted/Stickleback_SS-415_extra1.jpg', NULL, 'images/extracted/Stickleback_SS-415_extra2.jpg', NULL, 'images/extracted/Stickleback_SS-415_extra3.jpg', NULL, 'images/extracted/Stickleback_SS-415_extra4.jpg', NULL, 'images/extracted/Stickleback_SS-415_extra5.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Stickleback was a Balao class submarine completed in March of 1945 by the Mare Island Naval Shipyard in Vallejo, CA.');

